/* بانک آفلاین: ۴۸۰ حکمت + ۹ غرائب‌الحدیث. منبع: فایل‌های ارائه‌شده توسط مالک. توضیحات سید رضی حذف شدند. */
window.PMM_HIKMAT_ALL = [{"id":"h001","kind":"hikmat","number":1,"arabic":"قالَ عَلَيْهِ السَّلامُ: كُنْ فِى الْفِتْنَةِ كَابْنِ اللَّبُونِ؛ لا ظَهْرٌ فَيُرْكَبَ، وَ لا ضَرْعٌ فَيُحْلَبَ.","persian":"در فتنه‌ها همچون بچه‌شتر باش که نه پشتی دارد تا بر آن سوار شوند و نه پستانی تا از آن شیر بدوشند.","audio":null},{"id":"h002","kind":"hikmat","number":2,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَزْرى بِنَفْسِهِ مَنِ اسْتَشْعَرَ الطَّمَعَ، وَ رَضِىَ بِالذُّلِّ مَنْ كَشَفَ عَنْ ضُرِّهِ، وَ هانَتْ عَلَيْهِ نَفْسُهُ مَنْ اَمَّرَ عَلَيْها لِسانَهُ.","persian":"هرکس طمع را در درون خود جای دهد، خویشتن را خوار کرده است؛ هرکس گرفتاری خود را آشکار سازد، به خواری تن داده است؛ و هرکس زبانش را بر خود فرمانروا کند، ارزش خویش را از دست می‌دهد.","audio":null},{"id":"h003","kind":"hikmat","number":3,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْبُخْلُ عارٌ، وَ الْجُبْنُ مَنْقَصَةٌ، وَالْفَقْرُ يُخْرِسُ الْفَطِنَ عَنْ حُجَّتِهِ، وَ الْمُقِلُّ غَريبٌ فى بَلْدَتِهِ.","persian":"بخل ننگ است و ترسویی کاستی. تنگدستی، شخص زیرک را از بیان دلیل خود بازمی‌دارد و انسان تهیدست در شهر خویش نیز غریب است.","audio":null},{"id":"h004","kind":"hikmat","number":4,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعَجْزُ آفَةٌ، وَ الصَّبْرُ شَجاعَةٌ، وَ الزُّهْدُ ثَرْوَةٌ، وَ الْوَرَعُ جُنَّةٌ، وَ نِعْمَ الْقَرينُ الرِّضى.","persian":"ناتوانی آفت است؛ شکیبایی شجاعت است؛ بی‌رغبتی به دنیا ثروت است؛ پرهیزگاری سپر است؛ و خشنودی به آنچه خدا مقدر کرده، چه نیکو همدمی است.","audio":null},{"id":"h005","kind":"hikmat","number":5,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعِلْمُ وِراثَةٌ كَريمَةٌ، وَ الاْدابُ حُلَلٌ مُجَدَّدَةٌ، وَ الْفِكْرُ مِرْآةٌ صافِيَةٌ.","persian":"دانش، میراثی گران‌قدر است؛ آداب نیکو، جامه‌هایی نو و زیبا هستند؛ و اندیشه، آینه‌ای روشن و صاف است.","audio":null},{"id":"h006","kind":"hikmat","number":6,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: صَدْرُ الْعاقِلِ صُنْدُوقُ سِرِّهِ، وَ الْبَشاشَةُ حِبالَةُ الْمَوَدَّةِ، وَ الاِْحْتِمالُ قَبْرُ الْعُيُوبِ.","persian":"سینهٔ خردمند صندوق رازهای اوست؛ خوش‌رویی دام دوستی است؛ و بردباری، عیب‌ها را می‌پوشاند.","audio":null},{"id":"h007","kind":"hikmat","number":7,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الصَّدَقَةُ دَواءٌ مُنْجِحٌ، وَ اَعْمالُ الْعِبادِ فى عاجِلِهِمْ نُصْبُ اَعْيُنِهِمْ فى آجِلِهِمْ.","persian":"صدقه دارویی شفابخش است و کردار بندگان در این دنیا، در آخرت پیش چشم آنان خواهد بود.","audio":null},{"id":"h008","kind":"hikmat","number":8,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِعْجَبُوا لِهذَا الاِْنْسانِ، يَنْظُرُ بِشَحْم، وَ يَتَكَلَّمُ بِلَحْم، وَ يَسْمَعُ بِعَظْم، وَ يَتَنَفَّسُ مِنْ خَرْم.","persian":"از آفرینش این انسان شگفت‌زده شوید: با پیه چشم می‌بیند، با پاره‌ای گوشت سخن می‌گوید، با استخوان می‌شنود و از سوراخی نفس می‌کشد.","audio":null},{"id":"h009","kind":"hikmat","number":9,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا اَقْبَلَتِ الدُّنْيا عَلى قَوْم اَعارَتْهُمْ مَحاسِنَ غَيْرِهِمْ، وَ اِذا اَدْبَرَتْ عَنْهُمْ سَلَبَتْهُمْ مَحاسِنَ اَنْفُسِهِمْ.","persian":"هنگامی که دنیا به گروهی روی می‌آورد، خوبی‌های دیگران را به آنان عاریت می‌دهد؛ و چون از آنان روی برمی‌گرداند، خوبی‌های خودشان را نیز از ایشان می‌گیرد.","audio":null},{"id":"h010","kind":"hikmat","number":10,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: خالِطُوا النّاسَ مُخالَطَةً اِنْ مِتُّمْ مَعَها بَكَوْا عَلَيْكُمْ، وَ اِنْ عِشْتُمْ حَنُّوا اِلَيْكُمْ.","persian":"با مردم چنان معاشرت کنید که اگر از دنیا رفتید، بر شما بگریند و اگر زنده ماندید، به شما مهر بورزند.","audio":null},{"id":"h011","kind":"hikmat","number":11,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا قَدَرْتَ عَلى عَدُوِّكَ، فَاجْعَلِ الْعَفْوَ عَنْهُ شُكْراً لِلْقُدْرَةِ عَلَيْهِ.","persian":"هرگاه بر دشمن خود توانایی یافتی، گذشت از او را سپاس آن توانایی قرار بده.","audio":null},{"id":"h012","kind":"hikmat","number":12,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَعْجَزُ النّاسِ مَنْ عَجَزَ عَنِ اكْتِسابِ الاِْخْوانِ، وَ اَعْجَزُ مِنْهُ مَنْ ضَيَّعَ مَنْ ظَفِرَ بِهِ مِنْهُمْ.","persian":"ناتوان‌ترین مردم کسی است که نتواند دوستی به دست آورد؛ و ناتوان‌تر از او کسی است که دوستان به‌دست‌آمده را از دست بدهد.","audio":null},{"id":"h013","kind":"hikmat","number":13,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا وَصَلَتْ اِلَيْكُمْ اَطْرافُ النِّعَمِ، فَلاتُنَفِّرُوا اَقْصاها بِقِلَّةِ الشُّكْرِ.","persian":"هرگاه آغاز نعمت‌ها به شما رسید، با ناسپاسی اندک، ادامه و کمال آن‌ها را از خود دور نکنید.","audio":null},{"id":"h014","kind":"hikmat","number":14,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ ضَيَّعَهُ الاَْقْرَبُ، اُتيحَ لَهُ الاَْبْعَدُ.","persian":"کسی که نزدیکان او را واگذارند، چه‌بسا دورترها به یاری‌اش برخیزند.","audio":null},{"id":"h015","kind":"hikmat","number":15,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما كُلُّ مَفْتُون يُعاتَبُ.","persian":"هر گرفتارِ فتنه‌ای سزاوار سرزنش نیست.","audio":null},{"id":"h016","kind":"hikmat","number":16,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: تَذِلُّ الاُْمُورُ لِلْمَقاديرِ، حَتّى يَكُونَ الْحَتْفُ فِى التَّدْبيرِ.","persian":"کارها تابع تقدیرها هستند، تا آنجا که گاه مرگ انسان در همان تدبیر او نهفته است.","audio":null},{"id":"h017","kind":"hikmat","number":17,"arabic":"وَ سُئِلَ عَلَيْهِ السّلامُ عَنْ قَوْلِ الرَّسُولِ صَلَّى اللّهُ عَلَيْهِ وَ آلِهِ وَ سَلَّمَ: «غَيِّرُوا الشَّيْبَ، وَ لاتَشَبَّهُوا بِالْيَهُودِ» فَقالَ عَلَيْهِ السّلامُ: اِنَّما قالَ صَلَّى اللّهُ عَلَيْهِ وَآلِهِ ذلِكَ وَ الدّينُ قُلٌّ، فَاَمَّا الاْنَ وَ قَدِ اتَّسَعَ نِطاقُهُ، وَ ضَرَبَ بِجِرانِهِ، فَامْرُؤٌ وَ مَا اخْتارَ.","persian":"از امام دربارهٔ سخن پیامبر خدا (ص) پرسیدند که فرموده بود: «موی سپید را تغییر رنگ دهید و خود را به یهودیان شبیه نکنید.» امام فرمود: پیامبر این سخن را زمانی گفت که شمار پیروان دین اندک بود؛ اما اکنون که دامنهٔ اسلام گسترش یافته و استوار شده است، هرکس در این‌باره اختیار خود را دارد.","audio":null},{"id":"h018","kind":"hikmat","number":18,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فِى الَّذينَ اعْتَزَلُوا الْقِتالَ مَعَهُ: خَذَلُوا الْحَقَّ، وَ لَمْ يَنْصُرُوا الْباطِلَ.","persian":"دربارهٔ کسانی که از جنگیدن در کنار ایشان کناره گرفتند، فرمود: حق را یاری نکردند، اما باطل را نیز یاری نرساندند.","audio":null},{"id":"h019","kind":"hikmat","number":19,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ جَرى فى عِنانِ اَمَلِهِ عَثَرَ بِاَجَلِهِ.","persian":"هرکس افسار خود را به دست آرزوهایش بسپارد، به مرگ خویش برخورد می‌کند.","audio":null},{"id":"h020","kind":"hikmat","number":20,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَقيلُوا ذَوِى الْمُرُوءاتِ عَثَراتِهِمْ، فَما يَعْثُرُ مِنْهُمْ عاثِرٌ اِلاّ وَ يَدُهُ بِيَدِاللّهِ يَرْفَعُهُ.","persian":"از لغزش‌های جوانمردان درگذرید؛ زیرا هیچ‌یک از آنان نمی‌لغزد، مگر آنکه دست خدا همراه اوست و او را برمی‌خیزاند.","audio":null},{"id":"h021","kind":"hikmat","number":21,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قُرِنَتِ الْهَيْبَةُ بِالْخَيْبَةِ، وَ الْحَياءُ بِالْحِرْمانِ. وَالْفُرْصَةُ تَمُرُّ مَرَّ السَّحابِ، فَانْتَهِزُوا فُرَصَ الْخَيْرِ.","persian":"هراس با ناکامی همراه است و کم‌رویی با محرومیت. فرصت همچون ابر می‌گذرد؛ پس فرصت‌های نیک را غنیمت شمارید.","audio":null},{"id":"h022","kind":"hikmat","number":22,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَنا حَقٌّ فَاِنْ اُعْطيناهُ، وَ اِلاّ رَكِبْنا اَعْجازَ الاِْبِلِ وَ اِنْ طالَ السُّرى.","persian":"ما حقی داریم؛ اگر آن را به ما بدهند، حق خود را گرفته‌ایم؛ وگرنه، بر ترک شتران خواهیم نشست، هرچند این شب‌روی طولانی شود.","audio":null},{"id":"h023","kind":"hikmat","number":23,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَبْطَاَ بِهِ عَمَلُهُ، لَمْ يُسْرِعْ بِهِ نَسَبُهُ.","persian":"کسی که کردار او را عقب نگه دارد، نسبش او را پیش نخواهد برد.","audio":null},{"id":"h024","kind":"hikmat","number":24,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مِنْ كَفّاراتِ الذُّنُوبِ الْعِظامِ اِغاثَةُ الْمَلْهُوفِ، وَالتَّنْفيسُ عَنِ الْمَكْرُوبِ.","persian":"از کفاره‌های گناهان بزرگ، به فریاد درماندگان رسیدن و گره از اندوه گرفتاران گشودن است.","audio":null},{"id":"h025","kind":"hikmat","number":25,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يابْنَ آدَمَ، اِذا رَاَيْتَ رَبَّكَ سُبْحانَهُ يُتابعُ عَلَيْكَ نِعَمَهُ وَ اَنْتَ تَعْصيهِ فَاحْذَرْهُ.","persian":"ای فرزند آدم! هرگاه دیدی پروردگار پاک و منزهت نعمت‌هایش را پی‌درپی به تو می‌رساند، درحالی‌که تو او را نافرمانی می‌کنی، از او برحذر باش.","audio":null},{"id":"h026","kind":"hikmat","number":26,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما اَضْمَرَ اَحَدٌ شَيْئاً اِلاّ ظَهَرَ فى فَلَتاتِ لِسانِهِ وَ صَفَحاتِ وَجْهِهِ.","persian":"هیچ‌کس چیزی را در دل پنهان نمی‌کند، مگر آنکه از سخنان ناخواستهٔ زبانش و نشانه‌های چهره‌اش آشکار می‌شود.","audio":null},{"id":"h027","kind":"hikmat","number":27,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِمْشِ بِدائِكَ ما مَشى بِكَ.","persian":"تا زمانی که بیماری با تو راه می‌آید، تو نیز با آن مدارا کن.","audio":null},{"id":"h028","kind":"hikmat","number":28,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَفْضَلُ الزُّهْدِ اِخْفاءُ الزُّهْدِ.","persian":"برترین زهد آن است که زهد خود را پنهان داری.","audio":null},{"id":"h029","kind":"hikmat","number":29,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا كُنْتَ فى اِدْبار وَ الْمَوْتُ فى اِقْبال، فَما اَسْرَعَ الْمُلْتَقى!","persian":"هنگامی که عمر تو رو به پایان است و مرگ به سوی تو می‌آید، چه زود به یکدیگر خواهید رسید!","audio":null},{"id":"h030","kind":"hikmat","number":30,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَلْحَذَرَ الْحَذَرَ! فَوَاللّهِ لَقَدْ سَتَرَ، حَتّى كَاَنَّهُ قَدْ غَفَرَ.","persian":"برحذر باش، برحذر باش! به خدا سوگند، خداوند چنان پرده‌پوشی کرده است که گویی گناهان را آمرزیده است.","audio":null},{"id":"h031","kind":"hikmat","number":31,"arabic":"وَ سُئِلَ عَلَيْهِ السَّلامُ عَنِ الاِْيمانِ فَقال: الاْيمانُ عَلى اَرْبَع ِ دَعائِمَ: عَلَى الصَّبْرِ وَالْيَقينِ وَ الْعَدْلِ وَالْجِهادِ. وَالصَّبْرُ مِنْها عَلى اَرْبَع ِ شُعَب: عَلَى الشَّوْقِ وَ الشَّفَقِ وَ الزُّهْدِ وَالتَّرَقُّبِ. فَمَنِ اشْتاقَ اِلَى الْجَنَّةِ سَلا عَنِ الشَّهَواتِ. وَ مَنْ اَشْفَقَ مِنَ النّارِ اجْتَنَبَ الْمُحَرَّماتِ. وَ مَنْ زَهِدَ فِى الدُّنْيَا اسْتَهانَ بِالْمُصيباتِ. وَ مَنِ ارْتَقَبَ الْمَوْتَ سارَعَ اِلَى الْخَيْراتِ. وَ الْيَقينُ مِنْها عَلى اَرْبَع ِ شُعَب: عَلى تَبْصِرَةِ الْفِطْنَةِ، وَ تَاَوُّلِ الْحِكْمَةِ، وَ مَوْعِظَةِ الْعِبْرَةِ، وَ سُنَّةِ الاَْوَّلينَ. فَمَنْ تَبَصَّرَ فِى الْفِطْنَةِ تَبَيَّنَتْ لَهُ الْحِكْمَةُ. وَ مَنْ تَبَيَّنَتْ لَهُ الْحِكْمَةُ عَرَفَ الْعِبْرَةَ. وَمَنْ عَرَفَ الْعِبْرَةَ فَكاَنَّما كانَ فِى الاَْوَّلينَ. وَ الْعَدْلُ مِنْها عَلى اَرْبَع ِ شُعَب: عَلى غائِصِ الْفَهْمِ، وَ غَوْرِ الْعِلْمِ، وَ زُهْرَةِ الْحُكْمِ، وَ رَساخَةِ الْحِلْمِ. فَمَنْ فَهِمَ عَلِمَ غَوْرَ الْعِلْمِ. وَ مَنْ عَلِمَ غَوْرَ الْعِلْمِ صَدَرَ عَنْ شَرائِع ِ الْحُكْمِ. وَ مَنْ حَلُمَ لَمْ يُفَرِّطْ فى اَمْرِهِ وَ عاشَ فِى النّاسِ حَميداً. وَ الْجِهادُ مِنْها عَلى اَرْبَع ِ شُعَب: عَلَى الاَْمْرِ بِالْمَعْرُوفِ، وَالنَّهْىِ عَنِ الْمُنْكَرِ، وَ الصِّدْقِ فِى الْمَواطِنِ، وَ شَنَآنِ الْفاسِقينَ. فَمَنْ اَمَرَ بِالْمَعْرُوفِ شَدَّ ظُهُورَ الْمُؤْمِنينَ. وَ مَنْ نَهى عَنِ الْمُنْكَرِ اَرْغَمَ اُنُوفَ الْمُنافِقينَ. وَ مَنْ صَدَقَ فِى الْمَواطِنِ قَضى ما عَلَيْهِ. وَ مَنْ شَنِئَ الْفاسِقينَ وَ غَضِبَ لِلّهِ غَضِبَ اللّهُ لَهُ وَ اَرْضاهُ يَوْمَ الْقِيامَةِ. وَالْكُفْرُ عَلى اَرْبَع ِ دَعائِمَ: عَلَى التَّعَمُّقِ وَ التَّنازُع ِ وَ الزَّيْغ ِ وَالشِّقاقِ. فَمَنْ تَعَمَّقَ لَمْ يُنِبْ اِلَى الْحَقِّ. وَ مَنْ كَثُرَ نِزاعُهُ بِالْجَهْلِ دامَ عَماهُ عَنِ الْحَقِّ. وَ مَنْ زاغَ ساءَتْ عِنْدَهُ الْحَسَنَةُ، وَحَسُنَتْ عِنْدَهُ السَّيِّئَةُ، وَ سَكِرَ سُكْرَ الضَّلالَةِ. وَ مَنْ شاقَّ وَعُرَتْ عَلَيْهِ طُرُقُهُ، وَاَعْضَلَ عَلَيْهِ اَمْرُهُ، وَ ضاقَ عَلَيْهِ مَخْرَجُهُ. وَالشَّكُّ عَلى اَرْبَع ِ شُعَب: عَلَى التَّمارى وَ الْهَوْلِ وَالتَّرَدُّدِ وَالاِْسْتِسْلامِ. فَمَنْ جَعَلَ الْمِراءَ دَيْدَناً لَمْ يُصْبِحْ لَيْلُهُ. وَ مَنْ هالَهُ ما بَيْنَ يَدَيْهِ نَكَصَ عَلى عَقِبَيْهِ. وَ مَنْ تَرَدَّدَ فِى الرَّيْبِ وَطِئَتْهُ سَنابِكُ الشَّياطينِ. وَ مَنِ اسْتَسْلَمَ لِهَلَكَةِ الدُّنْيا وَ الاْخِرَةِ هَلَكَ فيهِما.","persian":"از امام دربارهٔ ایمان پرسیدند. فرمود: «ایمان بر چهار پایه استوار است: شکیبایی، یقین، عدالت و جهاد. شکیبایی چهار شاخه دارد: اشتیاق، بیم، زهد و انتظار. هرکس مشتاق بهشت باشد، خواهش‌های نفسانی را فراموش می‌کند؛ هرکس از آتش دوزخ بیم داشته باشد، از کارهای حرام دوری می‌کند؛ هرکس به دنیا دل نبندد، مصیبت‌ها را آسان می‌شمارد؛ و هرکس در انتظار مرگ باشد، در کارهای نیک شتاب می‌کند. یقین نیز چهار شاخه دارد: بینش هوشمندانه، دریافت حکمت، پند گرفتن از عبرت‌ها و شناخت روش پیشینیان. هرکس با هوشمندی بنگرد، حکمت برایش روشن می‌شود؛ هرکس حکمت را دریابد، عبرت را می‌شناسد؛ و هرکس عبرت‌شناس شود، گویی در میان پیشینیان زندگی کرده است. عدالت نیز چهار شاخه دارد: فهم ژرف، دانش عمیق، داوری روشن و بردباری استوار. هرکس درست بفهمد، به ژرفای دانش راه می‌یابد؛ هرکس به ژرفای دانش برسد، از سرچشمه‌های حکم درست بهره‌مند می‌شود؛ و هرکس بردبار باشد، در کار خود کوتاهی نمی‌کند و در میان مردم به نیکی زندگی می‌کند. جهاد نیز چهار شاخه دارد: فرمان دادن به نیکی، بازداشتن از بدی، راست‌گویی در جایگاه‌های دشوار و دشمنی با تبهکاران. کسی که به نیکی فرمان دهد، پشت مؤمنان را محکم می‌کند؛ کسی که از بدی بازدارد، منافقان را خوار می‌سازد؛ کسی که در جایگاه‌های دشوار راست بگوید، وظیفهٔ خود را انجام داده است؛ و کسی که با بدکاران دشمنی کند و برای خدا به خشم آید، خدا به خاطر او خشم می‌گیرد و در قیامت خشنودش می‌سازد. کفر نیز بر چهار پایه استوار است: فرو رفتن بی‌جا در امور، ستیزه‌جویی، انحراف از حق و دشمنی. کسی که به بیراههٔ ژرف‌کاوی نادرست برود، به حق بازنمی‌گردد؛ کسی که از روی نادانی بسیار جدال کند، پیوسته از دیدن حق کور می‌ماند؛ کسی که از حق منحرف شود، خوبی را بد و بدی را خوب می‌بیند و در مستی گمراهی فرو می‌رود؛ و کسی که سر ناسازگاری داشته باشد، راه‌هایش دشوار، کارش سخت و راه رهایی‌اش تنگ می‌شود. شک نیز چهار شاخه دارد: جدال، ترس، دودلی و تسلیم شدن به تباهی. هرکس جدال را عادت خود کند، شب تاریک او به صبح نمی‌رسد؛ هرکس از آنچه پیش روی اوست بترسد، به عقب بازمی‌گردد؛ هرکس در تردید بماند، زیر سم اسبان شیطان پایمال می‌شود؛ و هرکس به نابودی دنیا و آخرت تن دهد، در هر دو جهان هلاک می‌شود.»","audio":null},{"id":"h032","kind":"hikmat","number":32,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: فاعِلُ الْخَيْرِ خَيْرٌ مِنْهُ، وَ فاعِلُ الشَّرِّ شَرٌّ مِنْهُ.","persian":"انسان نیکوکار از کار نیک خود بهتر است و انسان بدکار از کار بد خود بدتر.","audio":null},{"id":"h033","kind":"hikmat","number":33,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كُنْ سَمْحاً وَ لاتَكُنْ مُبَذِّراً. وَ كُنْ مُقَدِّراً وَ لاتَكُنْ مُقَتِّراً.","persian":"بخشنده باش، اما اسراف نکن؛ در هزینه‌ها اندازه نگه دار، اما سخت‌گیر و تنگ‌نظر مباش.","audio":null},{"id":"h034","kind":"hikmat","number":34,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَشْرَفُ الْغِنى تَرْكُ الْمُنى.","persian":"برترین بی‌نیازی، رها کردن آرزوهاست.","audio":null},{"id":"h035","kind":"hikmat","number":35,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَسْرَعَ اِلَى النّاسِ بِما يَكْرَهُونَ، قالُوا فيهِ ما لايَعْلَمُونَ.","persian":"هرکس کاری را که مردم خوش نمی‌دارند با شتاب در پیش گیرد، مردم درباره‌اش چیزهایی می‌گویند که نمی‌دانند.","audio":null},{"id":"h036","kind":"hikmat","number":36,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَطالَ الاَْمَلَ اَساءَ الْعَمَلَ.","persian":"هرکس آرزوهای دراز داشته باشد، کردار خود را تباه می‌کند.","audio":null},{"id":"h037","kind":"hikmat","number":37,"arabic":"وَ قالَ عَلَيْهِ السّلامُ، وَ قَدْ لَقِيَهُ عِنْدَ مَسيرِهِ اِلَى الشّامِ دَهاقينُ الاَْنْبارِ فَتَرَجَّلُوا لَهُ وَ اشْتَدُّوا بَيْنَ يَدَيْهِ: ما هذَا الَّذى صَنَعْتُمُوهُ؟! - فَقالُوا: خُلُقٌ مِنّا نُعَظِّمُ بِهِ اُمَراءَنا. فَقالَ: وَ اللّهِ ما يَنْتَفِعُ بِهذا اُمَراؤُكُمْ، وَ اِنَّكُمْ لَتَشُقُّونَ عَلى اَنْفُسِكُمْ فى دُنْياكُمْ، وَ تَشْقَوْنَ بِهِ فى آخِرَتِكُمْ. وَ ما اَخْسَرَ الْمَشَقَّةَ وَراءَها الْعِقابُ، وَ اَرْبَحَ الدَّعَةَ مَعَها الاَْمانُ مِنَ النّارِ!","persian":"هنگامی که امام در راه شام بود، کشاورزان شهر انبار به احترام او از مرکب پیاده شدند و پیشاپیش او دویدند. امام پرسید: «این چه کاری است که می‌کنید؟» گفتند: «این رسم ماست که با آن فرمانروایانمان را بزرگ می‌داریم.» فرمود: «به خدا سوگند، فرمانروایان شما از این کار سودی نمی‌برند و شما در دنیای خود را به رنج می‌اندازید و در آخرت نیز گرفتار می‌شوید. چه زیان‌بار است رنجی که کیفر در پی داشته باشد، و چه سودمند است آسایشی که با ایمنی از آتش همراه باشد!»","audio":null},{"id":"h038","kind":"hikmat","number":38,"arabic":"وَ قالَ عَلَيْهِ السّلامُ لاِبْنِهِ الْحَسَنِ عَلَيْهِ السَّلامُ: يا بُنَىَّ، احْفَظْ عَنّى اَرْبَعاً وَ اَرْبَعاً، لايَضُرُّكَ ما عَمِلْتَ مَعَهُنَّ: اِنَّ اَغْنَى الْغِنَى الْعَقْلُ، وَ اَكْبَرَ الْفَقْرِ الْحُمْقُ، وَ اَوْحَشَ الْوَحْشَةِ الْعُجْبُ، وَ اَكْرَمَ الْحَسَبِ حُسْنُ الْخُلُقِ. يا بُنَىَّ، اِيّاكَ وَ مُصادَقَةَ الاَْحْمَقِ، فَاِنَّهُ يُريدُ اَنْ يَنْفَعَكَ فَيَضُرَّكَ. وَ اِيّاكَ وَ مُصادَقَةَ الْبَخيلِ، فَاِنَّهُ يَقْعُدُ عَنْكَ اَحْوَجَ ما تَكُونُ اِلَيْهِ. وَ اِيّاكَ وَ مُصادَقَةَ الْفاجِرِ، فَاِنَّهُ يَبيعُكَ بِالتّافِهِ. وَ اِيّاكَ وَ مَصَادَقَةَ الْكَذّابِ، فَاِنَّهُ كَالسَّرابِ، يُقَرِّبُ عَلَيْكَ الْبَعيدَ، وَ يُبَعِّدُ عَلَيْكَ الْقَريبَ.","persian":"به فرزندش حسن (ع) فرمود: «پسرم! چهار چیز و چهار چیز دیگر از من به خاطر بسپار که اگر به آن‌ها عمل کنی زیانی نمی‌بینی: بزرگ‌ترین توانگری، خرد است؛ بزرگ‌ترین تنگدستی، نادانی است؛ وحشتناک‌ترین تنهایی، خودپسندی است؛ و گرامی‌ترین حسب، خوش‌خویی است. پسرم! از دوستی با نادان بپرهیز؛ زیرا می‌خواهد به تو سود برساند، اما زیانت می‌زند. از دوستی با بخیل دوری کن؛ زیرا هنگامی که بیش از همیشه به او نیاز داری، از یاری تو خودداری می‌کند. از دوستی با بدکار بپرهیز؛ زیرا تو را به بهایی ناچیز می‌فروشد. و از دوستی با دروغگو دوری کن؛ زیرا همچون سراب، دور را برای تو نزدیک و نزدیک را دور جلوه می‌دهد.»","audio":null},{"id":"h039","kind":"hikmat","number":39,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا قُرْبَةَ بِالنَّوافِل اِذا اَضَرَّتْ بِالْفَرائِضِ.","persian":"اگر کارهای مستحب به واجبات آسیب برسانند، انجام آن‌ها موجب نزدیکی به خدا نمی‌شود.","audio":null},{"id":"h040","kind":"hikmat","number":40,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِسانُ الْعاقِلِ وَراءَ قَلْبِهِ، وَ قَلْبُ الاَْحْمَقِ وَراءَ لِسانِهِ.","persian":"زبان خردمند پشت دل اوست، اما دل نادان پشت زبان او قرار دارد.","audio":null},{"id":"h041","kind":"hikmat","number":41,"arabic":"وَ قَدْ رُوِىَ عَنْهُ عَلَيْهِ السَّلامُ هذَا الْمَعْنى بِلَفْظ آخَرَ وَ هُوَ قَوْلُهُ: قَلْبُ الاَْحْمَقِ فى فيهِ، وَ لِسانُ العاقِلِ فى قَلْبِهِ. - وَ مَعْناهُما واحِدٌ.","persian":"دل نادان در دهان اوست، اما زبان خردمند در دل اوست؛ معنای این سخن با حکمت پیشین یکسان است.","audio":null},{"id":"h042","kind":"hikmat","number":42,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِبَعْضِ اَصْحابِهِ فى عِلَّة اعْتَلَّها: جَعَلَ اللّهُ ما كانَ مِنْ شَكْواكَ حَطّاً لِسَيِّئاتِكَ، فَاِنَّ الْمَرَضَ لا اَجْرَ فيهِ وَلكِنَّهُ يَحُطُّ السَّيِّئاتِ، وَ يَحُتُّها حَتَّ الاَْوْراقِ. وَ اِنَّمَا الاَْجْرُ فِى الْقَوْلِ بِاللِّسانِ، وَ الْعَمَلِ بِالاَْيْدى وَ الاَْقْدامِ. وَ اِنَّ اللّهَ سُبحانَهُ يُدْخِلُ بِصِدقِ النِّيَّةِ وَ السَّريرَةِ الصّالِحَةِ مَنْ يَشاءُ مِنْ عِبادِهِ الْجَنَّةَ.","persian":"به یکی از یارانش که بیمار شده بود فرمود: «خداوند این بیماری را مایهٔ زدوده شدن گناهانت قرار دهد. خود بیماری پاداشی ندارد، اما گناهان را می‌ریزد، همچنان‌که برگ‌ها از درخت فرو می‌ریزند. پاداش برای گفتاری است که بر زبان جاری می‌شود و کاری که با دست و پا انجام می‌گیرد. خداوند سبحان هر بنده‌ای را که بخواهد، به سبب نیت راستین و درون پاک به بهشت درمی‌آورد.»","audio":null},{"id":"h043","kind":"hikmat","number":43,"arabic":"وَ قالَ عَلَيْهِ السّلاَمُ فى ذِكْرِ خَبّابِ بْنِ الاَْرَتِّ: يَرْحَمُ اللّهُ خَبّابَ بْنَ الاَْرَتِّ، فَلَقَدْ اَسْلَمَ راغِباً، وَ هاجَرَ طائِعاً، وَ قَنِعَ بِالْكَفافِ، وَ رَضِىَ عَنِ اللّهِ، وَ عاشَ مُجاهِداً.","persian":"خداوند خَبّاب بن اَرَت را رحمت کند؛ با رغبت اسلام آورد، از روی فرمان‌برداری هجرت کرد، به آنچه برای زندگی‌اش کافی بود قناعت ورزید، از خدا خشنود بود و زندگی خود را در جهاد گذراند.","audio":null},{"id":"h044","kind":"hikmat","number":44,"arabic":"وَ قالَ عَلَيْهِ اَلسَّلامُ: طُوبى لِمَنْ ذَكَرَ الْمَعادَ، وَ عَمِلَ لِلْحِسابِ، وَقَنِعَ بِالْكَفافِ، وَ رَضِىَ عَنِ اللّهِ.","persian":"خوشا به حال کسی که قیامت را به یاد دارد، برای حسابرسی کار می‌کند، به اندازهٔ نیاز قناعت می‌ورزد و از خدا خشنود است.","audio":null},{"id":"h045","kind":"hikmat","number":45,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَوْ ضَرَبْتُ خَيْشُومَ الْمُؤْمِنِ بِسَيْفى هذا عَلى اَنْ يُبْغِضَنى ما اَبْغَضَنى. وَ لَوْ صَبَبْتُ الدُّنْيا بِجَمّاتِها عَلَى الْمُنافِقِ عَلى اَنْ يُحِبَّنى ما اَحَبَّنى. وَ ذلِكَ اَنَّهُ قُضِىَ فَانْقَضى عَلى لِسانِ النَّبِىِّ الاُْمِّىِّ صَلَّى اللّهُ عَلَيْهِ وَ آلِهِ اَنَّهُ قالَ: «يا عَلِىُّ، لايُبْغِضُكَ مُؤْمِنٌ، وَ لايُحِبُّكَ مُنافِقٌ.»","persian":"اگر با این شمشیر بر بینی مؤمن بزنم تا مرا دشمن بدارد، دشمنم نخواهد داشت؛ و اگر همهٔ دنیا را با تمام نعمت‌هایش به منافق ببخشم تا مرا دوست بدارد، دوستم نخواهد داشت. این همان حکمی است که بر زبان پیامبر درس‌نخوانده (ص) جاری شد، آنجا که فرمود: «ای علی! هیچ مؤمنی با تو دشمنی نمی‌کند و هیچ منافقی تو را دوست نمی‌دارد.»","audio":null},{"id":"h046","kind":"hikmat","number":46,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: سَيِّئَةٌ تَسُوءُكَ خَيْرٌ عِنْدَاللّهِ مِنْ حَسَنَة تُعْجِبُكَ.","persian":"گناهی که تو را اندوهگین کند، نزد خدا از کار نیکی که تو را به خودپسندی بکشاند بهتر است.","audio":null},{"id":"h047","kind":"hikmat","number":47,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قَدْرُ الرَّجُلِ عَلى قَدْرِ هِمَّتِهِ، وَ صِدْقُهُ عَلى قَدْرِ مُرُوءَتِهِ، وَ شَجاعَتُهُ عَلى قَدْرِ اَنَفَتِهِ، وَ عِفَّتُهُ عَلى قَدْرِ غيرَتِهِ.","persian":"ارزش هرکس به اندازهٔ همت اوست؛ راستی‌اش به اندازهٔ جوانمردی او؛ شجاعتش به اندازهٔ احساس عزت و سربلندی‌اش؛ و پاک‌دامنی‌اش به اندازهٔ غیرتش.","audio":null},{"id":"h048","kind":"hikmat","number":48,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الظَّفَرُ بِالْحَزْمِ، وَ الْحَزْمُ بِاِجالَةِ الرَّأْىِ، وَ الرَّأْىُ بِتَحْصينِ الاَْسْرارِ.","persian":"پیروزی با دوراندیشی به دست می‌آید؛ دوراندیشی با بررسی و سنجش اندیشه‌ها، و اندیشهٔ درست با نگاهبانی از رازها.","audio":null},{"id":"h049","kind":"hikmat","number":49,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِحْذَرُوا صَوْلَةَ الْكَريمِ اِذا جاعَ، وَ اللَّئيمِ اِذا شَبِعَ.","persian":"از خشم و یورش انسان بزرگوار هنگامی که گرسنه است و انسان فرومایه هنگامی که سیر است بپرهیزید.","audio":null},{"id":"h050","kind":"hikmat","number":50,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قُلُوبُ الرِّجالِ وَحْشِيَّةٌ، فَمَنْ تاَلَّفَها اَقْبَلَتْ عَلَيْهِ.","persian":"دل‌های مردم رمنده‌اند؛ هرکس با آن‌ها الفت و مهربانی کند، به او روی می‌آورند.","audio":null},{"id":"h051","kind":"hikmat","number":51,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عَيْبُكَ مَسْتُورٌ ما اَسْعَدَكَ جَدُّكَ.","persian":"تا زمانی که بخت با تو یار است، عیبت پوشیده می‌ماند.","audio":null},{"id":"h052","kind":"hikmat","number":52,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَوْلَى النّاسِ بِالْعَفْوِ اَقْدَرُهُمْ عَلَى الْعُقُوبَةِ.","persian":"سزاوارترین مردم به گذشت، تواناترین آنان در مجازات کردن است.","audio":null},{"id":"h053","kind":"hikmat","number":53,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: السَّخاءُ ما كانَ ابْتِداءً، فَاَمّا ما كانَ عَنْ مَسْاَلَة فَحَياءٌ وَ تَذَمُّمٌ.","persian":"سخاوت آن است که بخشش پیش از درخواست صورت گیرد؛ اما بخششی که پس از درخواست انجام شود، از روی شرم یا پرهیز از سرزنش است.","audio":null},{"id":"h054","kind":"hikmat","number":54,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا غِنى كَالْعَقْلِ، وَ لا فَقْرَ كَالْجَهْلِ، وَلا ميراثَ كَالاَْدَبِ، وَلا ظَهيرَ كَالْمُشاوَرَةِ.","persian":"هیچ ثروتی مانند خرد، هیچ فقری مانند نادانی، هیچ میراثی مانند ادب و هیچ پشتیبانی مانند مشورت نیست.","audio":null},{"id":"h055","kind":"hikmat","number":55,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الصَّبْرُ صَبْرانِ: صَبْرٌ عَلى ما تَكْرَهُ، وَ صَبْرٌ عَمّا تُحِبُّ.","persian":"شکیبایی دو گونه است: شکیبایی بر آنچه خوش نمی‌داری و خویشتن‌داری در برابر آنچه دوست می‌داری.","audio":null},{"id":"h056","kind":"hikmat","number":56,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْغِنى فِى الْغُرْبَةِ وَطَنٌ، وَالْفَقْرُ فِى الْوَطنِ غُرْبَةٌ.","persian":"توانگری در غربت همچون وطن داشتن است، و تنگدستی در وطن همچون غربت.","audio":null},{"id":"h057","kind":"hikmat","number":57,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْقَناعَةُ مالٌ لايَنْفَدُ.","persian":"قناعت مالی است که پایان نمی‌یابد.","audio":null},{"id":"h058","kind":"hikmat","number":58,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْمالُ مادَّةُ الشَّهَواتِ.","persian":"مال، مایهٔ برانگیخته شدن خواهش‌هاست.","audio":null},{"id":"h059","kind":"hikmat","number":59,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ حَذَّرَكَ كَمَنْ بَشَّرَكَ.","persian":"کسی که تو را هشدار می‌دهد، همچون کسی است که به تو مژده می‌دهد.","audio":null},{"id":"h060","kind":"hikmat","number":60,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اللِّسانُ سَبُعٌ، اِنْ خُلِّىَ عَنْهُ عَقَرَ.","persian":"زبان درنده‌ای است که اگر آزاد گذاشته شود، آسیب می‌رساند.","audio":null},{"id":"h061","kind":"hikmat","number":61,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْمَرْاَةُ عَقْرَبٌ حُلْوَةُ اللَّسْبَةِ.","persian":"زن همچون عقربی است که نیش آن شیرین است.","audio":null},{"id":"h062","kind":"hikmat","number":62,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا حُيّيتَ بِتَحِيَّة فَحَىِّ بِاَحْسَنَ مِنْها، وَ اِذا اُسْدِيَتْ اِلَيْكَ يَدٌ فَكافِئْها بِما يُرْبى عَلَيْها، وَالْفَضْلُ مَعَ ذلِكَ لِلْبادى.","persian":"اگر به تو درود گفتند، با درودی بهتر پاسخ بده؛ و اگر کسی به تو نیکی کرد، نیکی او را با چیزی افزون‌تر جبران کن؛ بااین‌حال، برتری از آنِ کسی است که آغازگر نیکی بوده است.","audio":null},{"id":"h063","kind":"hikmat","number":63,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الشَّفيعُ جَناحُ الطّالِبِ.","persian":"میانجی، بال و پرِ کسی است که خواسته‌ای دارد.","audio":null},{"id":"h064","kind":"hikmat","number":64,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَهْلُ الدُّنْيا كَرَكْب يُسارُ بِهِمْ وَ هُمْ نِيامٌ.","persian":"دنیادوستان همچون کاروانی‌اند که آنان را می‌برند، درحالی‌که خواب‌اند.","audio":null},{"id":"h065","kind":"hikmat","number":65,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: فَقْدُ الاَْحِبَّةِ غُرْبَةٌ.","persian":"از دست دادن دوستان و عزیزان، غربت است.","audio":null},{"id":"h066","kind":"hikmat","number":66,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: فَوْتُ الْحاجَةِ اَهْوَنُ مِنْ طَلَبِها اِلى غَيْرِ اَهْلِها.","persian":"برآورده نشدن حاجت، آسان‌تر از درخواست آن از نااهل است.","audio":null},{"id":"h067","kind":"hikmat","number":67,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَسْتَح ِ مِنْ اِعْطاءِ الْقَليلِ فَاِنَّ الْحِرْمانَ اَقَلُّ مِنْهُ.","persian":"از بخشیدن اندک شرم نکن؛ زیرا محروم کردنِ دیگران از همان اندک نیز کمتر است.","audio":null},{"id":"h068","kind":"hikmat","number":68,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعَفافُ زينَةُ الْفَقْرِ، وَ الشُّكْرُ زينَةُ الْغِنى.","persian":"پاک‌دامنی زینت تنگدستی و سپاسگزاری زینت توانگری است.","audio":null},{"id":"h069","kind":"hikmat","number":69,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا لَمْ يَكُنْ ما تُريدُ فَلاتُبَلْ كَيْفَ كُنْتَ.","persian":"اگر آنچه می‌خواهی فراهم نشد، دیگر نگران چگونگی وضع خود مباش.","audio":null},{"id":"h070","kind":"hikmat","number":70,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاَ يُرَى الْجاهِلُ اِلاّ مُفْرِطاً اَوْ مُفَرِّطاً.","persian":"نادان را جز در حال زیاده‌روی یا کوتاهی نمی‌بینی.","audio":null},{"id":"h071","kind":"hikmat","number":71,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا تَمَّ الْعَقْلُ نَقَصَ الْكلامُ.","persian":"هرگاه خرد کامل شود، سخن کمتر می‌شود.","audio":null},{"id":"h072","kind":"hikmat","number":72,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الدَّهْرُ يُخْلِقُ الاَْبْدانَ، وَ يُجَدِّدُ الاْمالَ، وَ يُقَرِّبُ الْمَنِيَّةَ، وَ يُباعِدُ الاُْمْنِيَّةَ. مَنْ ظَفِرَ بِهِ نَصِبَ، وَ مَنْ فاتَهُ تَعِبَ.","persian":"روزگار بدن‌ها را فرسوده و آرزوها را تازه می‌کند؛ مرگ را نزدیک و خواسته‌ها را دور می‌سازد. هرکس به آنچه می‌خواهد برسد، به رنج می‌افتد و هرکس نرسد نیز رنج می‌برد.","audio":null},{"id":"h073","kind":"hikmat","number":73,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ نَصَبَ نَفْسَهُ لِلنّاسِ اِماماً فَعَلَيْهِ اَنْ يَبْدَأَ بِتَعْليمِ نَفْسِهِ قَبْلَ تَعْليمِ غَيْرِهِ، وَلْيَكُنْ تَأْديبُهُ بِسيرَتِهِ قَبْلَ تَأْديبِهِ بِلِسانِهِ، وَ مُعَلِّمُ نَفْسِهِ وَ مُوَدِّبُها اَحَقُّ بِالاِْجْلالِ مِنْ مُعَلِّمِ النّاسِ وَ مُوَدِّبِهِمْ.","persian":"کسی که خود را پیشوای مردم قرار می‌دهد، باید پیش از آموزش دیگران، به آموزش خود بپردازد؛ و باید پیش از آنکه با زبانش دیگران را تربیت کند، با رفتار خود آنان را پرورش دهد. کسی که خود را آموزش و پرورش می‌دهد، از کسی که فقط به آموزش و تربیت مردم می‌پردازد، سزاوارتر به بزرگداشت است.","audio":null},{"id":"h074","kind":"hikmat","number":74,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: نَفَسُ الْمَرْءِ خُطاهُ اِلى اَجَلِهِ.","persian":"هر نفسی که انسان می‌کشد، گامی به سوی پایان عمر اوست.","audio":null},{"id":"h075","kind":"hikmat","number":75,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كُلُّ مَعْدُود مُنْقَض،وَكُلُّ مُتَوَقَّع آت.","persian":"هر چیز شمارش‌پذیری سرانجام به پایان می‌رسد و هر چیز مورد انتظاری از راه خواهد رسید.","audio":null},{"id":"h076","kind":"hikmat","number":76,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ الاُْمُورَ اِذَا اشْتَبَهَتِ اعْتُبِرَ آخِرُها بِاَوَّلِها.","persian":"هنگامی که کارها مشتبه شوند، پایانشان با آغازشان سنجیده می‌شود.","audio":null},{"id":"h077","kind":"hikmat","number":77,"arabic":"وَ مِنْ خَبَرِ ضِرارِ بْنِ ضَمْرَةَ الضِّبابِىِّ عِنْدَ دُخُولِهِ عَلى مُعاوِيَةَ وَ مَسْاَلَتِهِ لَهُ عَنْ اَميرِالْمُؤْمِنِينَ عَلَيْهِ السَّلامُ، قالَ: فَاَشْهَدُ لَقَدْ رَاَيْتُهُ فى بَعْضِ مَواقِفِهِ وَ قَدْ اَرْخَى اللَّيْلُ سُدُولَهُ، وَ هُوَ قائِمٌ فى مِحْرابِهِ، قابِضٌ عَلى لِحْيَتِهِ، يَتَمَلْمَلُ تَمَلْمُلَ السَّليمِ، وَ يَبْكى بُكاءَ الْحَزينِ، وَ يَقُولُ: يا دُنْيا، يا دُنْيا، اِلَيْكِ عَنّى، اَ بى تَعَرَّضْتِ؟! اَمْ اِلَىَّ تَشَوَّقْتِ؟! لا حانَ حينُكِ، هَيْهاتَ! غُرّى غَيْرى، لاحاجَةَ لى فيكِ، قَدْ طَلَّقْتُكِ ثَلاثاً لارَجْعَةَ فيها. فَعَيْشُكِ قَصيرٌ، وَ خَطَرُكِ يَسيرٌ، وَ اَمَلُكِ حَقيرٌ. آهِ مِنْ قِلَّةِ الزّادِ، وَ طُولِ الطَّريقِ، وَ بُعْدِ السَّفَرِ، وَ عَظيمِ الْمَوْرِدِ!","persian":"در روایت ضِرار بن ضَمره آمده است که معاویه از او دربارهٔ امیرمؤمنان (ع) پرسید. ضِرار گفت: گواهی می‌دهم که شبی او را دیدم؛ شب پرده‌های تاریک خود را فرو افکنده بود و او در محراب عبادت ایستاده، محاسنش را در دست گرفته، همچون مارگزیده‌ای به خود می‌پیچید و مانند اندوهگینی می‌گریست و می‌گفت: «ای دنیا، ای دنیا! از من دور شو. آیا خود را به من عرضه می‌کنی یا مشتاق من شده‌ای؟ هرگز زمان تو فرا نرسد! دیگری را فریب بده؛ مرا به تو نیازی نیست. تو را سه‌طلاقه کرده‌ام؛ طلاقی که در آن بازگشتی نیست. عمرت کوتاه، ارزشت اندک و آرزویت ناچیز است. آه از توشهٔ کم، راه دراز، سفر دور و منزلگاه بزرگ!»","audio":null},{"id":"h078","kind":"hikmat","number":78,"arabic":"وَ مِنْ كَلام لَهُ عَلَيْهِ السّلاَمُ لِلسّائِلِ الشّامِىِّ لَمّا سَاَلَهُ: اَكانَ مَسيرُنا اِلَى الشّامِ بِقَضاء مِنَ اللّهِ وَ قَدَر؟ بَعْدَ كَلام طَويل هذا مُخْتارُهُ: وَ يْحَكَ! لَعَلَّكَ ظَنَنْتَ قَضاءًلازِماً وَ قَدَراً حاتِماً؟!وَ لَوْ كانَ ذلِكَ كَذلِكَ لَبَطَلَ الثَّوابُ وَالْعِقابُ، وَسَقَطَ الْوَعْدُ وَالْوَعيدُ. اِنَّ اللّهَ سُبْحانَهُ اَمَرَ عِبادَهُ تَخْييراً، وَ نَهاهُمْ تَحْذيراً، وَ كَلَّفَ يَسيراً، وَلَمْ يُكَلِّفْ عَسيراً، وَ اَعْطى عَلَى الْقَليلِ كَثيراً، وَ لَمْ يُعْصَ مَغْلُوباً، وَ لَمْ يُطَعْ مُكْرِهاً، وَ لَمْ يُرْسِلِ الاَْنْبِياءَ لَعِباً، وَ لَمْ يُنْزِلِ الْكُتُبَ لِلْعِبادِ عَبَثاً، وَ لا خَلَقَ السَّمواتِ وَالاَْرْضَ وَ ما بَيْنَهُما باطِلاً، «ذلِكَ ظَنُّ الَّذينَ كَفَرُوا،فَوَيْلٌ لِلَّذينَ كَفَرُوا مِنَ النّارِ».","persian":"مردی از مردم شام از امام پرسید: «آیا حرکت ما به سوی شام به قضا و قدر خدا بود؟» امام در بخشی از پاسخ بلند خود فرمود: «وای بر تو! شاید گمان کرده‌ای قضا و قدر، امری الزام‌آور و حتمی است که اختیار انسان را از میان می‌برد. اگر چنین بود، پاداش و کیفر بی‌معنا می‌شد و وعده و هشدار الهی از میان می‌رفت. خداوند سبحان بندگانش را با داشتن اختیار فرمان داده و برای هشدار دادن از کارهایی بازداشته است. تکالیف آسان بر عهدهٔ آنان گذاشته، نه تکالیف طاقت‌فرسا؛ در برابر کار اندک، پاداش بسیار داده است. او از سر ناتوانی نافرمانی نمی‌شود و کسی از روی اجبار فرمانش را نمی‌برد. پیامبران را بیهوده نفرستاده و کتاب‌ها را برای بندگان بی‌هدف فرو نفرستاده و آسمان‌ها و زمین و آنچه میان آن دو است را باطل نیافریده است: «این گمان کسانی است که کافر شدند؛ پس وای بر کافران از آتش.»»","audio":null},{"id":"h079","kind":"hikmat","number":79,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: خُذِ الْحِكْمَةَ اَنّى كانَتْ، فَاِنَّ الْحِكْمَةَ تَكُونُ فى صَدْرِ الْمُنافِقِ فَتَلَجْلَجُ فى صَدْرِهِ حَتّى تَخْرُجَ فَتَسْكُنَ اِلى صَواحِبِها فى صَدْرِ الْمُؤْمِنِ.","persian":"حکمت را هرجا که باشد فراگیر؛ زیرا گاه حکمت در سینهٔ منافق نیز جای می‌گیرد، اما در آنجا آرام نمی‌یابد تا بیرون آید و در کنار همتایانش در سینهٔ مؤمن قرار گیرد.","audio":null},{"id":"h080","kind":"hikmat","number":80,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى مِثْلِ ذلِكَ: الْحِكْمَةُ ضالَّةُ الْمُؤْمِنِ، فَخُذِ الْحِكْمَةَ وَ لَوْ مِنْ اَهْلِ النِّفاقِ.","persian":"حکمت گمشدهٔ مؤمن است؛ پس آن را به دست آور، هرچند نزد منافقان باشد.","audio":null},{"id":"h081","kind":"hikmat","number":81,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قيمَةُ كُلِّ امْرِئ ما يُحْسِنُهُ.","persian":"ارزش هر انسانی به اندازهٔ کاری است که آن را نیکو انجام می‌دهد.","audio":null},{"id":"h082","kind":"hikmat","number":82,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اُوصيكُمْ بِخَمْس لَوْ ضَرَبْتُمْ اِلَيْها آباطَ الاِْبِلِ لَكانَتْ لِذلِكَ اَهْلاً: لايَرْجُوَنَّ اَحَدٌ مِنْكُمْ اِلاّ رَبَّهُ، وَ لايَخافَنَّ اِلاّ ذَنْبَهُ، وَ لايَسْتَحِيَنَّ اَحَدٌ مِنْكُمْ اِذا سُئِلَ عَمّا لايَعْلَمُ اَنْ يَقُولَ لااَعْلَمُ، وَ لايَسْتَحِيَنَّ اَحَدٌ اِذا لَمْ يَعْلَمِ الشَّىْءَ اَنْ يَتَعَلَّمَهُ. وَ عَلَيْكُمْ بِالصَّبْرِ، فَاِنَّ الصَّبْرَ مِنَ الاْيمانِ كَالرَّأْسِ مِنَ الْجَسَدِ، وَ لاخَيْرَ فى جَسَد لارَأْسَ مَعَهُ، وَ لا فى ايمان لاصَبْرَ مَعَهُ.","persian":"شما را به پنج چیز سفارش می‌کنم که اگر برای به دست آوردنشان راه دوری را با شتران بپیمایید، سزاوار است: هیچ‌یک از شما جز به پروردگارش امید نبندد و جز از گناه خود نترسد. اگر از چیزی پرسیدند که نمی‌داند، از گفتنِ «نمی‌دانم» شرم نکند و اگر چیزی را نمی‌داند، از آموختن آن خجالت نکشد. و بر شما باد شکیبایی؛ زیرا شکیبایی برای ایمان همچون سر برای تن است؛ نه تنی بی‌سر ارزشی دارد و نه ایمانی بی‌شکیبایی.","audio":null},{"id":"h083","kind":"hikmat","number":83,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِرَجُل اَفْرَطَ فِى الثَّناءِ عَلَيْهِ، وَ كانَ لَهُ مُتَّهِماً: اَنَا دُونَ ما تَقُولُ، وَ فَوْقَ ما فى نَفْسِكَ.","persian":"به مردی که در ستایش او زیاده‌روی کرد، اما به صداقت او بدگمان بود، فرمود: من از آنچه بر زبان می‌آوری پایین‌ترم و از آنچه در دل داری بالاترم.","audio":null},{"id":"h084","kind":"hikmat","number":84,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: بَقِيَّةُ السَّيْفِ اَبْقى عَدَداً، وَ اَكْثَرُ وَلَداً.","persian":"بازماندگان از جنگ، شمارشان پایدارتر و فرزندانشان بیشتر است.","audio":null},{"id":"h085","kind":"hikmat","number":85,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ تَرَكَ قَوْلَ «لا اَدْرى» اُصيبَتْ مَقاتِلُهُ.","persian":"هرکس گفتنِ «نمی‌دانم» را ترک کند، خویشتن را در معرض هلاکت قرار می‌دهد.","audio":null},{"id":"h086","kind":"hikmat","number":86,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رَأْىُ الشَّيْخ ِ اَحَبُّ اِلَىَّ مِنْ جَلَدِ الْغُلامِ.","persian":"اندیشه و تدبیر پیرمرد را از دلیری جوان بیشتر دوست دارم.","audio":null},{"id":"h087","kind":"hikmat","number":87,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عَجِبْتُ لِمَنْ يَقْنَطُ وَ مَعَهُ الاِْسْتِغْفارُ.","persian":"در شگفتم از کسی که با داشتن راه استغفار، نومید می‌شود.","audio":null},{"id":"h088","kind":"hikmat","number":88,"arabic":"وَ حَكى عَنْهُ اَبُوجَعْفَر مُحَمَّدُ بْنُ عَلِىٍّ الْباقِرُ عَلَيْهِمَاالسّلامُ اَنَّهُ قالَ: كانَ فِى الاَْرْضِ اَمانانِ مِنْ عَذابِ اللّهِ، وَ قَدْ رُفِعَ اَحَدُهُما فَدُونَكُمُ الاْخَرَ، فَتَمَسَّكُوا بِهِ. اَمَّا الاَْمانُ الَّذى رُفِعَ فَهُوَ رَسُولُ اللّهِ صَلَّى اللّهُ عَلَيْهِ وَ آلِهِ. وَ اَمَّا الاَْمانُ الْباقى فَالاِْسْتِغْفارُ، قالَ اللّهُ تَعالى: «وَ ما كانَ اللّهُ لِيُعَذِّبَهُمْ وَ اَنْتَ فيهِمْ، وَ ما كانَ اللّهُ مُعَذِّبَهُمْ وَ هُمْ يَسْتَغْفِرُونَ».","persian":"امام محمد باقر (ع) از امیرمؤمنان (ع) روایت کرده است که فرمود: «در زمین دو امان از عذاب خدا وجود داشت؛ یکی از آن دو برداشته شده است، پس دیگری را دریابید و به آن چنگ بزنید. امانی که برداشته شد، وجود پیامبر خدا (ص) بود؛ و امانی که باقی مانده، آمرزش‌خواهی است. خداوند متعال فرمود: «خدا تا زمانی که تو در میان آنان هستی عذابشان نمی‌کند و تا زمانی که آمرزش می‌طلبند نیز عذابشان نخواهد کرد.»»","audio":null},{"id":"h089","kind":"hikmat","number":89,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَصْلَحَ ما بَيْنَهُ وَ بَيْنَ اللّهِ، اَصْلَحَ اللّهُ ما بَيْنَهُ وَ بَيْنَ النّاسِ. وَ مَنْ اَصْلَحَ اَمْرَ آخِرَتِهِ، اَصْلَحَ اللّهُ لَهُ اَمْرَ دُنْياهُ. وَ مَنْ كانَ لَهُ مِنْ نَفْسِهِ واعِظٌ كانَ عَلَيْهِ مِنَ اللّهِ حافِظٌ.","persian":"هرکس رابطهٔ خود با خدا را اصلاح کند، خدا رابطهٔ او با مردم را اصلاح می‌کند؛ و هرکس کار آخرت خویش را سامان دهد، خدا کار دنیای او را سامان می‌دهد؛ و کسی که در درون خود پنددهنده‌ای داشته باشد، از سوی خدا نگهبانی خواهد داشت.","audio":null},{"id":"h090","kind":"hikmat","number":90,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْفَقيهُ كُلُّ الْفَقيهِ مَنْ لَمْ يُقَنِّطِ النّاسَ مِنْ رَحْمَةِ اللّهِ، وَ لَمْ يُؤْيِسْهُمْ مِنْ رَوْح ِ اللّهِ، وَ لَمْ يُؤْمِنْهُمْ مِنْ مَكْرِ اللّهِ.","persian":"فقیهِ حقیقی کسی است که مردم را از رحمت خدا نومید نکند، آنان را از لطف خدا مأیوس نسازد و از کیفر خدا ایمن نگرداند.","audio":null},{"id":"h091","kind":"hikmat","number":91,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ هذِهِ الْقُلُوبَ تَمَلُّ كَما تَمَلُّ الاَْبْدانُ، فَابْتَغُوا لَها طَرائِفَ الْحِكَمِ.","persian":"این دل‌ها نیز همچون بدن‌ها خسته می‌شوند؛ پس برای آسودگی و نشاط آن‌ها، سخنان حکمت‌آمیز و تازه بجویید.","audio":null},{"id":"h092","kind":"hikmat","number":92,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَوْضَعُ الْعِلْمِ ما وَقَفَ عَلَى اللِّسانِ، وَ اَرْفَعُهُ ما ظَهَرَ فِى الْجَوارِح ِ وَ الاَْرْكانِ.","persian":"کم‌ارزش‌ترین دانش آن است که تنها بر زبان بماند و برترین دانش آن است که آثارش در رفتار و اندام انسان آشکار شود.","audio":null},{"id":"h093","kind":"hikmat","number":93,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايَقُولَنَّ اَحَدُكُمْ: «اللَّهُمَّ اِنّى اَعُوذُ بِكَ مِنَ الْفِتْنَةِ» لاَِنَّهُ لَيْسَ اَحَدٌ اِلاّ وَ هُو مُشْتَمِلٌ عَلى فِتْنَة. وَلكِنْ مَنِ اسْتَعاذَ فَلْيَسْتَعِذْ مِنْ مُضِلاّتِ الْفِتَنِ، فَاِنَّ اللّهَ سُبْحانَهُ يَقُولُ: «وَ اعْلَمُوا اَنَّما اَمْوالُكُمْ وَ اَوْلادُكُمْ فِتْنَةٌ». وَ مَعْنى ذلِكَ اَنَّهُ سُبْحانَهُ يَخْتَبِرُهُمْ بِالاَْمْوالِ وَ الاَْوْلادِ لِيَتَبَيَّنَ السّاخِطَ لِرِزْقِهِ وَالرّاضِىَ بِقِسْمِهِ، وَ اِنْ كانَ سُبْحانَهُ اَعْلَمَ بِهِمْ مِنْ اَنْفُسِهِمْ، وَلكِنْ لِتَظْهَرَ الاَْفْعالُ الَّتى بِها يُسْتَحَقُّ الثَّوابُ وَالْعِقابُ، لاَِنَّ بَعْضَهُمْ يُحِبُّ الذُّكُورَ وَ يَكْرَهُ الاِْناثَ، وَ بَعْضَهُمْ يُحِبُّ تَثْميرَ الْمالِ وَ يَكْرَهُ انْثِلامَ الْحالِ.","persian":"هیچ‌یک از شما نگوید: «خدایا، از آزمایش به تو پناه می‌برم»؛ زیرا هیچ‌کس نیست که آزموده نشود. اما هرکس می‌خواهد از خدا پناه بخواهد، باید از فتنه‌هایی که موجب گمراهی می‌شوند به او پناه ببرد. خداوند سبحان می‌فرماید: «بدانید که اموال و فرزندانتان وسیلهٔ آزمایش‌اند.» معنایش این است که خدا انسان‌ها را با اموال و فرزندانشان می‌آزماید تا روشن شود چه کسی از روزیِ او ناخشنود و چه کسی به سهم خود راضی است. هرچند خداوند از خودِ آنان به آنان آگاه‌تر است، آزمایش برای آشکار شدن کردارهایی است که پاداش یا کیفر به دنبال دارند؛ زیرا برخی پسر را دوست می‌دارند و دختر را ناخوش می‌شمارند، و برخی افزایش مال را دوست دارند و از کاهش آن ناراحت می‌شوند.","audio":null},{"id":"h094","kind":"hikmat","number":94,"arabic":"وَ سُئِلَ عَلَيْهِ السَّلامُ عَنِ الْخَيْرِ ما هُوَ؟ فَقالَ: لَيْسَ الْخَيْرَ اَنْ يَكْثُرَ مالُكَ وَ وَلَدُكَ، وَلكِنَّ الْخَيْرَ اَنْ يَكْثُرَ عِلْمُكَ، وَ اَنْ يَعْظُمَ حِلْمُكَ، وَاَنْ تُباهِىَ النّاسَ بِعِبادَةِ رَبِّكَ، فَاِنْ اَحْسَنْتَ حَمِدْتَ اللّهَ، وَ اِنْ اَسأْتَ اسْتَغْفَرْتَ اللّهَ. وَ لاخَيْرَ فِى الدُّنْيا اِلاّ لِرَجُلَيْنِ: رَجُل اَذْنَبَ ذُنُوباً فَهُوَ يَتَدارَكُها بِالتَّوْبَةِ، وَ رَجُل يُسارِعُ فِى الْخَيْراتِ.","persian":"هنگامی که از امام پرسیدند «خیر چیست؟» فرمود: «خیر در فراوان شدن مال و فرزند نیست؛ خیر آن است که دانشت افزون شود، بردباری‌ات بیشتر گردد و به بندگی پروردگارت افتخار کنی. اگر کار نیکی کردی، خدا را سپاس بگویی و اگر بد کردی، از او آمرزش بخواهی. در دنیا خیر نیست مگر برای دو نفر: کسی که گناهانی کرده و با توبه آن‌ها را جبران می‌کند، و کسی که برای انجام کارهای نیک شتاب می‌ورزد.»","audio":null},{"id":"h095","kind":"hikmat","number":95,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايَقِلُّ عَمَلٌ مَعَ التَّقْوى، وَ كَيْفَ يَقِلُّ ما يُتَقَبَّلُ؟!","persian":"عملی که با پرهیزگاری همراه باشد اندک نیست؛ و چگونه ممکن است عملی که نزد خدا پذیرفته شده است، اندک باشد؟","audio":null},{"id":"h096","kind":"hikmat","number":96,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اَوْلَى النّاسِ بِالاَْنْبِياءِ اَعْلَمُهُمْ بِما جاءُوا بِهِ. - ثُمَّ تَلا عَلَيْهِ السَّلامُ: «اِنَّ اَوْلَى النّاسِ بِاِبْراهيمَ لَلَّذينَ اتَّبَعُوهُ وَ هذَا النَّبِىُّ وَالَّذينَ آمَنُوا.» - ثُمَّ قالَ: اِنَّ وَلِىَّ مُحَمَّد مَنْ اَطاعَ اللّهَ وَ اِنْ بَعُدَتْ لُحْمَتُهُ، وَ اِنَّ عَدُوَّ مُحَمَّد مَنْ عَصَى اللّهَ وَ اِنْ قَرُبَتْ قَرابَتُهُ.","persian":"نزدیک‌ترین مردم به پیامبران کسانی‌اند که به آنچه پیامبران آورده‌اند داناترند. سپس این آیه را تلاوت کرد: «سزاوارترین مردم به ابراهیم، کسانی‌اند که از او پیروی کردند و نیز این پیامبر و کسانی که ایمان آورده‌اند.» سپس فرمود: «دوست محمد (ص) کسی است که خدا را اطاعت کند، هرچند پیوند خویشاوندی‌اش با پیامبر دور باشد؛ و دشمن محمد (ص) کسی است که خدا را نافرمانی کند، هرچند نزدیک‌ترین خویشاوند او باشد.»","audio":null},{"id":"h097","kind":"hikmat","number":97,"arabic":"وَقَدْ سَمِعَ عَلَيْهِ السَّلامُ رَجُلاً مِنَ الْحَرُورِيَّةِ، يَتَهَجَّدُ وَ يَقْرَاُ، فَقالَ: نَوْمٌ عَلى يَقين خَيْرٌ مِنْ صَلاة فى شَكٍّ.","persian":"چون شنید مردی از خوارج نماز شب می‌خواند و قرآن تلاوت می‌کند، فرمود: خوابیدن با یقین، از نماز خواندن با تردید بهتر است.","audio":null},{"id":"h098","kind":"hikmat","number":98,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِعْقِلُوا الْخَبَرَ اِذا سَمِعْتُمُوهُ عَقْلَ رِعايَة لا عَقْلَ رِوايَة، فَاِنَّ رُواةَ الْعِلْمِ كَثيرٌ، وَ رُعاتَهُ قَليلٌ.","persian":"آنچه می‌شنوید، با فهم و رعایت کردن حفظ کنید، نه تنها با نقل کردن؛ زیرا روایت‌کنندگان دانش بسیارند، اما عمل‌کنندگان به آن اندک.","audio":null},{"id":"h099","kind":"hikmat","number":99,"arabic":"وَ قَدْ سَمِعَ عَلَيْهِ السَّلامُ رَجُلاً يَقُولُ: «اِنّا لِلّهِ وَ اِنّا اِلَيْهِ راجِعُونَ»، فَقالَ: اِنَّ قَوْلَنا: «اِنّا لِلّهِ» اِقْرارٌ عَلى اَنْفُسِنا بِالْمُلْكِ، وَ قَوْلَنا: «وَ اِنّا اِلَيْهِ راجِعُونَ» اِقْرارٌ عَلى اَنْفُسِنا بِالْهُلْكِ.","persian":"هنگامی که شنید مردی می‌گوید «إِنّا لِلّهِ وَإِنّا إِلَیْهِ راجِعُونَ»، فرمود: گفتنِ «ما از آنِ خداییم» اعتراف به فرمانروایی او بر ماست، و گفتنِ «به سوی او بازمی‌گردیم» اعتراف به فناپذیری ماست.","audio":null},{"id":"h100","kind":"hikmat","number":100,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ وَ قَدْ مَدَحَهُ قَوْمٌ فى وَجْهِهِ: اللّهُمَّ اِنَّكَ اَعْلَمُ بِى مِنْ نَفْسى، وَ اَنَا اَعْلَمُ بِنَفْسى مِنْهُمْ. اللّهُمَّ اجْعَلْنا خَيْراً مِمّا يَظُنُّونَ، وَ اغْفِرْلَنا ما لايَعْلَمُونَ.","persian":"هنگامی که گروهی در حضورش او را ستودند، فرمود: خدایا، تو از خودِ من به من آگاه‌تری و من از آنان به خود آگاه‌ترم. خدایا، ما را از آنچه درباره‌مان می‌پندارند بهتر قرار ده و آنچه را از ما نمی‌دانند بر ما ببخش.","audio":null},{"id":"h101","kind":"hikmat","number":101,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايَسْتَقيمُ قَضاءُ الْحَوائِج ِ اِلاّ بِثَلاث: بِاسْتِصْغارِها لِتَعْظُمَ، وَ بِاسْتِكْتامِها لِتَظْهَرَ، وَ بِتَعْجيلِها لِتَهْنَاَ.","persian":"برآوردن نیازها تنها با سه چیز به کمال می‌رسد: کوچک شمردن آن کار تا نزد خدا بزرگ شود، پنهان داشتنش تا آشکار گردد و شتاب در انجامش تا برای نیازمند گوارا باشد.","audio":null},{"id":"h102","kind":"hikmat","number":102,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَأْتى عَلَى النّاسِ زَمانٌ لايُقَرَّبُ فيهِ اِلاَّ الْماحِلُ، وَ لايُظَرَّفُ فيهِ اِلاَّ الْفاجِرُ، وَ لايُضَعَّفُ فيهِ اِلاَّ الْمُنْصِفُ. يَعُدُّونَ الصَّدَقَةَ فيهِ غُرْماً، وَصِلَةَ الرَّحِمِ مَنّاً، وَالْعِبادَةَ اسْتِطالَةً عَلَى النّاسِ. فَعِنْدَ ذلِكَ يَكُونُ السُّلْطانُ بِمَشُورَةِ الاِْماءِ، وَ اِمارَةِ الصِّبْيانِ، وَ تَدْبيرِ الْخِصْيانِ.","persian":"روزگاری بر مردم فرا می‌رسد که جز سخن‌چین را به خود نزدیک نمی‌کنند، جز بدکار را خوش‌مشرب نمی‌دانند و جز فرد باانصاف را ناتوان نمی‌شمارند. یاری رساندن به نیازمندان را زیان، پیوند با خویشاوندان را منت‌گذاشتن و عبادت خدا را وسیلهٔ برتری‌جویی بر مردم می‌دانند. در آن زمان، حکومت با مشورت زنانِ خدمتکار، فرمانروایی کودکان و تدبیر خواجگان اداره می‌شود.","audio":null},{"id":"h103","kind":"hikmat","number":103,"arabic":"وَ قَدْ رُئِىَ عَلَيْهِ اِزارٌ خَلَقٌ مَرْقُوعٌ، فَقيلَ لَهُ فى ذلِكَ فَقالَ: يَخْشَعُ لَهُ الْقَلْبُ، وَ تَذِلُّ بِهِ النَّفْسُ، وَ يَقْتَدى بِهِ الْمُؤْمِنُونَ. اِنَّ الدُّنْيا وَ الاْخِرَةَ عَدُوّانِ مُتَفاوِتانِ، وَ سَبيلانِ مُخْتَلِفانِ، فَمَنْ اَحَبَّ الدُّنْيا وَ تَوَلاّها اَبْغَضَ الاْخِرَةَ وَ عاداها. وَ هُما بِمَنْزِلَةِ الْمَشْرِقِ وَالْمَغْرِبِ، وَ ماش بَيْنَهُما، كُلَّما قَرُبَ مِنْ واحِد بَعُدَ مِنَ الاْخَرِ، وَ هُما بَعْدُ ضَرَّتانِ.","persian":"هنگامی که جامه‌ای کهنه و وصله‌دار بر تن امام دیدند و دربارهٔ آن پرسیدند، فرمود: «این جامه دل را فروتن و نفس را رام می‌کند و مؤمنان از آن پیروی می‌کنند. دنیا و آخرت دو دشمن متفاوت و دو راه جداگانه‌اند. کسی که دنیا را دوست بدارد و به آن دل ببندد، آخرت را دشمن خواهد داشت. دنیا و آخرت مانند شرق و غرب‌اند؛ رهرو هرچه به یکی نزدیک‌تر شود، از دیگری دورتر می‌شود. این دو مانند دو زنِ همسرِ یک مردند که با یکدیگر ناسازگارند.»","audio":null},{"id":"h104","kind":"hikmat","number":104,"arabic":"وَ عَنْ نَوْف الْبِكالِىِّ، قالَ: راَيْتُ اَميرَالْمُؤْمِنينَ عَلَيْهِ السّلامُ ذاتَ لَيْلَة وَ قَدْ خَرَجَ مِنْ فِراشِهِ، فَنَظَرَ فِى النُّجُومِ، فَقالَ لى: يا نَوْفُ! اَ راقِدٌ اَنْتَ اَمْ رامِقٌ؟ فَقُلْتُ: بَلْ رامِقٌ يا اَميرَالْمُؤْمِنينَ، قالَ: يا نَوْفُ طَوبى لِلزّاهِدينَ فِى الدُّنْيا، الرّاغِبينَ فِى الاْخِرَةِ. اُولئِكَ قَوْمٌ اتَّخَذُوا الاَْرْضَ بِساطاً، وَ تُرابَها فِراشاً، وَ ماءَها طيباً، وَالْقُرْآنَ شِعاراً، وَالدُّعاءَ دِثاراً، ثُمَّ قَرَضُوا الدُّنْيا قَرْضاً عَلى مِنْهاج ِ الْمَسيح ِ! يا نَوْفُ، اِنَّ داوُدَ عَلَيْهِ السَّلامُ قامَ فى مِثْلِ هذِهِ السّاعَةِ مِنَ اللَّيْلِ، فَقالَ: اِنَّها ساعَةٌ لايَدْعُو فيها عَبْدٌ اِلاَّ اسْتُجيبَ لَهُ، اِلاّ اَنْ يَكُونَ عَشّاراً، اَوْ عَريفاً، اَوْ شُرْطِيّاً، اَوْ صاحِبَ عَرْطَبَة - وَ هِىَ الطُّنْبُورُ- اَوْ صاحِبَ كُوبَة - وَ هِىَ الطَّبْلُ.","persian":"نَوف بَکالی روایت کرد: شبی امیرمؤمنان (ع) را دیدم که از بستر برخاست، به ستارگان نگریست و به من گفت: «ای نوف، خوابی یا بیدار؟» گفتم: «بیدارم، ای امیرمؤمنان.» فرمود: «ای نوف، خوشا به حال کسانی که به دنیا دل نبستند و مشتاق آخرت‌اند. آنان زمین را فرش، خاکش را بستر و آبش را نوشیدنی خود قرار دادند؛ قرآن را جامهٔ درونی و دعا را جامهٔ بیرونی خود ساختند و همانند عیسی مسیح از دنیا بریدند. ای نوف، داوود (ع) در چنین ساعتی از شب برخاست و گفت: این ساعتی است که هر بنده‌ای در آن دعا کند، دعایش مستجاب می‌شود؛ مگر باج‌گیر، جاسوسِ حاکم ستمگر، مأمورِ ستمگر و نوازندهٔ ابزارهای لهو.»","audio":null},{"id":"h105","kind":"hikmat","number":105,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اللّهَ افْتَرَضَ عَلَيْكُمُ الْفَرائِضَ فَلاتُضَيِّعُوها، وَ حَدَّ لَكُمْ حُدُوداً فَلاتَعْتَدُوها، وَ نَهاكُمْ عَنْ اَشْياءَ فَلاتَنْتَهِكُوها، وَ سَكَتَ لَكُمْ عَنْ اَشْياءَ وَ لَمْ يَدَعْها نِسْياناً فَلاتَتَكَلَّفُوها.","persian":"خداوند واجباتی را بر شما مقرر کرده است؛ آن‌ها را تباه نکنید. حدودی تعیین کرده است؛ از آن‌ها فراتر نروید. از چیزهایی بازتان داشته است؛ حرمتشان را نشکنید. و دربارهٔ چیزهایی سکوت کرده است، نه از روی فراموشی؛ پس خود را در آن‌ها به تکلف نیندازید.","audio":null},{"id":"h106","kind":"hikmat","number":106,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايَتْرُكُ النّاسُ شَيْئاً مِنْ اَمْرِ دينِهِمْ لاِسْتِصْلاح ِ دُنْياهُمْ، اِلاّ فَتَحَ اللّهُ عَلَيْهِمْ ما هُوَ اَضَرُّ مِنْهُ.","persian":"مردم هیچ بخشی از امور دین خود را برای سامان دادن به دنیایشان رها نمی‌کنند، مگر آنکه خدا چیزی زیان‌بارتر از آن را در برابرشان می‌گشاید.","audio":null},{"id":"h107","kind":"hikmat","number":107,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رُبَّ عالِم قَدْ قَتَلَهُ جَهْلُهُ، وَ عِلْمُهُ مَعَهُ لايَنْفَعُهُ.","persian":"چه‌بسا دانایی که نادانی‌اش او را به هلاکت رساند و دانشش، با آنکه همراه اوست، سودی به حالش نداشته باشد.","audio":null},{"id":"h108","kind":"hikmat","number":108,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَقَدْ عُلِّقَ بِنِياطِ هذَا الاِْنْسانِ بَضْعَةٌ هِىَ اَعْجَبُ ما فيهِ وَ ذلِكَ الْقَلْبُ، وَ لَهُ مَوادٌّ مِنَ الْحِكْمَةِ، وَ اَضْدادٌ مِنْ خِلافِها. فَاِنْ سَنَحَ لَهُ الرَّجاءُ اَذَلَّهُ الطَّمَعُ، وَ اِنْ هاجَ بِهِ الطَّمَعُ اَهْلَكَهُ الْحِرْصُ، وَ اِنْ مَلَكَهُ الْيَأْسُ قَتَلَهُ الاَْسَفُ، وَ اِنْ عَرَضَ لَهُ الْغَضَبُ اشْتَدَّ بِهِ الْغَيْظُ، وَ اِنْ اَسْعَدَهُ الرِّضى نَسِىَ التَّحَفُّظَ، وَ اِنْ غالَهُ الْخَوْفُ شَغَلَهُ الْحَذَرُ، وَ اِنِ اتَّسَعَ لَهُ الاَْمْنُ اسْتَلَبَتْهُ الْغِرَّةُ، وَ اِنْ اَفادَ مالاً اَطْغاهُ الْغِنى، وَ اِنْ اَصابَتْهُ مُصيبَةٌ فَضَحَهُ الْجَزَعُ، وَ اِنْ عَضَّتْهُ الْفاقَةُ شَغَلَهُ الْبَلاءُ، وَ اِنْ جَهَدَهُ الْجُوعُ قَعَدَ بِهِ الضَّعْفُ، وَ اِنْ اَفْرَطَ بِهِ الشِّبَعُ كَظَّتْهُ الْبِطْنَةُ، فَكُلُّ تَقْصير بِهِ مُضِرٌّ، وَ كُلُّ اِفْراط لَهُ مُفْسِدٌ.","persian":"به راستی، در درون این انسان پاره‌گوشتی به رگی آویخته است که شگفت‌انگیزترین عضو اوست و آن، دل است. در دل، سرچشمه‌هایی از حکمت و نیز حالت‌هایی مخالف آن وجود دارد. هرگاه امید در آن پدید آید، طمع خوارش می‌کند؛ اگر طمع برانگیخته شود، حرص هلاکش می‌سازد؛ اگر نومیدی بر او چیره شود، اندوه از پایش درمی‌آورد؛ اگر خشم به او روی آورد، تندی او شدت می‌یابد؛ اگر خشنودی یاری‌اش کند، جانب احتیاط را فراموش می‌کند؛ اگر ترس ناگهانی بر او چیره شود، پرهیز و نگرانی سرگرمش می‌کند؛ اگر احساس امنیت کند، غفلت او را می‌رباید؛ اگر مالی به دست آورد، ثروت سرکشش می‌کند؛ اگر مصیبتی برسد، بی‌تابی رسوایش می‌سازد؛ اگر تنگدستی او را بفشارد، گرفتاری سرگرمش می‌کند؛ اگر گرسنگی بر او سخت گیرد، ناتوانی زمین‌گیرش می‌سازد؛ و اگر در سیری زیاده‌روی کند، پری شکم آزارش می‌دهد. پس هر کمبودی به او زیان می‌رساند و هر زیاده‌روی‌ای تباهش می‌کند.","audio":null},{"id":"h109","kind":"hikmat","number":109,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: نَحْنُ النُّمْرُقَةُ الْوُسْطى، بِها يَلْحَقُ التّالى، وَ اِلَيْها يَرْجِعُ الْغالى.","persian":"ما جایگاه میانه‌ایم که عقب‌ماندگان باید به ما برسند و تندروان باید به سوی ما بازگردند.","audio":null},{"id":"h110","kind":"hikmat","number":110,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايُقيمُ اَمْرَ اللّهِ سُبْحانَهُ اِلاّ مَنْ لايُصانِعُ، وَ لا يُضارِعُ، وَ لايَتَّبِعُ الْمَطامِعَ.","persian":"فرمان خدا را جز کسی برپا نمی‌دارد که سازش‌کاری نکند، خواری نپذیرد و از طمع‌ها پیروی نکند.","audio":null},{"id":"h111","kind":"hikmat","number":111,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ وَ قَدْ تُوُفِّى سَهْلُ بْنُ حُنَيْف الاَْنْصارِىُّ بِالْكُوفَةِ بَعْدَ مَرْجِعِهِ مِنْ صِفِّينَ مَعَهُ، وَ كانَ مِنْ اَحَبِّ النّاسِ اِلَيْهِ: لَوْ اَحَبَّنى جَبَلٌ لَتَهافَتَ.","persian":"هنگامی که سهل بن حُنَیف انصاری، که از عزیزترین یاران امام بود، پس از بازگشت از صفین در کوفه درگذشت، امام فرمود: اگر کوهی مرا دوست بدارد، از هم فرو می‌ریزد.","audio":null},{"id":"h112","kind":"hikmat","number":112,"arabic":"مَنْ اَحْبَّنا اَهْلَ الْبَيْتِ فَلْيَسْتَعِدَّ لِلْفَقْرِ جِلْباباً.","persian":"هرکس ما اهل‌بیت را دوست می‌دارد، باید جامهٔ تنگدستی را برای خود آماده کند.","audio":null},{"id":"h113","kind":"hikmat","number":113,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا مالَ اَعْوَدُ مِنَ الْعَقْلِ، وَ لا وَحْدَةَ اَوْحَشُ مِنَ الْعُجْبِ، وَ لا عَقْلَ كالتَّدْبيرِ، وَ لا كَرَمَ كَالتَّقْوى، وَ لاقَرينَ كَحُسْنِ الْخُلْقِ، وَ لا ميراثَ كَالاَْدَبِ، وَ لاقائِدَ كَالتَّوْفيقِ، وَ لاتِجارَةَ كَالْعَمَلِ الصّالِح ِ، وَ لارِبْحَ كَالثَّوابِ، وَ لا وَرَعَ كَالْوُقُوفِ عِنْدَ الشُّبْهَةِ، وَ لا زُهْدَ كَالزُّهْدِ فِى الْحَرامِ، وَ لا عِلْمَ كَالتَّفَكُّرِ، وَ لا عِبادَةَ كَاَداءِ الْفَرائِضِ، وَ لا ايمانَ كَالْحَياءِ وَ الصَّبْرِ، وَ لا حَسَبَ كَالتَّواضُع ِ، وَلا شَرَفَ كَالْعِلْمِ، وَ لا عِزَّ كَالْحِلْمِ، وَ لا مُظاهَرَةَ اَوْثَقُ مِنَ الْمُشاوَرَةِ.","persian":"هیچ مالی سودمندتر از خرد، هیچ تنهایی هراس‌انگیزتر از خودپسندی، هیچ خردی مانند تدبیر، هیچ بزرگواری مانند پرهیزگاری، هیچ همدمی مانند خوش‌خویی، هیچ میراثی مانند ادب، هیچ راهنمایی مانند توفیق، هیچ تجارتی مانند کردار شایسته، هیچ سودی مانند پاداش الهی، هیچ پارسایی مانند درنگ کردن در شبهه‌ها، هیچ زهدی مانند پرهیز از حرام، هیچ دانشی مانند اندیشیدن، هیچ عبادتی مانند انجام واجبات، هیچ ایمانی مانند شرم و شکیبایی، هیچ بزرگواری خانوادگی مانند فروتنی، هیچ شرافتی مانند دانش، هیچ عزتی مانند بردباری و هیچ پشتیبانی مطمئن‌تر از مشورت نیست.","audio":null},{"id":"h114","kind":"hikmat","number":114,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذَا اسْتَوْلَى الصَّلاحُ عَلَى الزَّمانِ وَ اَهْلِهِ ثُمَّ اَساءَ رَجُلٌ الظَّنَّ بِرَجُل لَمْ تَظْهَرْ مِنْهُ خَزْيَةٌ فَقَدْ ظَلَمَ. وَ اِذَا اسْتَوْلَى الْفَسادُ عَلَى الزَّمانِ وَ اَهْلِهِ فَاَحْسَنَ رَجُلٌ الظَّنَّ بِرَجُل فَقَدْ غَرَّرَ.","persian":"هرگاه نیکی بر مردم روزگار چیره باشد، کسی که بی‌آنکه از دیگری بدی دیده باشد به او بدگمان شود، ستم کرده است؛ و هرگاه بدی بر مردم چیره باشد، کسی که به دیگری خوش‌گمان شود، خود را فریب داده است.","audio":null},{"id":"h115","kind":"hikmat","number":115,"arabic":"وَقيلَ لَهُ عَلَيْهِ السَّلامُ: كَيْفَ تَجِدُكَ يا اَميرَالْمُؤْمِنينَ؟ فَقالَ عَلَيْهِ السّلامُ: كَيْفَ يَكُونُ حالُ مَنْ يَفْنى بِبَقائِهِ، وَ يَسْقَمُ بِصِحَّتِهِ، وَ يُؤْتى مِنْ مَأْمَنِهِ؟!","persian":"وقتی از او پرسیدند «حال خود را چگونه می‌بینی؟» فرمود: حال کسی چگونه است که با زنده‌ماندنش به سوی نابودی می‌رود، با سلامتش در معرض بیماری قرار می‌گیرد و مرگ از جایی که گمان ایمنی دارد به سراغش می‌آید؟","audio":null},{"id":"h116","kind":"hikmat","number":116,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَمْ مِنْ مُسْتَدْرَج بِالاِْحْسانِ اِلَيْهِ، وَ مَغْرُور بِالسَّتْرِ عَلَيْهِ، وَ مَفْتُون بِحُسْنِ الْقَوْلِ فيهِ. وَ مَا ابْتَلَى اللّهُ اَحَداً بِمِثْلِ الاِْمْلاءِ لَهُ.","persian":"چه بسیار کسان که با نیکی‌هایی که به آنان می‌شود، به‌تدریج گرفتار می‌گردند؛ با پوشیده ماندن گناهانشان فریب می‌خورند؛ و با ستایش دیگران دچار فتنه می‌شوند. خداوند سبحان هیچ‌کس را به چیزی مانند مهلت دادن به او نیازموده است.","audio":null},{"id":"h117","kind":"hikmat","number":117,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: هَلَكَ فِىَّ رَجُلانِ: مُحِبٌّ غال، وَ مُبْغِضٌ قال.","persian":"دو گروه دربارهٔ من به هلاکت می‌افتند: دوستدارِ افراط‌گر و دشمنِ کینه‌توز.","audio":null},{"id":"h118","kind":"hikmat","number":118,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِضاعَةُ الْفُرْصَةِ غُصَّةٌ.","persian":"از دست دادن فرصت، مایهٔ اندوه است.","audio":null},{"id":"h119","kind":"hikmat","number":119,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَثَلُ الدُّنْيا كَمَثَلِ الْحَيَّةِ، لَيِّنٌ مَسُّها، وَ السَّمُّ النّاقِعُ فى جَوْفِها. يَهْوى اِلَيْهَا الْغِرُّ الْجاهِلُ، وَ يَحْذَرُها ذُواللُّبِّ الْعاقِلُ.","persian":"دنیا همچون مار است: لمس آن نرم و دلپذیر، اما درونش زهر کشنده دارد. فریب‌خوردهٔ نادان به آن روی می‌آورد و خردمند هوشیار از آن دوری می‌کند.","audio":null},{"id":"h120","kind":"hikmat","number":120,"arabic":"وَ سُئِلَ عَلَيْهِ السّلامُ: عَنْ قُرَيْش فَقالَ: اَمّا بَنُومَخْزُوم فَرَيْحانَةُ قَرَيْش، نُحِبُّ حَديثَ رِجالِهِمْ، وَ النِّكاحَ فى نِسائِهِمْ. وَ اَمّا بَنُوعَبْدِشَمْس: فَاَبْعَدُها رَأْياً، وَ اَمْنَعُها لِما وَراءَ ظُهُورِها. وَ اَمّا نَحْنُ فَاَبْذَلُ لِما فى اَيْدينا، وَ اَسْمَحُ عِنْدَ الْمَوْتِ بِنُفُوسِنا، وَ هُمْ اَكْثَرُ وَ اَمْكَرُ وَ اَنْكَرُ، وَ نَحْنُ اَفْصَحُ وَ اَنْصَحُ وَ اَصْبَحُ.","persian":"از امام دربارهٔ قریش پرسیدند. فرمود: «بنی‌مخزوم گل‌های خوش‌بوی قریش‌اند؛ سخن گفتن مردانشان و همسری با زنانشان را دوست داریم. بنی‌عبدشمس دوراندیش‌تر و در پیشامدها استوارترند. اما ما بنی‌هاشم آنچه را در دست داریم سخاوتمندانه‌تر می‌بخشیم و در بخشیدن جان، بخشنده‌تریم. بنی‌عبدشمس از نظر شمار بیشتر، حیله‌گرتر و بدکردارترند؛ و ما گویاتر، خیرخواه‌تر و خوش‌روتریم.»","audio":null},{"id":"h121","kind":"hikmat","number":121,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: شَتّانَ ما بَيْنَ عَمَلَيْنِ: عَمَل تَذْهَبُ لَذَّتُهُ وَ تَبْقى تَبِعَتُهُ، وَ عَمَل تَذْهَبُ مَؤُونَتُهُ وَ يَبْقى اَجْرُهُ.","persian":"چه فاصلهٔ بزرگی است میان دو کار: کاری که لذتش می‌رود و پیامد زیان‌بارش می‌ماند، و کاری که رنجش پایان می‌یابد و پاداشش باقی می‌ماند.","audio":null},{"id":"h122","kind":"hikmat","number":122,"arabic":"وَ قَدْ تَبِعَ جَنازَةً فَسَمِعَ رَجُلاً يَضْحَكُ، فَقالَ عَلَيْهِ السَّلامُ: كَاَنَّ الْمَوتَ فيها عَلى غَيْرِنا كُتِبَ، وَ كَاَنَّ الْحَقَّ فيها عَلى غَيْرِنا وَجَبَ، وَ كَاَنَّ الَّذى نَرى مِنَ الاَْمْواتِ سَفْرٌ عَمّا قَليل اِلَيْنا راجِعُونَ، نُبَوِّئُهُمْ اَجْداثَهُمْ، وَ نَأْكُلُ تُراثَهُمْ، كَاَنّا مُخَلَّدُونَ بَعْدَهُمْ، ثُمَّ قَدْ نَسينا كُلَّ واعِظ وَ واعِظَة، وَ رُمينا بِكُلِّ فادِح وَ جائِحَة.","persian":"هنگامی که امام در پی جنازه‌ای می‌رفت، شنید مردی می‌خندد. فرمود: «گویی مرگ در دنیا برای دیگران نوشته شده و حق بر دیگران واجب شده است؛ گویی مردگانی را که می‌بینیم، مسافرانی می‌پنداریم که به‌زودی نزد ما بازمی‌گردند. آنان را در گورهایشان جای می‌دهیم و میراثشان را می‌خوریم، چنان‌که گویی پس از آنان جاودانه خواهیم ماند. پند هر پنددهنده‌ای را از یاد برده‌ایم و آماج هر بلای سنگینی شده‌ایم.»","audio":null},{"id":"h123","kind":"hikmat","number":123,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: طُوبى لِمَنْ ذَلَّ فى نَفْسِهِ، وَ طابَ كَسْبُهُ، وَ صَلَحَتْ سَريرَتُهُ، وَ حَسُنَتْ خَليقَتُهُ، وَ اَنْفَقَ الْفَضْلَ مِنْ مالِهِ، وَ اَمْسَكَ الْفَضْلَ مِنْ لِسانِهِ، وَ عَزَلَ عَنِ النّاسِ شَرَّهُ، وَ وَسِعَتْهُ السُّنَّةُ، وَ لَمْ يُنْسَبْ اِلَى الْبِدْعَةِ.","persian":"خوشا به حال کسی که در نظر خود فروتن است، کسب‌وکارش پاک، درونش شایسته و اخلاقش نیکوست؛ افزونی مال خود را می‌بخشد، از گفتار بیهوده می‌پرهیزد، بدی خود را از مردم دور می‌دارد، به سنت بسنده می‌کند و به بدعت روی نمی‌آورد.","audio":null},{"id":"h124","kind":"hikmat","number":124,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: غيرَةُ الْمَرْاَةِ كُفْرٌ، وَ غيرَةُ الرَّجُلِ ايمانٌ.","persian":"غیرت زن کفر است و غیرت مرد ایمان است.","audio":null},{"id":"h125","kind":"hikmat","number":125,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاََنْسُبَنَّ الاِْسْلامَ نِسْبَةً لَمْ يَنْسُبْها اَحَدٌ قَبْلى: الاِْسْلامُ هُوَ التَّسْليمُ، وَالتَّسْليمُ هُوَ الْيَقينُ، وَ الْيَقينُ هُوَ التَّصْديقُ، وَالتَّصْديقُ هُوَ الاِْقْرارُ، وَ الاِْقْرارُ هُوَ الاَْداءُ، وَ الاَْداءُ هُوَ الْعَمَلُ.","persian":"اسلام را به گونه‌ای تعریف می‌کنم که کسی پیش از من چنین تعریف نکرده است: اسلام همان تسلیم شدن است؛ تسلیم شدن همان یقین است؛ یقین همان تصدیق است؛ تصدیق همان اقرار است؛ اقرار همان انجام دادن است؛ و انجام دادن همان عمل کردن است.","audio":null},{"id":"h126","kind":"hikmat","number":126,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عَجِبْتُ لِلْبَخيلِ يَسْتَعْجِلُ الْفَقْرَ الَّذى مِنْهُ هَرَبَ، وَ يَفُوتُهُ الْغِنَى الَّذى اِيّاهُ طَلَبَ، فَيَعيشُ فِى الدُّنْيا عَيْشَ الْفُقَراءِ، وَ يُحاسَبُ فِى الاْخِرَةِ حِسابَ الاَْغْنِياءِ. وَ عَجِبْتُ لِلْمُتَكَبِّرِ الَّذى كانَ بِالاَْمْسِ نُطْفَةً، وَ يَكُونُ غَداً جيفَةً. وَ عَجِبْتُ لِمَنْ شَكَّ فِى اللّهِ وَ هُوَ يَرى خَلْقَ اللّهِ. وَ عَجِبْتُ لِمَنْ نَسِىَ الْمَوْتَ وَ هُوَ يَرَى مَنْ يَمُوتُ. وَ عَجِبْتُ لِمَنْ اَنْكَرَ النَّشْاَةَ الاُْخْرى وَ هُوَ يَرَى النَّشْاَةَ الاُْولى. وَ عَجِبْتُ لِعامِر دارَ الْفَناءِ، وَ تارِك دارَ الْبَقاءِ.","persian":"در شگفتم از بخیل که به سوی همان تنگدستی می‌شتابد که از آن گریزان است و توانگری‌ای را از دست می‌دهد که در پی آن است؛ در دنیا همچون تهیدستان زندگی می‌کند و در آخرت مانند توانگران حسابرسی می‌شود. و در شگفتم از متکبر که دیروز نطفه‌ای بود و فردا مرداری خواهد شد. و در شگفتم از کسی که در خدا شک می‌کند، درحالی‌که آفریدگان او را می‌بیند؛ و کسی که مرگ را فراموش می‌کند، درحالی‌که مردگان را می‌بیند؛ و کسی که رستاخیز را انکار می‌کند، درحالی‌که آفرینش نخستین خود را می‌بیند؛ و کسی که سرای ناپایدار را آباد می‌کند و سرای ماندگار را وا می‌گذارد.","audio":null},{"id":"h127","kind":"hikmat","number":127,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ قَصَّرَ فِى الْعَمَلِ ابْتُلِىَ بِالْهَمِّ. وَ لا حاجَةَ لِلّهِ فيمَنْ لَيْسَ لِلّهِ فى مالِهِ وَ نَفْسِهِ نَصيبٌ.","persian":"هرکس در عمل کوتاهی کند، به اندوه گرفتار می‌شود؛ و کسی که در مال و جانش بهره‌ای برای خدا قرار نداده است، خدا به او اعتنایی ندارد.","audio":null},{"id":"h128","kind":"hikmat","number":128,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: تَوَّقُوا الْبَرْدَ فى اَوَّلِهِ، وَ تَلَقَّوْهُ فى آخِرِهِ، فَاِنَّهُ يَفْعَلُ فِى الاَْبْدانِ كَفِعْلِهِ فِى الاَْشْجارِ، اَوَّلُهُ يُحْرِقُ، وَ آخِرُهُ يُورِقُ.","persian":"در آغاز سرما از آن بپرهیزید و در پایانش از آن استقبال کنید؛ زیرا سرما با بدن‌ها همان می‌کند که با درختان: در آغاز می‌سوزاند و در پایان برگ می‌رویاند.","audio":null},{"id":"h129","kind":"hikmat","number":129,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عِظَمُ الْخالِقِ عِنْدَكَ يُصَغِّرُ الْمَخْلُوقَ فى عَيْنَيْكَ.","persian":"هرچه عظمت آفریدگار در چشم تو بزرگ‌تر باشد، آفریدگان در نظرت کوچک‌تر خواهند بود.","audio":null},{"id":"h130","kind":"hikmat","number":130,"arabic":"وَ قالَ عَلَيْهِ السّلامُ، وَ قَدْ رَجَعَ مِنْ صِفِّينَ، فَاَشْرَفَ عَلَى الْقُبُورِ بِظاهِرِ الْكُوفَةِ: يا اَهْلَ الدِّيارِ الْمُوحِشَةِ، وَالْمَحالِّ الْمُقْفِرَةِ، وَالْقُبُورِ الْمُظْلِمَةِ؛ يا اَهْلَ التُّرْبَةِ، يا اَهْلَ الْغُرْبَةِ، يا اَهْلَ الْوَحْدَةِ، يا اَهْلَ الْوَحْشَةِ، اَنْتُمْ لَنا فَرَطٌ سابِقٌ وَ نَحْنُ لَكُمْ تَبَعٌ لاحِقٌ. اَمَّا الدُّورُ فَقَدْ سُكِنَتْ، وَاَمَّا الاَْزْواجُ فَقَدْ نُكِحَتْ، وَ اَمَّا الاَْمْوالُ فَقَدْ قُسِمَتْ. هذا خَبَرُ ما عِنْدَنا، فَما خَبَرُ ما عِنْدَكُمْ؟ - ثُمَّ الْتَفَتَ اِلى اَصْحابِهِ فَقالَ: اَما لَوْ اُذِنَ لَهُمْ فِى الْكَلامِ لاََخْبَرُوكُمْ اَنَّ خَيْرَ الزّادِ التَّقْوى.","persian":"هنگامی که امام از صفین بازگشت، به گورستان بیرون کوفه نگریست و فرمود: «ای ساکنان خانه‌های وحشت، جایگاه‌های بی‌آب‌وگیاه و گورهای تاریک! ای خاک‌نشینان، غریبان، تنهاشدگان و وحشت‌زدگان! شما پیشینیان مایید که زودتر رفتید و ما آیندگان شماییم که به شما خواهیم پیوست. خانه‌هایتان را دیگران گرفته‌اند، همسرانتان با دیگران ازدواج کرده‌اند و دارایی‌هایتان تقسیم شده است. این خبری است که ما داریم؛ شما چه خبری دارید؟» سپس رو به یاران خود کرد و فرمود: «اگر به مردگان اجازهٔ سخن گفتن داده می‌شد، به شما می‌گفتند: بهترین توشه، پرهیزگاری است.»","audio":null},{"id":"h131","kind":"hikmat","number":131,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ وَ قَدْ سَمِعَ رَجُلاً يَذُمُّ الدُّنْيا: اَيُّهَا الذّامُّ لِلدُّنْيا، الْمُغْتَرُّ بِغُرُورِها، الْمُنْخَدِعُ بِاَباطيلِها، اَتَغْتَرُّ بِالدُّنْيا ثُمَّ تَذُمُّها؟! اَنْتَ الْمُتَجَرِّمُ عَلَيْها اَمْ هِىَ الْمُتَجَرِّمَةُ عَلَيْكَ؟ مَتَى اسْتَهْوَتْكَ اَمْ مَتى غَرَّتْكَ؟ اَبِمَصارِع ِ آبائِكَ مِنَ الْبِلى؟ اَمْ بِمَضاجِع ِ اُمَّهاتِكَ تَحْتَ الثَّرى؟ كَمْ عَلَّلْتَ بِكَفَّيْكَ! وَ كَمْ مَرَّضْتَ بِيَدَيْكَ! تَبْتَغى لَهُمُ الشِّفاءَ، وَ تَسْتَوْصِفُ لَهُمُ الاَْطِبّاءَ، غَداةَ لايُغْنى عَنْهُمْ دَواؤُكَ، وَ لايُجْدى عَلَيْهِمْ بُكاؤُكَ، لَمْ يَنْفَعْ اَحَدَهُمْ اِشْفاقُكَ، وَ لَمْ تُسْعَفْ فيهِ بِطِلْبَتِكَ، وَ لَمْ تَدْفَعْ عَنْهُ بِقُوَّتِكَ. قَدْ مَثَّلَتْ لَكَ بِهِ الدُّنْيا نَفْسَكَ، وَ بِمَصْرَعِهِ مَصْرَعَكَ. اِنَّ الدُّنْيا دارُ صِدْق لِمَنْ صَدَقَها، وَ دارُ عافِيَة لِمَنْ فَهِمَ عَنْها، وَ دارُ غِنًى لِمَنْ تَزَوَّدَ مِنْها، وَ دارُ مَوْعِظَة لِمَنِ اتَّعَظَ بِها. مَسْجِدُ اَحِبّاءِ اللّهِ، وَ مُصَلّى مَلائِكَةِ اللّهِ، وَ مَهْبِطُ وَحْىِ اللّهِ، وَ مَتْجَرُ اَوْلِياءِ اللّهِ، اِكْتَسَبُوا فيهَا الرَّحْمَةَ، وَ رَبِحُوا فيهَا الْجَنَّةَ. فَمَنْ ذا يَذُمُّها وَ قَدْ آذَنَتْ بِبَيْنِها، وَ نادَتْ بِفِراقِها، وَ نَعَتْ نَفْسَها وَ اَهْلَها، فَمَثَّلَتْ لَهُمْ بِبَلائِها الْبَلاءَ، وَ شَوَّقَتْهُمْ بِسُروُرِها اِلَى السُّرُورِ. راحَتْ بِعافِيَة، وَ ابْتَكَرَتْ بِفَجيعَة، تَرْغيباً وَ تَرْهيباً، وَ تَخْويفاً وَ تَحْذيراً. فَذَمَّها رِجالٌ غَداةَ النَّدامَةِ، وَ حَمِدَها آخَرُونَ يَوْمَ الْقِيامَةِ. ذَكَّرَتْهُمُ الدُّنْيا فَتَذَكَّرُوا، وَ حَدَّثَتْهُمْ فَصَدَّقُوا، وَ وَعَظَتْهُمْ فَاتَّعَظُوا.","persian":"هنگامی که امام شنید مردی دنیا را نکوهش می‌کند، فرمود: «ای نکوهشگر دنیا! تو که فریب نیرنگ‌هایش را خورده و با سخنان باطلش گمراه شده‌ای، چگونه دنیا را سرزنش می‌کنی؟ آیا تو بر دنیا ادعای گناه داری یا دنیا بر تو؟ چه زمانی دنیا تو را سرگردان کرد و چه وقت فریبت داد؟ آیا با جایگاه فروپاشیدن پدرانت یا با آرامگاه مادرانت در زیر خاک؟ چه بسیار بیمارانی که با دستانت به پرستاری‌شان پرداختی و برای شفایشان کوشیدی، از پزشکان چاره خواستی و برایشان دل سوزاندی، اما بامدادان نه دارو سودشان داد، نه گریه به کارشان آمد و نه ترس تو مرگ را از آنان دور کرد. تو به خواسته‌ات نرسیدی و نتوانستی با توان خود مرگ را از آن‌ها بازداری. دنیا با سرنوشت آنان سرنوشت تو را نشان داد و با مرگشان، مرگ تو را به یادت آورد. دنیا برای کسی که با آن راست باشد، سرای راستی است؛ برای کسی که آن را درست بشناسد، خانهٔ عافیت است؛ برای کسی که از آن توشه برگیرد، جایگاه توانگری است؛ و برای کسی که پند بپذیرد، سرای اندرز است. دنیا مسجد دوستان خدا، نمازگاه فرشتگان، فرودگاه وحی و تجارتخانهٔ اولیای خداست؛ آنان در آن رحمت به دست آوردند و بهشت را سود بردند. پس چه کسی دنیا را نکوهش می‌کند، درحالی‌که دنیا جدایی خود را اعلام کرده، از رفتن خویش خبر داده و مرگ خود و ساکنانش را یادآور شده است؟ با بلاهایش نمونه‌ای از بلاهای آخرت نشان داده و با شادی‌هایش به شادی آن جهان امید بخشیده است. شامگاهی با آسایش می‌گذرد و بامدادی با گرفتاری فرا می‌رسد تا هشدار دهد و امیدوار کند، بترساند و برحذر دارد. گروهی در روز پشیمانی دنیا را سرزنش می‌کنند و گروهی دیگر در روز قیامت آن را می‌ستایند؛ همانان که دنیا پندشان داد و پند گرفتند، با آنان سخن گفت و تصدیقش کردند و اندرز داد و پذیرفتند.»","audio":null},{"id":"h132","kind":"hikmat","number":132,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِلّهِ مَلَكاً يُنادى فى كُلِّ يَوْم: لِدُوا لِلْمَوْتِ، وَ اجْمَعُوا لِلْفَناءِ، وَ ابْنُوا لِلْخَرابِ.","persian":"خدا فرشته‌ای دارد که هر روز ندا می‌دهد: بزایید تا بمیرید، گرد آورید تا نابود شود، و بنا کنید تا ویران شود.","audio":null},{"id":"h133","kind":"hikmat","number":133,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الدُّنْيا دارُ مَمَرٍّ لا دارُ مَقَرٍّ، وَ النّاسُ فيها رَجُلانِ: رَجُلٌ باعَ نَفْسَهُ فَاَوْبَقَها، وَ رَجُلٌ ابْتاعَ نَفْسَهُ فَاَعْتَقَها.","persian":"دنیا سرای گذر است، نه سرای ماندن؛ و مردم در آن دو دسته‌اند: کسی که خود را می‌فروشد و به هلاکت می‌کشاند، و کسی که خود را بازمی‌خرد و آزاد می‌کند.","audio":null},{"id":"h134","kind":"hikmat","number":134,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايَكُونُ الصَّديقُ صَديقاً حَتّى يَحْفَظَ اَخاهُ فى ثَلاث: فى نَكْبَتِهِ، وَ غَيْبَتِهِ، وَ وَفاتِهِ.","persian":"دوست، دوست حقیقی نیست مگر آنکه دوستش را در سه هنگام پاس بدارد: در سختی، در غیاب او و پس از مرگش.","audio":null},{"id":"h135","kind":"hikmat","number":135,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اُعْطِىَ اَرْبَعاً لَمْ يُحْرَمْ اَرْبَعاً: مَنْ اُعْطِىَ الدُّعاءَ لَمْ يُحْرَمِ الاِْجابَةَ، وَ مَنْ اُعْطِىَ التَّوْبَةَ لَمْ يُحْرَمِ الْقَبُولَ، وَ مَنْ اُعْطِىَ الاْسْتِغْفارَ لَمْ يُحْرَمِ الْمَغْفِرَةَ، وَ مَنْ اُعْطِىَ الشُّكْرَ لَمْ يُحْرَمِ الزِّيادَةَ. وَ تَصْديقُ ذلِكَ فى كِتابِ اللّهِ تَعالى، قالَ اللّهُ عَزَّوَجَلَّ فِى الدُّعاءِ: «ادْعُونى اَسْتَجِبْ لَكُمْ.» وَ قالَ فِى الاِْسْتِغْفارِ: «وَ مَنْ يَعْمَلْ سُوءاً اَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللّهَ يَجِدِ اللّهَ غَفُوراً رَحيماً.» وَ قالَ فِى الشُّكْرِ: «لَئِنْ شَكَرْتُمْ لاََزيدَنَّكُمْ» وَ قالَ فِى التَّوْبَةِ: «اِنَّمَا التَّوْبَةُ عَلَى اللّهِ لِلَّذينَ يَعْمَلُونَ السُّوءَ بِجَهالَة ثُمَّ يَتُوبُونَ مِنْ قَريب، فَاُولئِكَ يَتُوبُ اللّهُ عَلَيْهِمْ وَ كانَ اللّهُ عَليماً حَكيماً.»","persian":"به هرکس چهار چیز داده شود، از چهار چیز محروم نمی‌ماند: کسی که توفیق دعا داشته باشد، از اجابت؛ کسی که توفیق توبه یافته باشد، از پذیرش؛ کسی که آمرزش‌خواهی کند، از آمرزش؛ و کسی که سپاسگزاری کند، از افزونی نعمت محروم نمی‌شود. گواه آن در کتاب خداست: دربارهٔ دعا فرمود «مرا بخوانید تا شما را اجابت کنم»؛ دربارهٔ آمرزش‌خواهی فرمود «هرکس کار زشتی کند یا بر خویش ستم روا دارد و سپس از خدا آمرزش بخواهد، خدا را آمرزنده و مهربان می‌یابد»؛ دربارهٔ سپاسگزاری فرمود «اگر سپاس بگزارید، بر نعمت شما می‌افزایم»؛ و دربارهٔ توبه فرمود «پذیرش توبه از سوی خدا برای کسانی است که از روی نادانی کار بد می‌کنند و سپس زود توبه می‌کنند؛ خدا توبهٔ آنان را می‌پذیرد و خدا دانا و حکیم است.»","audio":null},{"id":"h136","kind":"hikmat","number":136,"arabic":"وَ قالَ عَلَيْهِ اَلسَّلامُ: الصَّلاةُ قُرْبانُ كُلِّ تَقِىٍّ، وَالْحَجُّ جِهادُ كُلِّ ضَعيف. وَ لِكُلِّ شَىْء زَكاةٌ، وَ زَكاةُ الْبَدَنِ الصِّيامُ، وَ جِهادُ الْمَرْاَةِ حُسْنُ التَّبَعُّلِ.","persian":"نماز وسیلهٔ تقرب هر پرهیزگار به خداست و حج، جهاد هر ناتوان است. هر چیزی زکاتی دارد و زکات بدن روزه است؛ و جهاد زن، نیکو همسرداری کردن است.","audio":null},{"id":"h137","kind":"hikmat","number":137,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِسْتَنْزِلُوا الرِّزْقَ بِالصَّدَقَةِ.","persian":"با صدقه دادن، فرود آمدن روزی را بجویید.","audio":null},{"id":"h138","kind":"hikmat","number":138,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَيْقَنَ بِالْخَلَفِ جادَ بِالْعَطِيَّةِ.","persian":"هرکس به جایگزین شدن آنچه می‌بخشد یقین داشته باشد، در بخشش گشاده‌دست می‌شود.","audio":null},{"id":"h139","kind":"hikmat","number":139,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: تَنْزِلُ الْمَعُونَةُ عَلى قَدْرِ الْمَؤُونَةِ.","persian":"یاری و کمک به اندازهٔ هزینه و نیاز فرومی‌رسد.","audio":null},{"id":"h140","kind":"hikmat","number":140,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما عالَ امْرُؤٌ اقْتَصَدَ.","persian":"کسی که میانه‌روی کند، تنگدست نمی‌شود.","audio":null},{"id":"h141","kind":"hikmat","number":141,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قِلَّةُ الْعِيالِ اَحَدُ الْيَسارَيْنِ.","persian":"کم بودن افراد تحت تکفل، یکی از دو گونه آسودگی و توانگری است.","audio":null},{"id":"h142","kind":"hikmat","number":142,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: التَّوَدُّدُ نِصْفُ الْعَقْلِ.","persian":"اظهار دوستی، نیمی از خرد است.","audio":null},{"id":"h143","kind":"hikmat","number":143,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْهَمُّ نِصْفُ الْهَرَمِ.","persian":"اندوه، نیمی از پیری است.","audio":null},{"id":"h144","kind":"hikmat","number":144,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَنْزِلُ الصَّبْرُ عَلى قَدْرِ الْمُصيبَةِ. وَ مَنْ ضَرَبَ يَدَهُ عَلى فَخِذِهِ عِنْدَ مُصيبَتِهِ حَبِطَ اَجْرُهُ.","persian":"شکیبایی به اندازهٔ سختی مصیبت فرومی‌رسد؛ و کسی که هنگام مصیبت از بی‌تابی بر ران خود بکوبد، پاداشش را تباه کرده است.","audio":null},{"id":"h145","kind":"hikmat","number":145,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَمْ مِنْ صائِم لَيْسَ لَهُ مِنْ صِيامِهِ اِلاَّ الْجُوعُ وَالظَّمَاءُ. وَ كَمْ مِنْ قائِم لَيْسَ لَهُ مِنْ قِيامِهِ اِلاَّ السَّهَرُ وَالْعَناءُ. حَبَّذا نَوْمُ الاَْكْياسِ وَ اِفْطارُهُمْ!","persian":"چه بسیار روزه‌دارانی که از روزهٔ خود جز گرسنگی و تشنگی بهره‌ای نمی‌برند، و چه بسیار شب‌زنده‌دارانی که از عبادت شبانه جز بیداری و رنج نصیبی ندارند. خوشا به خواب و روزه‌گشایی خردمندان!","audio":null},{"id":"h146","kind":"hikmat","number":146,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: سُوسُوا ايمانَكُمْ بِالصَّدَقَةِ، وَ حَصِّنُوا اَمْوالَكُمْ بِالزَّكاةِ، وَ ادْفَعُوا اَمْواجَ الْبَلاءِ بِالدُّعاءِ.","persian":"با صدقه دادن از ایمان خود نگاهبانی کنید؛ با زکات، اموالتان را حفظ کنید؛ و با دعا، موج‌های بلا را از خود دور سازید.","audio":null},{"id":"h147","kind":"hikmat","number":147,"arabic":"وَ مِنْ کَلام لَهُ عَلَیْهِ السَّلامُ لِكُمَيْلِ بْنِ زِياد النَّخَعِىِّ قالَ كُمَيْلُ بْنُ زِياد: اَخَذَ بِيَدى اَميرُالْمُؤْمِنينَ عَلِىُّ بْنُ اَبى طالِب عَلَيْهِ السّلامُ فَاَخْرَجَنى اِلَى الْجَبّانِ، فَلَمّا اَصْحَرَ تَنَفَّسَ الصُّعَداءَ، ثُمَّ قالَ: يا كُمَيْلُ، اِنَّ هذِهِ الْقُلُوبَ اَوْعِيَةٌ، فَخَيْرُها اَوْعاها، فَاحْفَظْ عَنّى ما اَقُولُ لَكَ. النّاسُ ثَلاثَةٌ: فَعالِمٌ رَبّانِىٌّ، وَ مُتَعَلِّمٌ عَلى سَبيلِ نَجاة، وَ هَمَجٌ رَعاعٌ، اَتْباعُ كُلِّ ناعِق، يَميلُونَ مَعَ كُلِّ ريح، لَمْ يَسْتَضيئُوا بِنُورِ الْعِلْمِ، وَ لَمْ يَلْجَاُوا اِلى رُكْن وَثيق. يا كُمَيْلُ، الْعِلْمُ خَيْرٌ مِنَ الْمالِ، الْعِلْمُ يَحْرُسُكَ وَ اَنْتَ تَحْرُسُ الْمالَ. الْمالُ تَنْقُصُهُ النَّفَقَةُ وَالْعِلْمُ يَزْكُو عَلَى الاِْنْفاقِ. وَ صَنيعُ الْمالِ يَزُولُ بِزَوالِهِ. يا كُمَيْلُ بْنَ زِياد، مَعْرِفَةُ الْعِلْمِ دينٌ يُدانُ بِهِ، بِهِ يَكْسِبُ الاِْنْسانُ الطّاعَةَ فى حَياتِهِ، وَ جَميلَ الاُْحْدُوثَةِ بَعْدَ وَفاتِهِ. وَالْعِلْمُ حاكِمٌ، وَ الْمالُ مَحْكُومٌ عَلَيْهِ. يا كُمَيْلُ، بْنَ زياد، هَلَكَ خُزّانُ الاَْمْوالِ وَ هُمْ اَحْياءٌ، وَ الْعُلَماءُ باقُونَ ما بَقِىَ الدَّهْرُ، اَعْيانُهُمْ مَفْقُودَةٌ، وَ اَمْثالُهُمْ فِى الْقُلُوبِ مَوْجُودَةٌ. ها، اِنَّ ههُنا لَعِلْماً جَمّاً - وَ اَشارَ بِيَدِهِ اِلى صَدْرِهِ- لَوْ اَصَبْتُ لَهُ حَمَلَةً! بَلى اَصَبْتُ لَقِناً غَيْرَ مَأْمُون عَلَيْهِ، مُسْتَعْمِلاً آلَةَ الدّينِ لِلدُّنْيا، وَ مُسْتَظْهِراً بِنِعَمِ اللّهِ عَلى عِبادِهِ، وَ بِحُجَجِهِ عَلى اَوْلِيائِهِ. اَوْ مُنْقاداً لِحَمَلَةِ الْحَقِّ، لا بَصيرَةَ لَهُ فى اَحْنائِهِ، يَنْقَدِحُ الشَّكُّ فى قَلْبِهِ لاَِوَّلِ عارِض مِنْ شُبْهَة. اَلا، لاذا وَلا ذاكَ. اَوْ مَنْهُوماً بِاللَّذَّةِ سَلِسَ الْقِيادِ لِلشَّهْوَةِ. اَوْ مُغْرَماً بِالْجَمْع ِ وَ الاِْدِّخارِ، لَيْسا مِنْ رُعاةِ الدّينِ فى شَىْء، اَقْرَبُ شَىْء شَبَهاً بِهِمَا الاَْنْعامُ السّائِمَةُ. كَذلِكَ يَمُوتُ الْعِلْمُ بِمَوْتِ حامِليهِ. اللّهُمَّ بَلى، لا تَخْلُو الاَْرْضُ مِنْ قائِم لِلّهِ بِحُجَّة، اِمّا ظاهِراً مَشْهُوراً، اَوْ خائِفاً مَغْمُوراً، لِئَلاّ تَبْطُلَ حُجَجُ اللّهِ وَ بَيِّناتُهُ. وَ كَمْ ذا؟ وَ اَيْنَ اُولئِكَ؟ اُولئِكَ وَاللّهِ الاَْقَلُّونَ عَدَداً، وَ الاَْعْظَمُونَ عِنْدَ اللّهِ قَدْراً، يَحْفَظُ اللّهُ بِهِمْ حُجَجَهُ وَ بَيِّناتِهِ حَتّى يُودِعُوها نُظَراءَهُمْ، وَ يَزْرَعُوها فى قُلُوبِ اَشْباهِهِمْ. هَجَمَ بِهِمُ الْعِلْمُ عَلى حَقيقَةِ الْبَصيرَةِ، وَ باشَرُوا رُوحَ الْيَقينِ، وَ اسْتَلانُوا مَا اسْتَوْعَرَهُ الْمُتْرَفُونَ، وَ اَنِسُوا بِمَا اسْتَوْحَشَ مِنْهُ الْجاهِلُونَ، وَ صَحِبُوا الدُّنْيا بِاَبْدان اَرْواحُها مُعَلَّقَةٌ بِالْمَحَلِّ الاَْعْلى. اُولئِكَ خُلَفاءُ اللّهِ فى اَرْضِهِ، وَ الدُّعاةُ اِلى دينِهِ. آهِ آهِ، شَوْقاً اِلى رُؤْيَتِهِمْ! اِنْصَرِفْ يا كُمَيْلُ اِذا شِئْتَ.","persian":"کمیل بن زیاد گفت: امیرمؤمنان علی بن ابی‌طالب (ع) دستم را گرفت و مرا به بیرون شهر برد. هنگامی که به صحرا رسیدیم، آهی ژرف کشید و فرمود: «ای کمیل! این دل‌ها ظرف‌اند و بهترینشان آن است که گنجایش و نگهداری بیشتری داشته باشد. آنچه می‌گویم به خاطر بسپار. مردم سه دسته‌اند: دانشمند الهی، دانش‌آموزی که در راه نجات گام برمی‌دارد، و جماعتی بی‌پایه که مانند پشه‌های پراکنده‌اند؛ به دنبال هر فریادی می‌روند و با هر بادی به سویی می‌گرایند. از نور دانش روشنایی نگرفته‌اند و به پناهگاهی استوار تکیه نکرده‌اند. ای کمیل! دانش از مال بهتر است؛ دانش از تو نگهبانی می‌کند، اما تو باید از مال نگهبانی کنی. مال با خرج کردن کم می‌شود، ولی دانش با بخشیدن افزایش می‌یابد؛ و آنچه با مال به دست می‌آید، با از میان رفتن مال از بین می‌رود. ای کمیل بن زیاد! شناخت دانش، آیینی است که انسان به آن پایبند می‌شود؛ با دانش در زندگی فرمان‌برداری از خدا به دست می‌آورد و پس از مرگ نام نیک می‌یابد. دانش فرمانرواست و مال فرمان‌بردار. ای کمیل! گردآورندگان مال، هرچند زنده‌اند، مرده‌اند؛ اما دانشمندان تا روزگار باقی است زنده‌اند. پیکرشان از میان می‌رود، ولی یاد و نمونهٔ آنان در دل‌ها باقی می‌ماند. بدان که اینجا دانش فراوانی نهفته است» و با دست به سینهٔ خود اشاره کرد، «کاش کسانی را می‌یافتم که توان حمل آن را داشته باشند! آری، کسانی تیزفهم می‌یابم، اما نمی‌توان به آنان اعتماد کرد: ابزار دین را برای دنیا به کار می‌گیرند و با نعمت‌های خدا بر بندگان او و با حجت‌های الهی بر دوستانش برتری می‌جویند. یا کسی را می‌یابم که پیرو اهل حق است، اما در شناخت ریزه‌کاری‌های حق بصیرت ندارد و با نخستین شبهه، شک در دلش شعله‌ور می‌شود. نه آن یکی شایسته است و نه این یکی. یا کسی را می‌یابم که شیفتهٔ لذت‌ها و فرمان‌بردار خواهش‌های نفسانی است، یا کسی که به گردآوردن و اندوختن مال دل بسته است. این دو نیز نگهبان دین نیستند و بیش از همه به چهارپایان چرنده شباهت دارند. چنین است که دانش با مرگ حاملانش از میان می‌رود. آری، خدایا! زمین هرگز از کسی که حجت تو را برپا دارد خالی نمی‌ماند؛ خواه آشکار و شناخته‌شده باشد، خواه بیمناک و پنهان، تا حجت‌ها و نشانه‌های روشن خدا از میان نروند. شمارشان چقدر است و کجایند؟ به خدا سوگند، شمارشان اندک، اما منزلتشان نزد خدا بسیار بزرگ است. خداوند حجت‌ها و نشانه‌های خود را به دست آنان نگه می‌دارد تا آن‌ها را به همانندان خویش بسپارند و بذرشان را در دل کسانی مانند خود بکارند. دانش با حقیقت بینش بر دل آنان فرود آمده و با روح یقین آمیخته‌اند. آنچه را خوش‌گذرانان دشوار می‌یابند، آسان می‌شمرند و با آنچه نادانان از آن می‌گریزند، انس می‌گیرند. با بدن‌های خود در دنیا زندگی می‌کنند، اما جان‌هایشان به جایگاهی برتر پیوسته است. آنان جانشینان خدا در زمین و دعوت‌کنندگان به دین اویند. آه، چه مشتاق دیدارشان هستم! ای کمیل، اکنون اگر می‌خواهی بازگرد.»","audio":null},{"id":"h148","kind":"hikmat","number":148,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْمَرْءُ مَخْبُوءٌ تَحْتَ لِسانِهِ.","persian":"انسان در پسِ زبان خود پنهان است.","audio":null},{"id":"h149","kind":"hikmat","number":149,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: هَلَكَ امْرُؤٌ لَمْ يَعْرِفْ قَدْرَهُ.","persian":"کسی که قدر و جایگاه خود را نشناسد، هلاک می‌شود.","audio":null},{"id":"h150","kind":"hikmat","number":150,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ، لِرَجُل سَاَلَهُ اَنْ يَعِظَهُ: لاتَكُنْ مِمَّنْ يَرْجُو الاْخِرَةَ بِغَيْرِ الْعَمَلِ، وَ يُرَجِّى التَّوْبَةَ بِطُولِ الاَْمَلِ. يَقُولُ فِى الدُّنْيا بِقَوْلِ الزّاهِدينَ، وَ يَعْمَلُ فيها بِعَمَلِ الرّاغِبينَ. اِنْ اُعْطِىَ مِنْها لَمْ يَشْبَعْ، وَ اِنْ مُنِعَ مِنْها لَمْ يَقْنَعْ. يَعْجِزُ عَنْ شُكْرِ ما اُوتِىَ، وَ يَبْتَغِى الزِّيادَةَ فيما بَقِىَ. يَنْهى وَ لا يَنْتَهى، وَ يَأْمُرُ بِما لايَأْتى. يُحِبُّ الصّالِحينَ وَ لايَعْمَلُ عَمَلَهُمْ، وَ يُبْغِضُ الْمُذْنِبينَ وَ هُوَ اَحَدُهُمْ. يَكْرَهُ الْمَوْتَ لِكَثْرَةِ ذُنُوبِهِ، وَ يُقيمُ عَلى ما يَكْرَهُ الْمَوْتَ مِنْ اَجْلِهِ. اِنْ سَقِمَ ظَلَّ نادِماً، وَ اِنْ صَحَّ اَمِنَ لاهِياً. يُعْجِبُ بِنَفْسِهِ اِذا عُوفِىَ، وَ يَقْنَطُ اِذَا ابْتُلِىَ. اِنْ اَصابَهُ بَلاءٌ دَعا مُضْطَرّاً، وَ اِنْ نالَهُ رَخاءٌ اَعْرَضَ مُغْتَرّاً. تَغْلِبُهُ نَفْسُهُ عَلى ما يَظُنُّ، وَلايَغْلِبُها عَلى ما يَسْتَيْقِنُ. يَخافُ عَلى غَيْرِهِ بِاَدْنى مِنْ ذَنْبِهِ، وَ يَرْجُو لِنَفْسِهِ بِاَكْثَرَ مِنْ عَمَلِهِ. اِنِ اسْتَغْنى بَطِرَ وَ فُتِنَ، وَ اِنِ افْتَقَرَ قَنَطَ وَ وَهَنَ. يُقَصِّرُ اِذا عَمِلَ، وَ يُبالِغُ اِذا سَاَلَ. اِنْ عَرَضَتْ لَهُ شَهْوَةٌ اَسْلَفَ الْمَعصِيَةَ وَ سَوَّفَ التَّوْبَةَ، وَ اِنْ عَرَتْهُ مِحْنَةٌ انْفَرَجَ عَنْ شَرائِطِ الْمِلَّةِ.يَصِفُ الْعِبْرَةَ وَلايَعْتَبِرُ، وَ يُبالِغُ فِى الْمَوْعِظَةِ وَلايَتَّعِظُ، فَهُوَ بِالْقَوْلِ مُدِلٌّ، وَ مِنَ الْعَمَلِ مُقِلٌّ. يُنافِسُ فيما يَفْنى، وَ يُسامِحُ فيما يَبْقى. يَرَى الْغُنْمَ مَغْرَماً، وَ الْغُرْمَ مَغْنَماً. يَخْشَى الْمَوْتَ وَلا يُبادِرُ الْفَوْتَ. يَسْتَعْظِمُ مِنْ مَعْصِيَةِ غَيْرِهِ ما يَسْتَقِلُّ اَكْثَرَ مِنْهُ مِنْ نَفْسِهِ، وَ يَسْتَكْثِرُ مِنْ طاعَتِهِ ما يَحْقِرهُ مِنْ طاعَةِ غَيْرِهِ. فَهُوَ عَلَى النّاسِ طاعِنٌ، وَ لِنَفْسِهِ مُداهِنٌ. اللَّهْوُ مَعَ الاَْغْنِياءِ اَحَبُّ اِلَيْهِ مِنَ الذِّكْرِ مَعَ الْفُقَراءِ. يَحْكُمُ عَلى غَيْرِهِ لِنَفْسِهِ، وَلايَحْكُمُ عَلَيْها لِغَيْرِهِ، وَ يُرْشِدُ غَيْرَهُ وَ يُغْوى نَفْسَهُ، فَهُوَ يُطاعُ وَ يَعْصى، وَ يَسْتَوْفى وَ لا يُوفى. وَ يَخْشَى الْخَلْقَ فى غَيْرِ رَبِّهِ، وَ لايَخْشى رَبَّهُ فى خَلْقِهِ.","persian":"امام به مردی که از او اندرز خواست، فرمود: «از کسانی مباش که بدون عمل به آخرت امید می‌بندند و با آرزوهای دراز، توبه را به تأخیر می‌اندازند؛ دربارهٔ دنیا مانند زاهدان سخن می‌گویند، اما مانند دلبستگان دنیا رفتار می‌کنند. اگر از دنیا به آنان بدهند سیر نمی‌شوند و اگر محرومشان کنند قناعت نمی‌ورزند. از سپاس آنچه به دست آورده‌اند ناتوان‌اند و بیشتر از آن را می‌خواهند. دیگران را از بدی بازمی‌دارند، ولی خود دست برنمی‌دارند؛ به کارهایی فرمان می‌دهند که خود انجام نمی‌دهند. نیکان را دوست دارند، اما مانند آنان عمل نمی‌کنند؛ از گناهکاران بیزارند، درحالی‌که خود از آنان‌اند. به سبب گناهان فراوان از مرگ می‌ترسند، ولی همان کارهایی را ادامه می‌دهند که سبب ترسشان شده است. هنگام بیماری پشیمان می‌شوند و چون سلامت می‌یابند، سرگرم خوش‌گذرانی می‌گردند؛ در آسایش خودپسند و در گرفتاری نومید می‌شوند. هنگام مصیبت از روی درماندگی دعا می‌کنند و چون آسوده شوند، مغرورانه از خدا روی می‌گردانند. نفسشان در آنچه گمان می‌برند بر آنان چیره است، اما آنان در آنچه یقین دارند بر نفس خود چیره نیستند. برای گناهی کمتر از گناه خود بر دیگران می‌ترسند، ولی برای خود پاداشی بیشتر از کردارشان می‌خواهند. اگر توانگر شوند سرکشی می‌کنند و اگر تنگدست شوند، نومید و سست می‌گردند. در عمل کوتاهی و در درخواست زیاده‌روی می‌کنند. اگر خواهشی نفسانی پیش آید، گناه را پیش می‌اندازند و توبه را عقب می‌اندازند؛ و اگر سختی برسد، از وظیفهٔ دینی فاصله می‌گیرند. عبرت‌ها را بازمی‌گویند، اما عبرت نمی‌گیرند؛ در اندرز دادن زیاده‌روی می‌کنند، ولی خود پند نمی‌پذیرند. در سخن گفتن خود را بزرگ می‌شمارند و در عمل فرو می‌مانند. به چیزهای فناپذیر دل می‌بندند و از امور ماندگار غفلت می‌کنند. سود معنوی را زیان و زیان واقعی را سود می‌پندارند. از مرگ می‌ترسند، اما پیش از آنکه فرصت از دست برود، به کار شایسته نمی‌شتابند. گناه دیگران را بزرگ می‌شمارند، درحالی‌که گناه بزرگ‌تر خود را کوچک می‌بینند؛ عبادت اندک خویش را بسیار می‌دانند، درحالی‌که عبادت همانند آن را از دیگران ناچیز می‌شمارند. مردم را سرزنش و با خود مدارا می‌کنند. سرگرمی با توانگران را از یاد خدا در کنار تهیدستان بیشتر دوست دارند. به سود خود علیه دیگران حکم می‌کنند، ولی به سود دیگران علیه خود حکم نمی‌کنند. دیگران را راهنمایی و خود را گمراه می‌کنند؛ از آنان فرمان می‌برند، ولی خود نافرمانی می‌کنند. حق خویش را کامل می‌گیرند، ولی حق دیگران را کامل نمی‌دهند. از مردم به خاطر غیر خدا می‌ترسند، اما در رفتار با مردم از پروردگارشان پروا ندارند.»","audio":null},{"id":"h151","kind":"hikmat","number":151,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِكُلِّ امْرِئ عاقِبَةٌ حُلْوَةٌ اَوْ مُرَّةٌ.","persian":"هر انسانی سرانجامی دارد؛ شیرین یا تلخ.","audio":null},{"id":"h152","kind":"hikmat","number":152,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِكُلِّ مُقْبِل اِدْبارٌ، وَ ما اَدْبَرَ كَاَنْ لَمْ يَكُنْ.","persian":"هر روی‌آوردنی، پشت‌کردنی در پی دارد؛ و آنچه پشت کند، گویی هرگز نبوده است.","audio":null},{"id":"h153","kind":"hikmat","number":153,"arabic":"وَقالَ عَلَيْهِ السَّلامُ: لايَعْدَمُ الصَّبُورُ الظَّفَرَ وَاِنْ طالَ بِهِ الزَّمانُ.","persian":"انسان شکیبا پیروزی را از دست نمی‌دهد، هرچند انتظارش طولانی شود.","audio":null},{"id":"h154","kind":"hikmat","number":154,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الرّاضى بِفِعْلِ قَوْم كَالدّاخِل فيهِ مَعَهُمْ. وَ عَلى كُلِّ داخِل فى باطِل اِثْمانِ: اِثْمُ الْعَمَلِ بِهِ، وَ اِثْمُ الرِّضى بِهِ.","persian":"هرکس به کار گروهی رضایت دهد، مانند کسی است که در آن کار با آنان همراه بوده است؛ و هرکس در باطل وارد شود، دو گناه دارد: گناه انجام آن کار و گناه خشنودی به آن.","audio":null},{"id":"h155","kind":"hikmat","number":155,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اعْتَصِمُوا بِالذِّمَمِ فى اَوْتادِها.","persian":"به پیمان‌ها، در جایگاهی که استوار شده‌اند، چنگ بزنید.","audio":null},{"id":"h156","kind":"hikmat","number":156,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عَلَيْكُمْ بِطاعَةِ مَنْ لا تُعْذَرُونَ بِجَهالَتِهِ.","persian":"بر شما باد فرمان‌برداری از کسی که در نشناختن او عذری ندارید.","audio":null},{"id":"h157","kind":"hikmat","number":157,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قَدْ بُصِّرْتُمْ اِنْ اَبْصَرْتُمْ، وَ قَدْ هُديتُمْ اِنِ اهْتَدَيْتُمْ، وَ اُسْمِعْتُمْ اِنِ اسْتَمَعْتُمْ.","persian":"راه را به شما نشان داده‌اند، اگر چشم بگشایید؛ شما را راهنمایی کرده‌اند، اگر هدایت بپذیرید؛ و پیام را به گوشتان رسانده‌اند، اگر بشنوید.","audio":null},{"id":"h158","kind":"hikmat","number":158,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عاتِبْ اَخاكَ بِالاِْحْسانِ اِلَيْهِ، وَ ارْدُدْ شَرَّهُ بِالاِْنْعامِ عَلَيْهِ.","persian":"برادرت را با نیکی کردن به او سرزنش کن و بدی‌اش را با بخشش پاسخ بده.","audio":null},{"id":"h159","kind":"hikmat","number":159,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ وَضَعَ نَفْسَهُ مَواضِعَ التُّهَمَةِ فَلايَلُومَنَّ مَنْ اَساءَ بِهِ الظَّنَّ.","persian":"کسی که خود را در جایگاه تهمت قرار دهد، نباید کسی را که به او بدگمان شده سرزنش کند.","audio":null},{"id":"h160","kind":"hikmat","number":160,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ مَلَكَ اسْتَأْثَرَ.","persian":"هرکس به قدرت دست یابد، آن را به خود اختصاص می‌دهد.","audio":null},{"id":"h161","kind":"hikmat","number":161,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنِ اسْتَبَدَّ بِرَأْيِهِ هَلَكَ، وَ مَنْ شاوَرَ الرِّجالَ شارَكَها فى عُقُولِها.","persian":"هرکس تنها به رأی خود تکیه کند، هلاک می‌شود؛ و هرکس با دیگران مشورت کند، در خرد آنان شریک می‌شود.","audio":null},{"id":"h162","kind":"hikmat","number":162,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ كَتَمَ سِرَّهُ كانَتِ الْخِيَرَةُ بِيَدِهِ.","persian":"هرکس راز خود را پوشیده نگه دارد، اختیار کارش در دست خودش خواهد بود.","audio":null},{"id":"h163","kind":"hikmat","number":163,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْفَقْرُ الْمَوْتُ الاَْكْبَرُ.","persian":"تنگدستی، مرگ بزرگ‌تر است.","audio":null},{"id":"h164","kind":"hikmat","number":164,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ قَضى حَقَّ مَنْ لايَقْضى حَقَّهُ فَقَدْ عَبَدَهُ.","persian":"هرکس حق کسی را ادا کند که او حقش را ادا نمی‌کند، خود را بندهٔ او کرده است.","audio":null},{"id":"h165","kind":"hikmat","number":165,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا طاعَةَ لِمَخْلُوق فى مَعْصِيَةِ الْخالِقِ.","persian":"در نافرمانی از آفریدگار، نباید از هیچ آفریده‌ای اطاعت کرد.","audio":null},{"id":"h166","kind":"hikmat","number":166,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايُعابُ الْمَرْءُ بِتَأْخيرِ حَقِّهِ، اِنَّما يُعابُ مَنْ اَخَذَ ما لَيْسَ لَهُ.","persian":"انسان را برای به تأخیر انداختن گرفتن حقش سرزنش نمی‌کنند؛ بلکه برای گرفتن چیزی که حق او نیست سرزنش می‌کنند.","audio":null},{"id":"h167","kind":"hikmat","number":167,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الاِْعْجابُ يَمْنَعُ مِنَ الاِْزْدِيادِ.","persian":"خودپسندی مانع فزونی یافتن است.","audio":null},{"id":"h168","kind":"hikmat","number":168,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الاَْمْرُ قَريبٌ، وَ الاِْصْطِحابُ قَليلٌ.","persian":"پایان کار نزدیک است و زمان همراهی کوتاه.","audio":null},{"id":"h169","kind":"hikmat","number":169,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قَدْ اَضاءَ الْصُّبْحُ لِذى عَيْنَيْنِ.","persian":"صبح برای کسی که چشم بینا دارد روشن شده است.","audio":null},{"id":"h170","kind":"hikmat","number":170,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: تَرْكُ الذَّنْبِ اَهْوَنُ مِنْ طَلَبِ التَّوْبَةِ.","persian":"ترک گناه، آسان‌تر از درخواست توبه است.","audio":null},{"id":"h171","kind":"hikmat","number":171,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَمْ مِنْ اَكْلَة تَمْنَعُ اَكَلات.","persian":"چه‌بسا یک بار خوردن که آدمی را از خوردن‌های بسیار بازدارد.","audio":null},{"id":"h172","kind":"hikmat","number":172,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: النّاسُ اَعْداءُ ما جَهِلُوا.","persian":"مردم با آنچه نمی‌شناسند دشمنی می‌کنند.","audio":null},{"id":"h173","kind":"hikmat","number":173,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنِ اسْتَقْبَلَ وُجُوهَ الاْراءِ عَرَفَ مَواقِعَ الْخَطَأِ.","persian":"هرکس اندیشه‌های گوناگون را بررسی کند، جایگاه‌های خطا را می‌شناسد.","audio":null},{"id":"h174","kind":"hikmat","number":174,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَحَدَّ سِنانَ الْغَضَبِ لِلّهِ قَوِىَ عَلى قَتْلِ اَشِدّاءِ الْباطِلِ.","persian":"هرکس سرِ نیزهٔ خشم خود را برای خدا تیز کند، بر رویارویی با نیرومندترین باطل‌پیشگان توانا می‌شود.","audio":null},{"id":"h175","kind":"hikmat","number":175,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا هِبْتَ اَمْراً فَقَعْ فيهِ، فَاِنَّ شِدَّةَ تَوَقّيهِ اَعْظَمُ مِمّا تَخافُ مِنْهُ.","persian":"هرگاه از کاری ترسیدی، به آن روی آور؛ زیرا سختیِ پرهیز کردن از آن، بزرگ‌تر از چیزی است که از آن می‌ترسی.","audio":null},{"id":"h176","kind":"hikmat","number":176,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: آلَةُ الرِّياسَةِ سَعَةُ الصَّدْرِ.","persian":"ابزار پیشوایی، گشادگی سینه و بردباری است.","audio":null},{"id":"h177","kind":"hikmat","number":177,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اُزْجُرِ الْمُسىءَ بِثَوابِ الْمُحْسِنِ.","persian":"بدکار را با پاداش دادن به نیکوکار بازدار.","audio":null},{"id":"h178","kind":"hikmat","number":178,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اُحْصُدِ الشَّرَّ مِنْ صَدْرِ غَيْرِكَ بِقَلْعِهِ مِنْ صَدْرِكَ.","persian":"بدی را از دل دیگران با برکندن آن از دل خود ریشه‌کن کن.","audio":null},{"id":"h179","kind":"hikmat","number":179,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اللَّجاجَةُ تَسُلُّ الرّأْىَ.","persian":"لجاجت، اندیشهٔ درست را از میان می‌برد.","audio":null},{"id":"h180","kind":"hikmat","number":180,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الطَّمَعُ رِقُّ مُؤَبَّدٌ.","persian":"طمع، بندگیِ همیشگی است.","audio":null},{"id":"h181","kind":"hikmat","number":181,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ثَمَرَةُ التَّفْريطِ النَّدامَةُ، وَ ثَمَرَةُ الْحَزْمِ السَّلامَةُ.","persian":"میوهٔ کوتاهی، پشیمانی است و میوهٔ دوراندیشی، سلامت.","audio":null},{"id":"h182","kind":"hikmat","number":182,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا خَيْرَ فِى الصَّمْتِ عَنِ الْحُكْمِ، كَما اَنَّهُ لاخَيْرَ فِى الْقَوْلِ بِالْجَهْلِ.","persian":"در خاموشی از بیان حکمت، خیری نیست؛ همچنان‌که در سخن گفتن از روی نادانی خیری نیست.","audio":null},{"id":"h183","kind":"hikmat","number":183,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَا اخْتَلَفَتْ دَعْوَتانِ اِلاّ كانَتْ اِحْداهُما ضَلالَةً.","persian":"دو دعوت با یکدیگر اختلاف نمی‌کنند، مگر آنکه یکی از آن‌ها گمراهی است.","audio":null},{"id":"h184","kind":"hikmat","number":184,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما شَكَكْتُ فِى الْحَقِّ مُذْ اُريتُهُ.","persian":"از هنگامی که حق به من نشان داده شد، هرگز در آن شک نکردم.","audio":null},{"id":"h185","kind":"hikmat","number":185,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما كَذَبْتُ وَلا كُذِبْتُ، وَ لا ضَلَلْتُ وَ لا ضُلَّ بى.","persian":"نه دروغ گفته‌ام و نه به من دروغ گفته شده است؛ نه گمراه شده‌ام و نه گمراه کرده‌ام.","audio":null},{"id":"h186","kind":"hikmat","number":186,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِلظّالِمِ الْبادى غَداً بِكَفِّهِ عَضَّةٌ.","persian":"ستمگری که آغازگر ستم بوده است، فردا از پشیمانی دست خود را به دندان می‌گزد.","audio":null},{"id":"h187","kind":"hikmat","number":187,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الرَّحيلُ وَشيكٌ.","persian":"کوچ کردن نزدیک است.","audio":null},{"id":"h188","kind":"hikmat","number":188,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَبْدى صَفْحَتَهُ لِلْحَقِّ هَلَكَ.","persian":"هرکس آشکارا در برابر حق بایستد، هلاک می‌شود.","audio":null},{"id":"h189","kind":"hikmat","number":189,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ لَمْ يُنْجِهِ الصَّبْرُ اَهْلَكَهُ الْجَزَعُ.","persian":"کسی را که شکیبایی نجات ندهد، بی‌تابی هلاک می‌کند.","audio":null},{"id":"h190","kind":"hikmat","number":190,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: وَاعَجَباهْ! اَ تَكُونُ الْخِلافَةُ بِالصَّحابَةِ، وَ لاتَكُونُ بِالصَّحابَةِ وَالْقَرابَة؟! - وَ رُوِىَ لَهُ شِعْرٌ فى هذَا الْمَعْنى وَ هُوَ: فَاِنْ كُنْتَ بِالشُّورى مَلَكْتَ اُمُورَهُمْ فَكَيْفَ بِهذا وَالْمُشيرُونَ غُيَّبُ؟ وَ اِنْ كُنْتَ بِالْقُرْبى حَجَجْتَ خَصيمَهُمْ فَغَيْرُكَ اَوْلى بِالنَّبِىِّ وَ اَقْرَبُ!","persian":"شگفتا! آیا خلافت با استناد به همنشینی با پیامبر ثابت می‌شود، اما با همنشینی و خویشاوندی ثابت نمی‌شود؟ و در شعری که با همین مضمون از او نقل شده است، آمده است: «اگر از راه شورا بر آنان فرمانروا شدی، این چه شورایی بود که مشورت‌شوندگانش غایب بودند؟ و اگر با خویشاوندی با پیامبر بر رقیبان خود حجت آوردی، دیگری به پیامبر سزاوارتر و نزدیک‌تر است.»","audio":null},{"id":"h191","kind":"hikmat","number":191,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّمَا الْمَرْءُ فِى الدُّنْيا غَرَضٌ تَنْتَضِلُ فيهِ الْمَنايا، وَ نَهْبٌ تُبادِرُهُ الْمَصائِبُ. وَ مَعَ كُلِّ جُرْعَة شَرَقٌ، وَ فى كُلِّ اَكْلَة غَصَصٌ. وَ لايَنالُ الْعَبْدُ نِعْمَةً اِلاّ بِفِراقِ اُخْرى، وَ لايَسْتَقْبِلُ يَوْماً مِنْ عُمْرِهِ اِلاّ بِفِراقِ آخَرَ مِنْ اَجَلِهِ. فَنَحْنُ اَعْوانُ الْمَنُونِ، وَ اَنْفُسُنا نَصْبُ الْحُتُوفِ، فَمِنْ اَيْنَ نَرْجُو الْبَقاءَ؟ وَ هذَا اللَّيْلُ وَ النَّهارُ لَمْ يَرْفَعا مِنْ شَىْء شَرَفاً اِلاّ اَسْرَعَا الْكَرَّةَ فى هَدْمِ ما بَنَيا، وَ تَفْريقِ ما جَمَعا.","persian":"انسان در دنیا نشانه‌ای است که تیرهای مرگ به سوی او پرتاب می‌شوند و غنیمتی است که مصیبت‌ها برای ربودنش شتاب دارند. در هر نوشیدنی، بیمِ پریدن جرعه به گلو هست و در هر لقمه، بیمِ گلوگیر شدن. بنده به نعمتی نمی‌رسد مگر آنکه نعمت دیگری را از دست می‌دهد و روزی از عمرش را پشت سر نمی‌گذارد مگر آنکه روزی دیگر از زندگی‌اش کاسته می‌شود. پس ما همدمان مرگیم و جان‌هایمان هدف تیرهای نابودی‌اند؛ چگونه به ماندگاری امید ببندیم؟ شب و روز چیزی را بالا نبرده‌اند مگر آنکه در ویران کردن ساخته‌های خود و پراکندن گردآورده‌های خویش شتاب کرده‌اند.","audio":null},{"id":"h192","kind":"hikmat","number":192,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يا بْنَ آدَمَ، ما كَسَبْتَ فَوْقَ قُوتِكَ فَاَنْتَ فيهِ خازِنٌ لِغَيْرِكَ.","persian":"ای فرزند آدم! هرچه بیش از خوراک و نیاز خود به دست آوری، تنها خزانه‌دارِ آن برای دیگری هستی.","audio":null},{"id":"h193","kind":"hikmat","number":193,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِلْقُلُوبِ شَهْوَةً وَ اِقْبالاً وَ اِدْباراً، فَأْتُوها مِنْ قِبَلِ شَهْوَتِها وَ اِقْبالِها، فَاِنَّ الْقَلْبَ اِذا اُكْرِهَ عَمِىَ.","persian":"دل‌ها نیز خواهش و روی‌آوردن و روی‌گرداندن دارند؛ پس آن‌ها را هنگام رغبت و آمادگی به کار بگیرید، زیرا اگر دل را به زور به کاری وادارند، کور می‌شود.","audio":null},{"id":"h194","kind":"hikmat","number":194,"arabic":"وَ كانَ عَلَيْهِ السَّلامُ يَقُولُ: مَتى اَشْفى غَيْظى اِذا غَضِبْتُ؟ اَحينَ اَعْجِزُ عَنِ الاِْنْتِقامِ فَيُقالُ لى: لَوْ صَبَرْتَ؟! اَمْ حينَ اَقْدِرُ عَلَيْهِ فَيُقالُ لى: لَوْ عَفَوْتَ؟!","persian":"امام می‌فرمود: هنگامی که خشمگین می‌شوم، چه وقت باید خشم خود را فرونشانم؟ زمانی که توان انتقام ندارم و به من می‌گویند «اگر شکیبایی می‌کردی بهتر بود»؟ یا زمانی که قدرت انتقام دارم و به من می‌گویند «اگر می‌بخشیدی بهتر بود»؟","audio":null},{"id":"h195","kind":"hikmat","number":195,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ وَ قَدْ مَرَّ بِقَذَر عَلى مَزْبَلَة: هذا ما بَخِلَ بِهِ الْباخِلُونَ. - وَ فى خَبَر آخَرَ اَنَّهُ قالَ: هذا ما كُنْتُمْ تَتَنافَسُونَ فيهِ بِالاَْمْسِ.","persian":"هنگامی که از کنار آلودگیِ زباله‌دانی گذشت، فرمود: این همان چیزی است که بخیلان از بخشیدنش خودداری می‌کردند. و در روایت دیگری فرمود: این همان چیزی است که دیروز برای به دست آوردنش رقابت می‌کردید.","audio":null},{"id":"h196","kind":"hikmat","number":196,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَمْ يَذْهَبْ مِنْ مالِكَ ما وَعَظَكَ.","persian":"آنچه از مالت از دست رفته، اما برایت مایهٔ پند شده است، در حقیقت از دست نرفته است.","audio":null},{"id":"h197","kind":"hikmat","number":197,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ هذِهِ القُلُوبَ تَمَلُّ كَما تَمَلُّ الاَْبْدانُ، فَابْتَغُوا لَها طَرائِفَ الْحِكْمَةِ.","persian":"دل‌ها نیز مانند بدن‌ها خسته می‌شوند؛ پس برایشان حکمت‌های لطیف و تازه بجویید.","audio":null},{"id":"h198","kind":"hikmat","number":198,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لَمّا سَمِعَ قَوْلَ الْخَوارِج ِ «لا حُكْمَ اِلاّ لِلّهِ»: كَلِمَةُ حَقٍّ يُرادُ بِها باطِلٌ.","persian":"هنگامی که شعار خوارج را شنید که می‌گفتند «حکمی جز حکم خدا نیست»، فرمود: سخن حقی است که از آن مقصودی باطل دارند.","audio":null},{"id":"h199","kind":"hikmat","number":199,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى صِفَةِ الْغَوْغاءِ: هُمُ الَّذينَ اِذَا اجْتَمَعُوا غَلَبُوا، وَ اِذا تَفَرَّقُوا لَمْ يُعْرَفُوا. - وَ قيلَ: بَلْ قالَ عَلَيْهِ السَّلامُ: هُمُ الَّذينَ اِذَا اجْتَمَعُوا ضَرُّوا، وَ اِذا تَفَرَّقُوا نَفَعُوا. - فَقيلَ: قَدْ عَرَفْنا مَضَرَّةَ اجْتِماعِهِمْ، فَما مَنْفَعَةُ افْتِراقِهِمْ؟ فَقالَ: يَرْجِعُ اَصْحابُ الْمِهَنِ اِلى مِهْنَتِهِمْ فَيَنْتَفِعُ النّاسُ بِهِمْ، كَرُجُوع ِ الْبَنّاءِ اِلى بِنائِهِ، وَالنَّسّاج ِ اِلى مَنْسَجِهِ، وَالْخَبّازِ اِلى مَخْبَزِهِ.","persian":"دربارهٔ گروه‌های آشوبگر فرمود: «آنان کسانی‌اند که اگر گرد هم آیند چیره می‌شوند و اگر پراکنده شوند شناخته نمی‌شوند.» و در نقل دیگری آمده است: «اگر گرد هم آیند زیان می‌رسانند و اگر پراکنده شوند سود می‌بخشند.» پرسیدند: «زیانِ گرد آمدنشان را دانستیم، اما سودِ پراکندگی‌شان چیست؟» فرمود: «صاحبان پیشه به کار خود بازمی‌گردند و مردم از آنان بهره‌مند می‌شوند؛ مانند بنّا که به بنّایی، بافنده که به بافندگی و نانوا که به نانوایی بازمی‌گردد.»","audio":null},{"id":"h200","kind":"hikmat","number":200,"arabic":"وَ قَدْ اُتِىَ بِجان وَ مَعَهُ غَوْغاءُ، فَقالَ عَلَيْهِ السَّلامُ: لامَرْحَباًبِوُجُوه لاتُرى اِلاّ عِنْدَ كُلِّ سَوْاَة.","persian":"هنگامی که مجرمی را همراه گروهی از اوباش نزد او آوردند، فرمود: خوشامد مباد بر چهره‌هایی که جز در کنار هر کار زشتی دیده نمی‌شوند.","audio":null},{"id":"h201","kind":"hikmat","number":201,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ مَعَ كُلِّ اِنْسان مَلَكَيْنِ يَحْفَظانِهِ، فَاِذا جاءَ الْقَدَرُ خَلَّيا بَيْنَهُ وَ بَيْنَهُ، وَ اِنَّ الاَْجَلَ جُنَّةٌ حَصينَةٌ.","persian":"همراه هر انسانی دو فرشته‌اند که او را نگه می‌دارند؛ اما هنگامی که تقدیر الهی فرا رسد، او را به آن وامی‌گذارند. به‌راستی، مدت مقرر زندگی انسان سپری استوار برای اوست.","audio":null},{"id":"h202","kind":"hikmat","number":202,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ وَ قَدْ قالَ لَهُ طَلْحَةُ وَ الزُّبَيْرُ نُبايِعُكَ عَلى اَنّا شُرَكاؤُكَ فى هذَا الاَْمْرِ: لا، وَلكِنَّكُما شَريكانِ فِى الْقُوَّةِ وَ الاِْسْتِعانَةِ، وَ عَوْنانِ عَلَى الْعَجْزِ وَ الاَْوَدِ.","persian":"وقتی طلحه و زبیر گفتند «با تو بیعت می‌کنیم به شرط آنکه در این کار با تو شریک باشیم»، فرمود: نه؛ اما شما در نیرو بخشیدن و یاری رساندن شریک خواهید بود و در ناتوانی و سختی نیز یاور.","audio":null},{"id":"h203","kind":"hikmat","number":203,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَيُّهَا النّاسُ اتَّقُوا اللّهَ الَّذى اِنْ قُلْتُمْ سَمِعَ، وَ اِنْ اَضْمَرْتُمْ عَلِمَ. وَ بادِرُوا الْمَوْتَ الَّذى اِنْ هَرَبْتُمْ مِنْهُ اَدْرَكَكُمْ، وَ اِنْ اَقَمْتُمْ اَخَذَكُمْ، وَ اِنْ نَسيتُمُوهُ ذَكَرَكُمْ.","persian":"ای مردم! از خدایی پروا کنید که اگر سخن بگویید می‌شنود و اگر پنهان کنید می‌داند. برای مرگی آماده شوید که اگر از آن بگریزید به شما می‌رسد، اگر بمانید شما را می‌گیرد و اگر فراموشش کنید، شما را از یاد نمی‌برد.","audio":null},{"id":"h204","kind":"hikmat","number":204,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايُزَهِّدَنَّكَ فِى الْمَعْرُوفِ مَنْ لا يَشْكُرُهُ لَكَ، فَقَدْ يَشْكُرُكَ عَلَيْهِ مَنْ لا يَسْتَمْتِعُ بِشَىْء مِنْهُ، وَ قَدْ تُدْرِكُ مِنْ شُكْرِ الشّاكِرِ اَكْثَرَ مِمّا اَضاعَ الْكافِرُ، «وَاللّهُ يُحِبُّ الْمُحْسِنينَ».","persian":"ناسپاسیِ کسی که از نیکی تو سپاس نمی‌گوید، تو را از نیکوکاری بازندارد؛ چه‌بسا کسی که از نیکی‌ات بهره‌ای نبرده، قدردان آن باشد و تو از سپاس او بیش از آنچه ناسپاس ضایع کرده است بهره ببری؛ و خداوند نیکوکاران را دوست می‌دارد.","audio":null},{"id":"h205","kind":"hikmat","number":205,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كُلُّ وِعاء يَضيقُ بِما جُعِلَ فيهِ، اِلاّ وِعاءَ الْعِلْمِ فَاِنَّهُ يَتَّسِعُ بِهِ.","persian":"هر ظرفی با آنچه در آن می‌ریزند تنگ می‌شود، جز ظرف دانش که هرچه در آن جای گیرد، گشاده‌تر می‌شود.","audio":null},{"id":"h206","kind":"hikmat","number":206,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَوَّلُ عِوَضِ الْحَليمِ مِنْ حِلْمِهِ اَنَّ النّاسَ اَنْصارُهُ عَلَى الْجاهِلِ.","persian":"نخستین پاداشی که بردبار از بردباری خود می‌گیرد این است که مردم در برابر نادان به یاری او برمی‌خیزند.","audio":null},{"id":"h207","kind":"hikmat","number":207,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنْ لَمْ تَكُنْ حَليماً فَتَحَلَّمْ، فَاِنَّهُ قَلَّ مَنْ تَشَبَّهَ بِقَوْم اِلاّ اَوْشَكَ اَنْ يَكُونَ مِنْهُمْ.","persian":"اگر بردبار نیستی، خود را به بردباری وادار؛ زیرا کمتر کسی خود را شبیه گروهی می‌کند و سرانجام از آنان نمی‌شود.","audio":null},{"id":"h208","kind":"hikmat","number":208,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ حاسَبَ نَفْسَهُ رَبِحَ، وَ مَنْ غَفَلَ عَنْها خَسِرَ، وَ مَنْ خافَ اَمِنَ، وَ مَنِ اعْتَبَرَ اَبْصَرَ، وَ مَنْ اَبْصَرَ فَهِمَ، وَ مَنْ فَهِمَ عَلِمَ.","persian":"هرکس به حساب خود برسد سود می‌برد؛ هرکس غفلت کند زیان می‌بیند؛ هرکس بترسد ایمن می‌شود؛ هرکس عبرت بگیرد بینا می‌شود؛ هرکس بینا شود می‌فهمد؛ و هرکس بفهمد، دانا می‌شود.","audio":null},{"id":"h209","kind":"hikmat","number":209,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَتَعْطِفَنَّ الدُّنْيا عَلَيْنا بَعْدَ شِماسِها عَطْفَ الضَّرُوسِ عَلى وَلَدِها. وَ تَلا عَقيبَ ذلِكَ: «وَ نُريدُ اَنْ نَمُنَّ عَلَى الَّذينَ اسْتُضْعِفُوا فِى الاَْرْضِ وَ نَجْعَلَهُمْ اَئِمَّةً وَ نَجْعَلَهُمُ الْوارِثينَ».","persian":"دنیا پس از سرکشی، به سوی ما بازخواهد گشت؛ همچون شتر ماده‌ای که پس از سرکشی به سوی بچهٔ خود بازمی‌گردد. سپس این آیه را خواند: «و می‌خواهیم بر کسانی که در زمین ناتوان شمرده شدند منت نهیم و آنان را پیشوایان و وارثان قرار دهیم.»","audio":null},{"id":"h210","kind":"hikmat","number":210,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِتَّقُوا اللّهَ تَقِيَّةَ مَنْ شَمَّرَ تَجْريداً، وَ جَدَّ تَشْميراً، وَ اَكْمَشَ فى مَهَل، وَ بادَرَ عَنْ وَجَل، وَ نَظَرَ فى كَرَّةِ الْمَوْئِلِ، وَ عاقِبَةِ الْمَصْدَرِ، وَ مَغَبَّةِ الْمَرْجِعِ.","persian":"از خدا پروا کنید، همچون کسی که خود را برای کار آماده و از وابستگی‌ها آزاد کرده است؛ با کوشش، به چابکی برخاسته، در فرصت عمر به سوی نیکی شتافته، پیش از پایان مهلت به عمل پیش‌دستی کرده و دربارهٔ بازگشت خود، فرجام کار و حسابرسی اندیشیده است.","audio":null},{"id":"h211","kind":"hikmat","number":211,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْجُودُ حارِسُ الاَْعْراضِ. وَالْحِلْمُ فِدامُ السَّفيهِ. وَالْعَفْوُ زَكاةُ الظَّفَرِ. وَالسُّلُوُّ عِوَضُكَ مِمَّنْ غَدَرَ. وَالاِْسْتِشارَةُ عَيْنُ الْهِدايَةِ. وَ قَدْ خاطَرَ مَنِ اسْتَغْنَى بِرَأْيِهِ. وَالصَّبْرُ يُناضِلُ الْحِدْثانَ. وَالْجَزَعُ مِنْ اَعْوانِ الزَّمانِ. وَ اَشْرَفُ الْغِنى تَرْكُ الْمُنى. وَ كَمْ مِنْ عَقْل اَسير تَحْتَ هَوىً اَمير. وَ مِنَ التَّوْفيقِ حِفْظُ التَّجْرِبَةِ. وَ الْمَوَدَّةُ قَرابَةٌ مُسْتَفادَةٌ. وَلاتَأْمَنَنَّ مَلُولاً.","persian":"بخشندگی، نگهبان آبروست؛ بردباری، دهان نادان را می‌بندد؛ گذشت، زکات پیروزی است؛ فراموش کردن خیانت دیگری، جایگزین انتقام است؛ و مشورت، راه هدایت است. کسی که تنها به رأی خود تکیه کند، خویش را به خطر می‌اندازد. شکیبایی، سختی‌ها را دور می‌کند و بی‌تابی، به روزگار برای آسیب زدن یاری می‌رساند. برترین توانگری، ترک آرزوهاست. چه‌بسا خردی که اسیر خواهش‌های فرمانروا بر خویش باشد! حفظ تجربه از توفیق است و دوستی، خویشاوندیِ به‌دست‌آمده است. از کسی که دل‌آزرده است، آسوده‌خاطر مباش.","audio":null},{"id":"h212","kind":"hikmat","number":212,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عُجْبُ الْمَرْءِ بِنَفْسِهِ اَحَدُ حُسّادِعَقْلِهِ.","persian":"خودپسندی انسان، یکی از حسودان خرد اوست.","audio":null},{"id":"h213","kind":"hikmat","number":213,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَغْضِ عَلَى الْقَذى وَ اِلاّ لَمْ تَرْضَ اَبَداً.","persian":"از رنجش‌ها چشم بپوش؛ وگرنه هرگز خشنود نخواهی شد.","audio":null},{"id":"h214","kind":"hikmat","number":214,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ لانَ عُودُهُ كَثُفَتْ اَغْصانُهُ.","persian":"هرکس نرم‌خو باشد، شاخه‌های پیوند و دوستی‌اش فراوان می‌شود.","audio":null},{"id":"h215","kind":"hikmat","number":215,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْخِلافُ يَهْدِمُ الرَّأْىَ.","persian":"مخالفت و ناسازگاری، تدبیر را ویران می‌کند.","audio":null},{"id":"h216","kind":"hikmat","number":216,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ نالَ اسْتَطالَ.","persian":"هرکس به قدرت و جایگاه دست یابد، برتری‌جویی می‌کند.","audio":null},{"id":"h217","kind":"hikmat","number":217,"arabic":"وَقالَ عَلَيْهِ السَّلامُ: فى تَقَلُّبِ الاَْحْوالِ عِلْمُ جَواهِرِ الرِّجالِ.","persian":"گوهر انسان‌ها در دگرگونی روزگار شناخته می‌شود.","audio":null},{"id":"h218","kind":"hikmat","number":218,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: حَسَدُ الصَّديقِ مِنْ سُقْمِ الْمَوَدَّةِ.","persian":"حسادت به دوست، نشانهٔ بیماریِ دوستی است.","audio":null},{"id":"h219","kind":"hikmat","number":219,"arabic":"وَقالَ عَلَيْهِ السَّلامُ: اَكْثَرُ مَصارِع ِالْعُقُولِ تَحْتَ بُرُوقِ الْمَطامِع ِ.","persian":"بیشتر لغزشگاه‌های خرد در زیر درخشش طمع‌هاست.","audio":null},{"id":"h220","kind":"hikmat","number":220,"arabic":"وَقالَ عَلَيْهِ السَّلامُ: لَيْسَ مِنَ الْعَدْلِ الْقَضاءُ عَلَى الثِّقَةِ بِالظَّنِّ.","persian":"داوری بر ضد فردی مورد اعتماد، تنها بر پایهٔ گمان، از عدالت نیست.","audio":null},{"id":"h221","kind":"hikmat","number":221,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: بِئْسَ الزّادُ اِلَى الْمَعادِ الْعُدْوانُ عَلَى الْعِبادِ.","persian":"ستم به بندگان خدا، چه بد توشه‌ای برای آخرت است!","audio":null},{"id":"h222","kind":"hikmat","number":222,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مِنْ اَشْرَفِ اَعْمالِ الْكَريمِ غَفْلَتُهُ عَمّا يَعْلَمُ.","persian":"از بزرگوارانه‌ترین کارهای انسان کریم آن است که از برخی چیزهایی که می‌داند، خود را به نادانی بزند.","audio":null},{"id":"h223","kind":"hikmat","number":223,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ كَساهُ الْحَياءُ ثَوْبَهُ لَمْ يَرَالنّاسُ عَيْبَهُ.","persian":"کسی که جامهٔ حیا بر تن دارد، مردم عیب او را نمی‌بینند.","audio":null},{"id":"h224","kind":"hikmat","number":224,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: بِكَثْرَةِ الصَّمْتِ تَكُونُ الْهَيْبَةُ. وَ بِالنَّصَفَةِ يَكْثُرُ الْمُواصِلُونَ. وَبِالاِْفْضالِ تَعْظُمُ الاَْقْدارُ. وَ بِالتَّواضُع ِ تَتِمُّ النِّعْمَةُ، وَ بِاحْتِمالِ الْمُؤَنِ يَجِبُ السُّؤْدَدُ. وَ بِالسّيرَةِ الْعادِلَةِ يُقْهَرُ الْمُناوِئُ. وَ بِالْحِلْمِ عَنِ السَّفيهِ تَكْثُرُ الاَْنْصارُ عَلَيْهِ.","persian":"با سکوت بسیار، هیبت پدید می‌آید؛ با انصاف، پیوندها فزونی می‌یابد؛ با بخشش، منزلت‌ها بزرگ می‌شود؛ با فروتنی، نعمت کامل می‌شود؛ با تحمل دشواری‌ها، بزرگی و سروری استوار می‌گردد؛ با رفتار عادلانه، دشمن شکست می‌خورد؛ و با بردباری در برابر نادان، یاران انسان بر ضد او افزایش می‌یابند.","audio":null},{"id":"h225","kind":"hikmat","number":225,"arabic":"وَقالَ عَلَيْهِ السَّلامُ: الْعَجَبُ لِغَفْلَةِ الْحُسّادِ عَنْ سَلامَةِ الاَْجْسادِ.","persian":"در شگفتم از حسودانی که از آسیب حسد به تندرستی خود غافل‌اند.","audio":null},{"id":"h226","kind":"hikmat","number":226,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الطّامِعُ فى وِثاقِ الذُّلِّ.","persian":"طمع‌کار در بند خواری است.","audio":null},{"id":"h227","kind":"hikmat","number":227,"arabic":"وَ قَدْ سُئِلَ عَنِ الاْيمانِ فَقال عَلَيْهِ السَّلامُ: الاْيمانُ مَعْرِفَةٌ بِالْقَلْبِ، وَ اِقْرارٌ بِاللِّسانِ، وَعَمَلٌ بِالاَْرْكانِ.","persian":"ایمان، شناخت با دل، اقرار با زبان و عمل با اندام‌هاست.","audio":null},{"id":"h228","kind":"hikmat","number":228,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَصْبَحَ عَلَى الدُّنْيا حَزيناً فَقَدْ اَصْبَحَ لِقَضاءِ اللّهِ ساخِطاً. وَ مَنْ اَصْبَحَ يَشْكُو مُصيبَةً نَزَلَتْ بِهِ فَاِنَّما يَشْكُو رَبَّهُ. وَ مَنْ اَتى غَنِيّاً فَتَواضَعَ لَهُ لِغِناهُ ذَهَبَ ثُلُثا دينِهِ. وَ مَنْ قَرَاَ الْقُرْآنَ فَماتَ فَدَخَلَ النّارَ فَهُوَ مِمَّنْ كانَ يَتَّخِذُ آياتِ اللّهِ هُزُواً. وَ مَنْ لَهِجَ قَلْبُهُ بِحُبِّ الدُّنْيَا الْتاطَ قَلْبُهُ مِنْها بِثَلاث: هَمٍّ لايُغِبُّهُ، وَ حِرْص لايَتْرُكُهُ، وَ اَمَل لا يُدْرِكُهُ.","persian":"هرکس به خاطر دنیا اندوهگین شود، از قضای خدا ناخشنود شده است؛ و هرکس از مصیبتی که به او رسیده شکوه کند، از پروردگارش شکوه کرده است. هرکس در برابر توانگری به سبب ثروتش فروتنی کند، دو سوم دین خود را از دست داده است. و هرکس قرآن بخواند و پس از مرگ وارد دوزخ شود، از کسانی بوده که آیات خدا را به تمسخر می‌گرفته‌اند. هرکس دلش به محبت دنیا گرفتار شود، سه چیز از آن جدا نمی‌شود: اندوهی پایدار، حرصی رها‌نشدنی و آرزویی دست‌نیافتنی.","audio":null},{"id":"h229","kind":"hikmat","number":229,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَفى بِالْقَناعَةِ مُلْكاً، وَ بِحُسْنِ الْخُلُقِ نَعيماً. - وَ سُئِلَ عَلَيْهِ السَّلامُ عَنْ قَوْلِهِ تَعالى: «فَلَنُحْيِيَنَّهُ حَياةً طَيِّبَةً» فَقالَ: هِىَ الْقَناعَةُ.","persian":"قناعت برای فرمانروایی و خوش‌خویی برای برخورداری از نعمت کافی است. هنگامی که دربارهٔ «زندگی پاکیزه» در قرآن از امام پرسیدند، فرمود: آن زندگی، قناعت است.","audio":null},{"id":"h230","kind":"hikmat","number":230,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: شارِكُوا الَّذى قَدْ اَقْبَلَ عَلَيْهِ الرِّزْقُ، فَاِنَّهُ اَخْلَقُ لِلْغِنى، وَ اَجْدَرُ بِاِقْبالِ الْحَظِّ عَلَيْهِ.","persian":"با کسی که روزی به او روی آورده است شریک شوید؛ زیرا این شراکت به توانگری نزدیک‌تر و برای رسیدن به بهرهٔ بیشتر شایسته‌تر است.","audio":null},{"id":"h231","kind":"hikmat","number":231,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى قَوْلِهِ تَعالى: «اِنَّ اللّهَ يَأْمُرُ بِالْعَدْلِ وَالاِْحْسانِ»: الْعَدْلُ الاِْنْصافُ، وَ الاِْحْسانُ التَّفَضُّلُ.","persian":"دربارهٔ سخن خدای متعال که «خداوند به عدالت و احسان فرمان می‌دهد» فرمود: عدالت، انصاف است و احسان، بخششِ افزون بر حق.","audio":null},{"id":"h232","kind":"hikmat","number":232,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ يُعْطِ بِالْيَدِ الْقَصيرَةِ يُعْطَ بِالْيَدِ الطَّويلَةِ.","persian":"هرکس با دست کوتاه ببخشد، با دست بلند به او بخشیده می‌شود.","audio":null},{"id":"h233","kind":"hikmat","number":233,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لاِبْنِهِ الْحَسَنِ عَلَيْهِمَا السَّلامُ: لاتَدْعُوَنَّ اِلى مُبارَزَة، وَ اِنْ دُعيتَ اِلَيْها فَاَجِبْ، فَاِنَّ الدّاعِىَ اِلَيْها باغ، وَ الْباغِىَ مَصْرُوعٌ.","persian":"به فرزندش حسن (ع) فرمود: کسی را به مبارزه دعوت نکن؛ اما اگر تو را به مبارزه خواندند، بپذیر؛ زیرا آغازگر مبارزه تجاوزگر است و تجاوزگر به خاک می‌افتد.","audio":null},{"id":"h234","kind":"hikmat","number":234,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: خِيارُ خِصالِ النِّساءِ شِرارُ خِصالِ الرِّجالِ: الزَّهْوُ وَالْجُبْنُ وَالْبُخْلُ. فَاِذا كانَتِ الْمَرْاَةُ مَزْهُوَّةً لَمْ تُمَكِّنْ مِنْ نَفْسِها. وَ اِذا كانَتْ بَخيلَةً حَفِظَتْ مالَها وَ مالَ بَعْلِها. وَ اِذا كانَتْ جَبانَةً فَرِقَتْ مِنْ كُلِّ شَىْء يَعْرِضُ لَها.","persian":"بهترین خصلت‌های زنان، بدترین خصلت‌های مردان است: تکبر، بخل و ترس. زیرا اگر زن متکبر باشد، خود را در اختیار دیگران نمی‌گذارد؛ اگر بخیل باشد، مال خود و همسرش را حفظ می‌کند؛ و اگر ترسو باشد، از هر آنچه به او روی می‌آورد پرهیز می‌کند.","audio":null},{"id":"h235","kind":"hikmat","number":235,"arabic":"وَ قيلَ لَهُ عَلَيْهِ السَّلامُ: صِفْ لَنا الْعاقِلَ. فَقالَ عَلَيْهِ السَّلامُ: هُوَ الَّذى يَضَعُ الشَّىْءَ مَواضِعَهُ. - فَقيِلَ: فَصِفْ لَنَا الْجاهِلَ. فَقالَ: قَدْ فَعَلْتُ.","persian":"از امام خواستند خردمند را توصیف کند؛ فرمود: کسی است که هر چیز را در جای خود قرار می‌دهد. گفتند: پس نادان را توصیف کن. فرمود: همین کار را کردم.","audio":null},{"id":"h236","kind":"hikmat","number":236,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: وَاللّهِ لَدُنْياكُمْ هذِهِ اَهْوَنُ فى عَيْنى مِنْ عُراقِ خِنْزير فى يَدِ مَجْذُوم.","persian":"به خدا سوگند، این دنیای شما نزد من از استخوان بی‌گوشت خوکی که در دست فرد مبتلا به جذام باشد، بی‌ارزش‌تر است.","audio":null},{"id":"h237","kind":"hikmat","number":237,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ قَوْماً عَبَدُوا اللّهَ رَغْبَةً فَتِلْكَ عِبادَةُ التُّجّارِ. وَ اِنَّ قَوْماً عَبَدُوا اللّهَ رَهْبَةً فَتِلْكَ عِبادَةُ الْعَبيدِ. وَ اِنَّ قَوْماً عَبَدُوا اللّهَ شُكْراً فَتِلْكَ عِبادَةُ الاَْحْرارِ.","persian":"گروهی خدا را به امید پاداش عبادت می‌کنند؛ این عبادت بازرگانان است. گروهی از ترس کیفر او را می‌پرستند؛ این عبادت بردگان است. و گروهی از روی سپاسگزاری او را عبادت می‌کنند؛ این عبادت آزادگان است.","audio":null},{"id":"h238","kind":"hikmat","number":238,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْمَرْاَةُ شَرٌّ كُلُّها، وَ شَرُّ ما فيها اَنَّهُ لابُدَّ مِنْها.","persian":"زن سراسر شر است و بدتر از همه آنکه گریزی از او نیست.","audio":null},{"id":"h239","kind":"hikmat","number":239,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَطاعَ التَّوانِىَ ضَيَّعَ الْحُقُوقَ، وَ مَنْ اَطاعَ الْواشِىَ ضَيَّعَ الصَّديقَ.","persian":"هرکس از سستی و تنبلی پیروی کند، حق‌ها را تباه می‌سازد؛ و هرکس به سخن‌چین گوش بسپارد، دوستش را از دست می‌دهد.","audio":null},{"id":"h240","kind":"hikmat","number":240,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْحَجَرُ الْغَصيبُ فِى الدّارِ رَهْنٌ عَلى خَرابِها.","persian":"سنگ غصبی در ساختمان خانه، گروگان ویرانی آن است.","audio":null},{"id":"h241","kind":"hikmat","number":241,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَوْمُ الْمَظْلُومِ عَلَى الظّالِمِ اَشَدُّ مِنْ يَوْمِ الظّالِمِ عَلَى الْمَظْلُومِ.","persian":"روزی که ستمدیده از ستمگر داد می‌ستاند، بر ستمگر سخت‌تر از روزی است که ستمگر بر ستمدیده ستم می‌کند.","audio":null},{"id":"h242","kind":"hikmat","number":242,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِتَّقِ اللّهَ بَعْضَ التُّقى وَ اِنْ قَلَّ، وَ اجْعَلْ بَيْنَكَ وَ بَيْنَ اللّهِ سِتْراً وَ اِنْ رَقَّ.","persian":"از خدا پروا کن، هرچند این پروا اندک باشد؛ و میان خود و خدا پرده‌ای از حرمت قرار بده، هرچند نازک باشد.","audio":null},{"id":"h243","kind":"hikmat","number":243,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذَا ازْدَحَمَ الْجَوابُ خَفِىَ الصَّوابُ.","persian":"هرگاه پاسخ‌ها ازدحام کنند، پاسخ درست پنهان می‌ماند.","audio":null},{"id":"h244","kind":"hikmat","number":244,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِلّهِ تَعالى فى كُلِّ نِعْمَة حَقّاً، فَمَنْ اَدّاهُ زادَهُ مِنْها، وَ مَنْ قَصَّرَ فيهِ خاطَرَ بِزَوالِ نِعْمَتِهِ.","persian":"خداوند در هر نعمتی حقی دارد؛ هرکس آن را ادا کند، خدا نعمتش را افزون می‌کند؛ و هرکس در ادای آن کوتاهی کند، نعمتش را در معرض زوال قرار می‌دهد.","audio":null},{"id":"h245","kind":"hikmat","number":245,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا كَثُرَتِ الْمَقْدُرَةُ قَلَّتِ الشَّهْوَةُ.","persian":"هرگاه توانایی بیشتر شود، خواهش و میل کمتر می‌شود.","audio":null},{"id":"h246","kind":"hikmat","number":246,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِحْذَرُوا نِفارَ النِّعَمِ، فَما كُلُّ شارِد بِمَرْدُود.","persian":"از گریختن نعمت‌ها برحذر باشید؛ زیرا هر گریخته‌ای بازنمی‌گردد.","audio":null},{"id":"h247","kind":"hikmat","number":247,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْكَرَمُ اَعْطَفُ مِنَ الرَّحِمِ.","persian":"بزرگواری و کرم، بیش از خویشاوندی دل‌ها را به یکدیگر متمایل می‌کند.","audio":null},{"id":"h248","kind":"hikmat","number":248,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ ظَنَّ بِكَ خَيْراً فَصَدِّقْ ظَنَّهُ.","persian":"هرکس دربارهٔ تو گمان نیک دارد، گمان او را با کردار خود به حقیقت برسان.","audio":null},{"id":"h249","kind":"hikmat","number":249,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَفْضَلُ الاَْعْمالِ ما اَكْرَهْتَ نَفْسَكَ عَلَيْهِ.","persian":"برترین کارها آن‌هایی هستند که نفس خود را به انجامشان وامی‌داری.","audio":null},{"id":"h250","kind":"hikmat","number":250,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عَرَفْتُ اللّهَ سُبْحانَهُ بِفَسْخ ِ الْعَزائِمِ وَ حَلِّ الْعُقُودِ وَنَقْضِ الْهِمَمِ.","persian":"خداوند سبحان را از راه برهم خوردن تصمیم‌ها، گشوده شدن گره اراده‌ها و سست شدن عزم‌ها شناختم.","audio":null},{"id":"h251","kind":"hikmat","number":251,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَرارَةُ الدُّنْيا حَلاوَةُ الاْخِرَةِ، وَ حَلاوَةُ الدُّنْيا مَرارَةُ الاْخِرَةِ.","persian":"تلخی دنیا شیرینی آخرت است و شیرینی دنیا تلخی آخرت.","audio":null},{"id":"h252","kind":"hikmat","number":252,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: فَرَضَ اللّهُ الاْيْمانَ تَطْهيراً مِنَ الشِّرْكِ، وَالصّلاةَ تَنْزيهاً عَنِ الْكِبْرِ، وَ الزَّكاةَ تَسْبيباً لِلرِّزْقِ، وَالصِّيامَ ابْتِلاءً لاِِخْلاصِ الْخَلْقِ، وَ الْحَجَّ تَقْوِيَةً لِلدّينِ، وَالْجِهادَ عِزّاً لِلاِْسْلامِ، وَ الاَْمْرَ بِالْمَعْرُوفِ مَصْلَحَةً لِلْعَوامِّ، وَالنَّهْىَ عَنِ الْمُنْكَرِ رَدْعاً لِلسُّفَهاءِ، وَ صِلَةَ الرَّحِمِ مَنْماةً لِلْعَدَدِ، وَالْقِصاصَ حَقْناً لِلدِّماءِ، وَ اِقامَةَ الْحُدُودِ اِعْظاماً لِلْمَحارِمِ، وَ تَرْكَ شُرْبِ الْخَمْرِ تَحْصيناً لِلْعَقْلِ، وَ مُجانَبَةَ السَّرِقَةِ ايجاباً لِلْعِفَّةِ، وَ تَرْكَ الزِّنا تَحْصيناً لِلنَّسَبِ، وَ تَرْكَ اللِّواطِ تَكْثيراً لِلنَّسْلِ، وَالشَّهاداتِ اسْتِظْهاراً عَلَى الْمُجاحَداتِ، وَ تَرْكَ الْكَذِبِ تَشْريفاً لِلصِّدْقِ، وَالسَّلامُ اَماناً مِنَ الْمَخاوِفِ، وَ الاِْمامَةَ نِظاماً لِلاُْمَّةِ، وَالطّاعَةَ تَعْظيماً لِلاِْمامَةِ.","persian":"خداوند ایمان را برای پاک شدن از شرک، نماز را برای دور شدن از تکبر، زکات را برای فراهم شدن روزی، روزه را برای آزمودن اخلاص مردم، حج را برای استواری دین، جهاد را برای عزت اسلام، امر به معروف را برای اصلاح عموم مردم، نهی از منکر را برای بازداشتن نابخردان، پیوند خویشاوندی را برای فزونی شمار و نیرو، قصاص را برای پاسداری از خون‌ها، اجرای حدود را برای بزرگداشت حرمت‌ها، پرهیز از نوشیدنی‌های مست‌کننده را برای پاسداری از خرد، دوری از دزدی را برای حفظ پاک‌دامنی، ترک زنا را برای نگاهداری نسب، ترک لواط را برای افزایش نسل، گواهی دادن را برای پشتیبانی از حق در برابر انکار، ترک دروغ را برای بزرگداشت راستی، سلام کردن را برای ایمنی از بیم‌ها، امامت را برای سامان یافتن امت و فرمان‌برداری را برای بزرگداشت مقام امامت مقرر کرده است.","audio":null},{"id":"h253","kind":"hikmat","number":253,"arabic":"وَ كانَ عَلَيْهِ السَّلامُ يَقُولُ: اَحْلِفُوا الظّالِمَ اِذا اَرَدْتُمْ يَمينَهُ بِاَنَّهُ بَرىءٌ مِنْ حَوْلِ اللّهِ وَقُوَّتِهِ. فَاِنَّهُ اِذا حَلَفَ بِها كاذِباً عُوجِلَ الْعُقُوبَةَ. وَ اِذا حَلَفَ بِاللّهِ الَّذى لا اِلهَ اِلاّ هُوَ، لَمْ يُعاجَلْ، لاَِنَّهُ قَدْ وَحَّدَ اللّهَ سُبْحانَهُ.","persian":"اگر خواستید ستمگر را سوگند دهید، از او بخواهید سوگند یاد کند که از توان و نیروی خدا بیزار است؛ زیرا اگر به چنین سوگندی دروغ بگوید، کیفرش زود فرا می‌رسد. اما اگر به خدایی که جز او خدایی نیست سوگند یاد کند، در کیفرش شتاب نمی‌شود؛ زیرا خدا را یگانه دانسته است.","audio":null},{"id":"h254","kind":"hikmat","number":254,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يا بْنَ آدَمَ، كُنْ وَصِىَّ نَفْسِكَ فى مالِكَ، وَ اعْمَلْ فيهِ ما تُؤْثِرُ اَنْ يُعْمَلَ فيهِ مِنْ بَعْدِكَ.","persian":"ای فرزند آدم! خودت وصی مال خویش باش و با آن همان‌گونه رفتار کن که دوست داری پس از مرگت با آن رفتار شود.","audio":null},{"id":"h255","kind":"hikmat","number":255,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْحِدَّةُ ضَرْبٌ مِنَ الْجُنُونِ، لاَِنَّ صاحِبَها يَنْدَمُ، فَاِنْ لَمْ يَنْدَمْ فَجُنُونُهُ مُسْتَحْكِمٌ.","persian":"تندخویی گونه‌ای از دیوانگی است؛ زیرا فرد تندخو پشیمان می‌شود و اگر پشیمان نشود، دیوانگی‌اش ریشه‌دار است.","audio":null},{"id":"h256","kind":"hikmat","number":256,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: صِحَّةُ الْجَسَدِ مِنْ قِلَّةِ الْحَسَدِ.","persian":"تندرستی بدن از کم بودن حسادت است.","audio":null},{"id":"h257","kind":"hikmat","number":257,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِكُمَيْلِ بْنِ زِياد النَّخَعِىِّ: يا كُمَيْلُ! مُرْ اَهْلَكَ اَنْ يَرُوحُوا فى كَسْبِ الْمَكارِمِ، وَ يُدْلِجُوا فى حاجَةِ مَنْ هُوَ نائِمٌ. فَوَ الَّذى وَسِعَ سَمْعُهُ الاَْصْواتَ، ما مِنْ اَحَد اَوْدَعَ قَلْباً سُرُوراً اِلاّ وَ خَلَقَ اللّهُ لَهُ مِنْ ذلِكَ السُّرُورِ لُطْفاً، فَاِذا نَزَلَتْ بِهِ نائِبَةٌ جَرى اِلَيْها كَالْماءِ فِى انْحِدارِهِ حَتّى يَطْرُدَها عَنْهُ كَما تُطْرَدُ غَريبَةُ الاِْبِلِ.","persian":"به کمیل بن زیاد نخعی فرمود: ای کمیل! خانواده و نزدیکانت را فرمان ده که روزها در پی کسب فضیلت‌ها باشند و شب‌ها برای برآوردن نیاز کسانی که در خواب‌اند بکوشند. سوگند به آن‌که شنوایی‌اش همهٔ صداها را دربرگرفته است، هیچ‌کس دلی را شاد نمی‌کند مگر آنکه خدا از آن شادی، لطفی برای او می‌آفریند؛ پس هرگاه بلایی به او برسد، آن لطف همچون آبِ روان در سراشیبی به سوی آن بلا می‌رود و آن را از او دور می‌کند، همان‌گونه که شتر غریبه را از آبشخور دور می‌کنند.","audio":null},{"id":"h258","kind":"hikmat","number":258,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا اَمْلَقْتُمْ فَتاجِرُوا اللّهَ بِالصَّدَقَةِ.","persian":"هرگاه تهیدست شدید، با صدقه دادن با خدا معامله کنید.","audio":null},{"id":"h259","kind":"hikmat","number":259,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْوَفاءُ لاَِهْلِ الْغَدْرِ غَدْرٌ عِنْدَاللّهِ، وَ الْغَدْرُ بِاَهْلِ الْغَدْرِ وَفاءٌ عِنْدَاللّهِ.","persian":"وفاداری به پیمان‌شکنان نزد خدا پیمان‌شکنی است و پیمان‌شکنی با پیمان‌شکنان نزد خدا وفاداری است.","audio":null},{"id":"h260","kind":"hikmat","number":260,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَمْ مِنْ مُسْتَدْرَج بِالاِْحْسانِ اِلَيْهِ، وَ مَغْرُور بِالسَّتْرِ عَلَيْهِ، وَ مَفْتُون بِحُسْنِ الْقَوْلِ فيهِ. وَ مَا ابْتَلَى اللّهُ سُبْحانَهُ اَحَداً بِمِثْلِ الاِْمْلاءِ لَهُ.","persian":"چه بسیار کسان که با احسانی که به آنان می‌شود، به‌تدریج به دام می‌افتند؛ و با پوشیده ماندن عیب‌هایشان فریب می‌خورند و با سخنان نیک دیگران دربارهٔ خود، گرفتار فتنه می‌شوند. خداوند سبحان هیچ‌کس را به چیزی همانند مهلت دادن به او نیازموده است.","audio":null},{"id":"g001","kind":"gharaib","number":1,"arabic":"فى حَديثِهِ عَلَيْهِ السَّلامُ: فَاِذا كانَ ذلِكَ ضَرَبَ يَعْسُوبُ الدّينِ بِذَنَبِهِ، فَيَجْتَمِعُونَ اِلَيْهِ كَما يَجْتَمِعُ قَزَعُ الْخَريفِ.","persian":"در حدیثی از امام آمده است: «چون آن زمان فرارسد، پیشوای دین جایگاه خود را استوار می‌سازد و مردم همچون پاره‌ابرهای پراکندهٔ پاییزی گرد او جمع می‌شوند.»","audio":null},{"id":"g002","kind":"gharaib","number":2,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: هذَا الْخَطيبُ الشَّحْشَحُ.","persian":"در سخنی از امام آمده است: «این سخنران، زبردست و رساست.»","audio":null},{"id":"g003","kind":"gharaib","number":3,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: اِنَّ لِلْخُصُومَةِ قُحَماً.","persian":"در سخنی از امام آمده است: «ستیزه‌جویی، پرتگاه‌ها و مهلکه‌هایی دارد.»","audio":null},{"id":"g004","kind":"gharaib","number":4,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: اِذا بَلَغَ النِّساءُ نَصَّ الْحِقاقِ فَالْعَصَبَةُ أَوْلَى.","persian":"در سخنی از امام آمده است: «هنگامی که دختران به سن رشد و بلوغ برسند، خویشاوندان پدری (عصبه) سزاوارترند.»","audio":null},{"id":"g005","kind":"gharaib","number":5,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: اِنَّ الْإيمانَ يَبْدُو لُمْظَةً فِى الْقَلْبِ، كُلَّما ازْدادَ الْإيمانُ ازْدادَتِ اللُّمْظَةُ.","persian":"امام فرمود: «ایمان نخست همچون نقطه‌ای روشن در دل پدیدار می‌شود؛ هرچه ایمان فزونی یابد، آن نقطهٔ روشن نیز گسترده‌تر می‌شود.»","audio":null},{"id":"g006","kind":"gharaib","number":6,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: اِنَّ الرَّجُلَ اِذا كانَ لَهُ الدَّيْنُ الظَّنُونُ، يَجِبُ عَلَيْهِ اَنْ يُزَكِّيَهُ لِما مَضى، اِذا قَبَضَهُ.","persian":"در سخنی از امام آمده است: «اگر کسی طلبی داشته باشد که وصول آن نامطمئن است، هنگامی که آن را دریافت کند، زکات سال‌های گذشتهٔ آن را باید بپردازد.»","audio":null},{"id":"g007","kind":"gharaib","number":7,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ، اَنَّهُ شَيَّعَ جَيْشاً يُغْزيهِ، فَقالَ: اَعْذِبُوا عَنِ النِّساءِ مَا اسْتَطَعْتُمْ.","persian":"در حدیثی آمده است که امام هنگام بدرقهٔ سپاهی که برای نبرد می‌فرستاد، فرمود: «تا آنجا که می‌توانید از زنان دوری کنید.»","audio":null},{"id":"g008","kind":"gharaib","number":8,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: كَالْياسِرِ الْفالِج ِ، يَنْتَظِرُ اَوَّلَ فَوْزَة مِنْ قِداحِهِ.","persian":"در بخشی از سخن امام آمده است: «مانند کسی که در تیراندازیِ قمار برنده است و چشم به نخستین پیروزیِ تیرهای خود دوخته است.»","audio":null},{"id":"g009","kind":"gharaib","number":9,"arabic":"وَ فى حَديثِهِ عَلَيْهِ السَّلامُ: كُنّا اِذَا احْمَرَّ الْبَأْسُ اتَّقَيْنا بِرَسُولِ اللّهِ صَلّى اللّهُ عَلَيْهِ وَ آلِهِ، فَلَمْ يَكُنْ اَحَدٌ مِنّا اَقْرَبَ اِلَى الْعَدُوِّ مِنْهُ.","persian":"امام فرمود: «هنگامی که نبرد سخت و آتش جنگ شعله‌ور می‌شد، به پیامبر خدا (ص) پناه می‌بردیم؛ زیرا هیچ‌یک از ما از او به دشمن نزدیک‌تر نبود.»","audio":null},{"id":"h261","kind":"hikmat","number":261,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ، لَمّا بَلَغَهُ اِغارَةُ اَصْحابِ مُعاوِيَةَ عَلَى الاَْنْبارِ، فَخَرَجَ بِنَفْسِهِ ماشِياً حَتّى اَتَى النُّخَيْلَةَ، فَاَدْرَكَهُ النّاسُ وَ قالُوا: يا اَميرَ الْمُؤْمِنينَ، نَحْنُ نَكْفيكَهُمْ، فَقالَ عَلَيْهِ السَّلامُ: وَ اللّهِ ما تَكْفُونَنى اَنْفُسَكُمْ، فَكَيْفَ تَكْفُونَنى غَيْرَكُمْ؟! اِنْ كانَتِ الرَّعايا قَبْلى لَتَشْكُو حَيْفَ رُعاتِها، فَاِنِّى الْيَوْمَ لاََشْكُو حَيْفَ رَعِيَّتى، كاَنَّنِى الْمَقُودُ وَ هُمُ الْقادَةُ، اَوِ الْمَوْزُوعُ وَ هُمُ الْوَزَعَةُ! فَلَمَّا قالَ عَلَيْهِ السَّلامُ هَذَا الْقَوْلَ، تَقَدَّمَ اِلَيْهِ رَجُلانِ مِنْ اَصْحابِهِ فَقالَ اَحَدُهُما: اِنّى لا اَمْلِكُ اِلاّ نَفْسى وَ اَخى، فَمُرْنا بِاَمْرِكَ يا اَميرَالْمُؤْمِنينَ، نَنْفُذْ لَهُ. فَقالَ عَلَيْهِ السَّلامُ: وَ اَيْنَ تَقَعانِ مِمّا اُريدُ؟!","persian":"هنگامی که خبر یورش یاران معاویه به شهر انبار به امام علی (ع) رسید، شخصاً پیاده حرکت کرد تا به نخیله رسید. مردم به او پیوستند و گفتند: «ای امیر مؤمنان، ما برای مقابله با آنان کافی هستیم.» فرمود: «به خدا سوگند، شما حتی نمی‌توانید مرا از آسیب خودتان آسوده کنید؛ چگونه می‌توانید مرا از دیگران بی‌نیاز سازید؟ پیش از من مردم از ستم فرمانروایان خود شکایت می‌کردند، اما امروز من از ستم مردم خود شکایت دارم؛ گویی من فرمان‌بردارم و آنان فرمانده‌اند، یا من فرمان‌پذیرم و آنان فرمان می‌رانند!» پس از این سخن، دو تن از یارانش پیش آمدند. یکی گفت: «ای امیر مؤمنان، من جز بر خودم و برادرم اختیاری ندارم؛ به ما فرمان بده تا اجرا کنیم.» امام فرمود: «این دو نفر کجا و آنچه من می‌خواهم، کجا؟»","audio":null},{"id":"h262","kind":"hikmat","number":262,"arabic":"وَ قيلَ: اِنَّ الْحارِثَ بْنَ حَوْط اَتاهُ فَقالَ: اَتُرانى اَظُنُّ اَصْحابَ الْجَمَلِ كانُوا عَلى ضَلالَة؟ فَقالَ عَلَيْهِ السَّلامُ: يا حارِثُ، اِنَّكَ نَظَرْتَ تَحْتَكَ وَ لَمْ تَنْظُرْ فَوْقَكَ فَحِرْتَ! اِنَّكَ لَمْ تَعْرِفِ الْحَقَّ فَتَعْرِفَ اَهْلَهُ، وَ لَمْ تَعْرِفِ الْباطِلَ فَتَعْرِفَ مَنْ اَتاهُ. فَقالَ الْحارِثُ: فَاِنّى اَعْتَزِلُ مَعَ سَعْدِ بْنِ مالِك وَ عَبْدِاللّهِ ابْنِ عُمَرَ، فَقالَ عَلَيْهِ السَّلامُ: اِنَّ سَعْداً وَ عَبْدَاللّهِ بْنَ عُمَرَ لَمْ يَنْصُرا الْحَقَّ، وَ لَمْ يَخْذُلاَ الْباطِلَ.","persian":"نقل شده است که حارث بن حوط نزد امام آمد و گفت: «آیا گمان می‌کنی من باور دارم که اصحاب جمل گمراه بوده‌اند؟» فرمود: «ای حارث، تو به پایین نگریسته‌ای و بالا را ندیده‌ای؛ ازاین‌رو سرگردان شده‌ای. حق را نشناخته‌ای تا اهل حق را بشناسی و باطل را نشناخته‌ای تا پیروانش را بشناسی.» حارث گفت: «پس من نیز مانند سعد بن مالک و عبدالله بن عمر کنار می‌کشم.» امام فرمود: «سعد و عبدالله بن عمر نه حق را یاری کردند و نه باطل را خوار ساختند.»","audio":null},{"id":"h263","kind":"hikmat","number":263,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: صاحِبُ السُّلْطانِ كَراكِبِ الاَْسَدِ، يُغْبَطُ بِمَوْقِعِهِ وَ هُوَ اَعْلَمُ بِمَوْضِعِهِ.","persian":"هم‌نشینِ صاحب قدرت مانند کسی است که بر شیر سوار شده باشد؛ دیگران به جایگاهش غبطه می‌خورند، اما خود او از خطر آن آگاه‌تر است.","audio":null},{"id":"h264","kind":"hikmat","number":264,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَحْسِنُوا فى عَقِبِ غَيْرِكُمْ، تُحْفَظُوا فى عَقِبِكُمْ.","persian":"به بازماندگان دیگران نیکی کنید تا پس از شما نیز از بازماندگانتان نگهداری شود.","audio":null},{"id":"h265","kind":"hikmat","number":265,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ كَلامَ الْحُكَماءِ اِذا كانَ صَواباً كانَ دَواءً، وَ اِذا كانَ خَطَأً كانَ داءً.","persian":"سخن حکیمان اگر درست باشد، درمان است و اگر نادرست باشد، درد.","audio":null},{"id":"h266","kind":"hikmat","number":266,"arabic":"وَ سَاَلَهُ رَجُلٌ اَنْ يُعَرِّفَهُ مَا الاْيمانُ. فَقالَ عَلَيْهِ السَّلامُ: اِذا كانَ الْغَدُ فَأْتِنى حَتّى اُخْبِرَكَ عَلى اَسْماع ِ النّاسِ، فَاِنْ نَسيتَ مَقالَتى حَفِظَها عَلَيْكَ غَيْرُكَ، فَاِنَّ الْكَلامَ كَالشّارِدَةِ، يَنْقُفُها هذا، وَ يُخْطِئُها هذا.","persian":"مردی از امام خواست ایمان را برایش تعریف کند. فرمود: «فردا نزد من بیا تا در حضور مردم برایت توضیح دهم؛ اگر سخنم را فراموش کردی، دیگری آن را برایت به یاد داشته باشد، زیرا سخن چون شکار رمنده است: یکی آن را به چنگ می‌آورد و دیگری از دست می‌دهد.»","audio":null},{"id":"h267","kind":"hikmat","number":267,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يا بْنَ آدَمَ لا تَحْمِلْ هَمَّ يَوْمِكَ الَّذى لَمْ يَأْتِكَ عَلى يَوْمِكَ الَّذى قَدْ اَتاكَ، فَاِنَّهُ اِنْ يَكُ مِنْ عُمُرِكَ يَأْتِ اللّهُ فيهِ بِرِزْقِكَ.","persian":"ای فرزند آدم! اندوه روزی را که هنوز نرسیده، بر امروزت بار نکن؛ اگر آن روز از عمر تو باشد، خداوند روزی‌ات را در آن خواهد رساند.","audio":null},{"id":"h268","kind":"hikmat","number":268,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَحْبِبْ حَبيبَكَ هَوْناًمّا، عَسى اَنْ يَكُونَ بَغيضَكَ يَوْماًمّا، وَ اَبْغِضْ بَغيضَكَ هَوْناً مّا،عَسى اَنْ يَكُونَ حَبيبَكَ يَوْماًمّا.","persian":"دوستت را به‌اندازه دوست بدار؛ چه‌بسا روزی دشمنت شود. دشمنت را نیز به‌اندازه دشمن بدار؛ چه‌بسا روزی دوستت شود.","audio":null},{"id":"h269","kind":"hikmat","number":269,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: النّاسُ فِى الدُّنْيا عامِلانِ: عامِلٌ عَمِلَ فِى الدُّنْيا لِلدُّنْيا، قَدْ شَغَلَتْهُ دُنْياهُ عَنْ آخِرَتِهِ، يَخْشى عَلى مَنْ يَخْلُفُهُ الْفَقْرَ وَ يَأْمَنُهُ عَلى نَفْسِهِ، فَيُفْنى عُمُرَهُ فى مَنْفَعَةِ غَيْرِهِ. وَ عامِلٌ عَمِلَ فِى الدُّنْيا لِما بَعْدَها، فَجاءَهُ الَّذى لَهُ مِنَ الدُّنْيا بِغَيْرِ عَمَل، فَاَحْرَزَ الْحَظَّيْنِ مَعاً، وَ مَلَكَ الدَّارَيْنِ جَميعاً، فَاَصْبَحَ وَجيهاً عِنْدَ اللّهِ لا يَسْاَلُ اللّهَ حاجَةً فَيَمْنَعَهُ.","persian":"مردم در دنیا دو گونه عمل می‌کنند: یکی برای دنیا کار می‌کند و دنیا او را از آخرت بازمی‌دارد؛ برای فقرِ بازماندگانش نگران است اما از فقر خود غافل، و عمرش را صرف سود دیگران می‌کند. دیگری در دنیا برای جهان پس از آن کار می‌کند؛ سهمش از دنیا نیز بی‌آنکه برای آن کوشش جداگانه‌ای کند به او می‌رسد. بدین‌سان هر دو بهره را به دست می‌آورد، هر دو سرا را آباد می‌کند و نزد خداوند آبرومند می‌شود؛ هر حاجتی از او بخواهد، خداوند دریغ نمی‌کند.","audio":null},{"id":"h270","kind":"hikmat","number":270,"arabic":"وَ رُوِىَ اَنَّهُ ذُكِرَ عِنْدَ عُمَرَبْنِ الْخَطّابِ فى اَيّامِهِ حَلْىُ الْكَعْبَةِ وَ كَثْرَتُهُ، فَقالَ قَوْمٌ: لَوْ اَخَذْتَهُ فَجَهَّزْتَ بِهِ جُيُوشَ الْمُسْلِمينَ كانَ اَعْظَمَ لِلاَْجْرِ، وَ ما تَصْنَعُ الْكَعْبَةُ بِالْحَلْىِ؟! فَهَمَّ عُمَرُ بِذلِكَ، وَ سَاَلَ عَنْهُ اَميرَالْمُؤْمِنينَ عَلَيْهِ السَّلامُ فَقالَ: اِنَّ القُرْآنَ اُنْزِلَ عَلَى النَّبِىِّ صَلَّى اللّهُ عَلَيْهِ وَ آلِهِ وَ الاَْمْوالُ اَرْبَعَةٌ: اَمْوالُ الْمُسْلِمينَ فَقَسَّمَها بَيْنَ الْوَرَثَةِ فِى الْفَرائِضِ. وَالْفَىْءُ فَقَسَّمَهُ عَلى مُسْتَحِقّيهِ. وَالْخُمُسُ فَوَضَعَهُ اللّهُ حَيْثُ وَضَعَهُ. وَالصَّدَقاتُ فَجَعَلَهَا اللّهُ حَيْثُ جَعَلَها. وَ كانَ حَلْىُ الْكَعْبَةِ فيها يَوْمَئِذ، فَتَرَكَهُ اللّهُ عَلى حالِهِ، وَ لَمْ يَتْرُكْهُ نِسْياناً، وَ لَمْ يَخْفَ عَلَيْهِ مَكاناً، فَاَقِرَّهُ حَيْثُ اَقَرَّهُ اللّهُ وَ رَسُولُهُ. فَقالَ لَهُ عُمَرُ: لَوْلاكَ لاَفْتَضَحْنا. وَ تَرَكَ الْحَلْىَ بِحالِهِ.","persian":"نقل شده است که در روزگار عمر بن خطاب، از زیورهای فراوان کعبه سخن به میان آمد. گروهی گفتند: «اگر آن‌ها را برداری و با درآمدشان سپاه مسلمانان را تجهیز کنی، پاداش بیشتری خواهد داشت؛ کعبه چه نیازی به زیور دارد؟» عمر قصد چنین کاری کرد و با امیر مؤمنان مشورت نمود. امام فرمود: «قرآن هنگامی بر پیامبر (ص) نازل شد که اموال چهار گونه بود: دارایی مسلمانان که خداوند سهم وارثان را در آن تعیین کرد؛ فیء که آن را میان مستحقان تقسیم کرد؛ خمس که مصرفش را مشخص ساخت؛ و صدقات که جایگاهشان را تعیین فرمود. زیورهای کعبه نیز در همان روزگار وجود داشت و خداوند آن‌ها را به حال خود گذاشت، نه از روی فراموشی و نه از آن رو که جایشان را نمی‌دانست. پس تو نیز آن‌ها را در همان جایگاهی نگه دار که خدا و پیامبرش قرار داده‌اند.» عمر گفت: «اگر تو نبودی، رسوا می‌شدیم» و زیورها را دست‌نخورده گذاشت.","audio":null},{"id":"h271","kind":"hikmat","number":271,"arabic":"وَ رَوِىَ اَنَّهُ عَلَيْهِ السَّلامُ رُفِعَ اِلَيْهِ رَجُلانِ سَرَقا مِنْ مالِ اللّهِ: اَحَدُهُما عَبْدٌ مِنْ مالِ اللّهِ، وَ الاْخَرُ مِنْ عُرُوضِ النّاسِ. فَقالَ: اَمّا هذا فَهُوَ مِنْ مالِ اللّهِ وَلا حَدَّ عَلَيْهِ، مالُ اللّهِ اَكَلَ بَعْضُهُ بَعْضاً. وَ اَمَّا الاْخَرُ فَعَليْهِ الْحَدُّ. فَقَطَعَ يَدَهُ.","persian":"نقل شده است که دو مرد را به اتهام دزدی از بیت‌المال نزد امام آوردند: یکی برده‌ای متعلق به بیت‌المال و دیگری برده‌ای متعلق به مردم. فرمود: «اولی از اموال عمومی است و حدّ سرقت بر او جاری نمی‌شود؛ بخشی از مال خدا از بخش دیگر آن برداشته است. اما دومی مشمول حد است.» سپس دست او را برید.","audio":null},{"id":"h272","kind":"hikmat","number":272,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَوْ قَدِ اسْتَوَتْ قَدَماىَ مِنْ هذِهِ الْمَداحِضِ لَغَيَّرْتُ اَشْياءَ.","persian":"اگر پاهایم در این لغزشگاه‌ها استوار شود، چیزهایی را تغییر خواهم داد.","audio":null},{"id":"h273","kind":"hikmat","number":273,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِعْلَمُوا عِلْماً يَقيناً اَنَّ اللّهَ لَمْ يَجْعَلْ لِلْعَبْدِ وَ اِنْ عَظُمَتْ حيلَتُهُ، وَ اشْتَدَّتْ طِلْبَتُهُ، وَ قَوِيَتْ مَكيدَتُهُ اَكْثَرَ مِمّا سُمِّىَ لَهُ فِى الذِّكْرِ الْحَكيمِ، وَ لَمْ يَحُلْ بَيْنَ الْعَبْدِ فى ضَعْفِهِ وَ قِلَّةِ حيلَتِهِ وَ بَيْنَ اَنْ يَبْلُغَ ما سُمِّىَ لَهُ فِى الذِّكْرِ الْحَكيمِ. وَ الْعارِفُ لِهذا الْعامِلُ بِهِ اَعْظَمُ النّاسِ راحَةً فى مَنْفَعَة. وَ التّارِكُ لَهُ الشّاكُّ فيهِ اَعْظَمُ النّاسِ شُغُلاً فى مَضَرَّة. وَ رُبَّ مُنْعَم عَلَيْهِ مُسْتَدْرَجٌ بِالنُّعْمى، وَ رُبَّ مُبْتَلًى مَصْنُوعٌ لَهُ بِالْبَلْوى. فَزِدْ اَيُّهَا الْمُسْتَمِعُ فى شُكْرِكَ، وَ قَصِّرْ مِنْ عَجَلَتِكَ، وَ قِفْ عِنْدَ مُنْتَهى رِزْقِكَ.","persian":"به‌یقین بدانید خداوند برای هیچ بنده‌ای، هرچند چاره‌جویی‌اش فراوان، جست‌وجویش شدید و تدبیرش نیرومند باشد، بیش از روزیِ مقدرش در کتاب حکیم قرار نداده است؛ و ناتوانی و کم‌تدبیری هیچ بنده‌ای مانع رسیدن آن روزیِ مقدر نمی‌شود. کسی که این حقیقت را بشناسد و به آن عمل کند، بیش از همه آسوده و بهره‌مند است؛ و کسی که آن را نادیده بگیرد و در آن تردید کند، بیش از همه گرفتار و زیان‌دیده است. چه‌بسا برخورداری که نعمت، او را به‌تدریج به سوی کیفر می‌کشاند و چه‌بسا گرفتاری که بلا برای او مایه لطف است. پس ای شنونده، بر سپاسگزاری بیفزا، از شتاب بکاه و در مرز روزی مقدر خود بایست.","audio":null},{"id":"h274","kind":"hikmat","number":274,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَجْعَلُوا عِلْمَكُمْ جَهْلاً، وَ يَقينَكُمْ شَكّاً. اِذا عَلِمْتُمْ فَاعْمَلُوا، وَ اِذا تَيَقَّنْتُمْ فَاَقْدِمُوا.","persian":"دانشتان را به نادانی و یقینتان را به شک تبدیل نکنید؛ هنگامی که دانستید، عمل کنید و وقتی یقین یافتید، اقدام کنید.","audio":null},{"id":"h275","kind":"hikmat","number":275,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ الطَّمَعَ مُورِدٌ غَيْرُ مُصْدِر، وَ ضامِنٌ غَيْرُ وَفِىٍّ. وَ رُبَّما شَرِقَ شارِبُ الْماءِ قَبْلَ رِيِّهِ. وَ كُلَّما عَظُمَ قَدْرُ الشَّىْءِ الْمُتَنافَسِ فيهِ عَظُمَتِ الرَّزِيَّةُ لِفَقْدِهِ. وَ الاَْمانِىُّ تُعْمى اَعْيُنَ الْبَصائِرِ، وَالْحَظُّ يَأْتى مَنْ لايَأْتيهِ.","persian":"طمع چون آبشخوری است که واردش را بازنمی‌گرداند و ضمانت‌کننده‌ای است که وفا نمی‌کند. چه‌بسا نوشنده آب پیش از سیراب شدن به گلوگرفتگی دچار شود. هرچه ارزش چیزی که بر سرش رقابت می‌شود بیشتر باشد، اندوه از دست دادنش سنگین‌تر است. آرزوها چشم بصیرت را کور می‌کنند و گاهی بهره به سراغ کسی می‌رود که در پی آن نیست.","audio":null},{"id":"h276","kind":"hikmat","number":276,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اللّهُمَّ، اِنّى اَعُوذُ بِكَ مِنْ اَنْ تَحْسُنَ فى لامِعَةِ الْعُيُونِ عَلانِيَتى، وَ تَقْبُحَ فيما اُبْطِنُ لَكَ سَريرَتى، مُحافِظاً عَلى رِئاءِ النّاسِ مِنْ نَفْسى بِجَميع ِ ما اَنْتَ مُطَّلِعٌ عَلَيْهِ مِنّى، فَاُبْدِىَ لِلنّاسِ حُسْنَ ظاهِرى، وَ اُفْضِىَ اِلَيْكَ بِسُوءِ عَمَلى، تَقَرُّباً اِلى عِبادِكَ، وَ تَباعُداً مِنْ مَرْضاتِكَ.","persian":"خدایا، به تو پناه می‌برم از اینکه در نگاه مردم، آشکارم نیکو و در آنچه از تو پنهان می‌دارم، باطنم زشت باشد؛ از اینکه برای خوشایند مردم ظاهر خود را بیارایم، درحالی‌که تو از همه حقیقت من آگاهی، و نزد مردم چهره‌ای نیکو نشان دهم اما کردار بد خود را نزد تو آورم و با نزدیک شدن به بندگانت از خشنودی تو دور شوم.","audio":null},{"id":"h277","kind":"hikmat","number":277,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا وَالَّذى اَمْسَيْنا مِنْهُ فى غُبْرِ لَيْلَة دَهْماءَ، تَكْشِرُ عَنْ يَوْم اَغَرَّ، ما كانَ كَذا وَ كَذا.","persian":"نه؛ سوگند به آن‌که ما را به واپسین ساعات شب تاریک رساند، شبی که از پس آن روزی روشن سر برمی‌آورد، چنین و چنان نبوده است.","audio":null},{"id":"h278","kind":"hikmat","number":278,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قَليلٌ تَدُومُ عَلَيْهِ اَرْجى مِنْ كَثير مَمْلُول مِنْهُ.","persian":"کار اندکی که بر آن مداومت کنی، امیدبخش‌تر از کار فراوانی است که از آن خسته شوی.","audio":null},{"id":"h279","kind":"hikmat","number":279,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا اَضَرَّتِ النَّوافِلُ بِالْفَرائِضِ فَارْفُضُوها.","persian":"هرگاه کارهای مستحب به واجبات زیان رساند، مستحبات را کنار بگذارید.","audio":null},{"id":"h280","kind":"hikmat","number":280,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ تَذَكَّرَ بُعْدَ السَّفَرِ اسْتَعَدَّ.","persian":"هرکس دوری راه سفر آخرت را به یاد آورد، برای آن آماده می‌شود.","audio":null},{"id":"h281","kind":"hikmat","number":281,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَيْسَتِ الرَّوِيَّةُ كَالْمُعايَنَةِ مَعَ الاَْبْصارِ، فَقَدْ تَكْذِبُ الْعُيُونُ اَهْلَها، وَلايَغُشُّ الْعَقْلُ مَنِ اسْتَنْصَحَهُ.","persian":"اندیشیدن مانند دیدن با چشم نیست؛ گاه چشم‌ها به صاحب خود خطا نشان می‌دهند، اما عقل به کسی که از او خیرخواهی بخواهد خیانت نمی‌کند.","audio":null},{"id":"h282","kind":"hikmat","number":282,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: بَيْنَكُمْ وَ بَيْنَ الْمَوْعِظَةِ حِجابٌ مِنَ الْغِرَّةِ.","persian":"میان شما و پذیرش اندرز، پرده‌ای از فریب‌خوردگی و غفلت قرار گرفته است.","audio":null},{"id":"h283","kind":"hikmat","number":283,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: جاهِلُكُمْ مُزْدادٌ، وَ عالِمُكُمْ مُسَوِّفٌ.","persian":"نادانِ شما بر نادانی خود می‌افزاید و دانای شما عمل را به تأخیر می‌اندازد.","audio":null},{"id":"h284","kind":"hikmat","number":284,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قَطَعَ الْعِلْمُ عُذْرَ الْمُتَعَلِّلينَ.","persian":"دانش، راه بهانه‌جویی را بر بهانه‌جویان بسته است.","audio":null},{"id":"h285","kind":"hikmat","number":285,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كُلُّ مُعاجَل يَسْاَلُ الاِْنْظارَ، وَ كُلُّ مُؤَجَّل يَتَعَلَّلُ بِالتَّسْويفِ.","persian":"هرکس مرگش نزدیک شده باشد مهلت می‌خواهد، و هرکس مهلت یافته باشد کار را به فردا می‌اندازد.","audio":null},{"id":"h286","kind":"hikmat","number":286,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما قالَ النّاسُ لِشَىْء «طُوبى لَهُ» اِلاّ وَ قَدْ خَبَاَ لَهُ الدَّهْرُ يَوْمَ سَوْء.","persian":"هرگاه مردم درباره کسی بگویند «خوشا به حال او»، روزگار برای او نیز روزی ناخوش در آستین دارد.","audio":null},{"id":"h287","kind":"hikmat","number":287,"arabic":"وَ قَدْ سُئِلَ عَنِ الْقَدَرِ فَقالَ عَلَيْهِ السَّلامُ: طَريقٌ مُظْلِمٌ فَلاتَسْلُكُوهُ، وَ بَحْرٌ عَميقٌ فَلاتَلِجُوهُ، وَ سِرُّ اللّهِ فَلاتَتَكَلَّفُوهُ.","persian":"از امام درباره تقدیر پرسیدند. فرمود: «راهی تاریک است؛ در آن گام نگذارید. دریایی ژرف است؛ به آن وارد نشوید. راز خداست؛ خود را به تکلّفِ گشودن آن نیندازید.»","audio":null},{"id":"h288","kind":"hikmat","number":288,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا اَرْذَلَ اللّهُ عَبْداً حَظَرَ عَلَيْهِ الْعِلْمَ.","persian":"هرگاه خداوند بنده‌ای را خوار سازد، دانش را از او دریغ می‌دارد.","audio":null},{"id":"h289","kind":"hikmat","number":289,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كانَ لى فيما مَضى اَخٌ فِى اللّهِ، وَ كانَ يُعْظِمُهُ فى عَيْنى صِغَرُ الدُّنْيا فى عَيْنِهِ. وَ كانَ خارِجاً مِنْ سُلْطانِ بَطْنِهِ، فَلايَشْتَهى ما لايَجِدُ، وَلايُكْثِرُ اِذا وَجَدَ. وَ كانَ اَكْثَرَ دَهْرِهِ صامِتاً، فَاِنْ قالَ بَذَّ الْقائِلينَ، وَ نَقَعَ غَليلَ السّائِلينَ. وَ كانَ ضَعيفاً مُسْتَضْعَفاً، فَاِنْ جاءَ الْجِدُّ فَهُوَ لَيْثٌ غاد وَ صِلُّ واد. لايُدْلى بِحُجَّة حَتّى يَأْتِىَ قاضِياً. وَ كانَ لايَلُومُ اَحَداً عَلى ما يَجِدُ الْعُذْرَ فى مِثْلِهِ حَتّى يَسْمَعَ اعْتِذارَهُ. وَ كانَ لايَشْكُو وَجَعاً اِلاّ عِنْدَ بُرْئِهِ. وَ كانَ يَقُولُ ما يَفْعَلُ، وَ لايَقُولُ ما لايَفْعَلُ. وَ كانَ اِذا غُلِبَ عَلَى الْكَلامِ لَمْ يُغْلَبْ عَلَى السُّكُوتِ، وَ كانَ عَلى ما يَسْمَعُ اَحْرَصَ مِنْهُ عَلى اَنْ يَتَكَلَّمَ. وَ كانَ اِذا بَدَهَهُ اَمْرانِ نَظَرَ اَيُّهُما اَقْرَبُ اِلَى الْهَوى فَيُخالِفُهُ. فَعَلَيْكُمْ بِهذِهِ الْخَلائِقِ فَالْزَمُوها وَ تَنافَسُوا فيها، فَاِنْ لَمْ تَسْتَطيعُوها فَاعْلَمُوا اَنَّ اَخْذَ الْقَليلِ خَيْرٌ مِنْ تَرْكِ الْكَثيرِ.","persian":"در گذشته برادری دینی داشتم که در نظرم بزرگ می‌نمود، زیرا دنیا در چشم او کوچک بود. زیر فرمان شکم نبود: آنچه نمی‌یافت آرزو نمی‌کرد و چون می‌یافت زیاده‌روی نمی‌کرد. بیشتر اوقات خاموش بود؛ اما اگر سخن می‌گفت، بر سخنوران پیشی می‌گرفت و تشنگی پرسشگران را فرومی‌نشاند. در ظاهر فروتن و ناتوان شمرده می‌شد، ولی هنگام جدیت چون شیری خشمگین و ماری دلیر بود. تا نزد داور نمی‌رفت، دلیل خود را آشکار نمی‌کرد. کسی را برای کاری که ممکن بود عذری داشته باشد سرزنش نمی‌کرد، مگر آنکه عذرش را می‌شنید. از دردی شکایت نمی‌کرد مگر پس از بهبود. آنچه می‌گفت انجام می‌داد و آنچه انجام نمی‌داد بر زبان نمی‌آورد. اگر در گفتار مغلوبش می‌کردند، در سکوت مغلوب نمی‌شد. به شنیدن مشتاق‌تر بود تا سخن گفتن. هنگامی که میان دو کار مردد می‌شد، می‌نگریست کدام‌یک به هوای نفس نزدیک‌تر است و با همان مخالفت می‌کرد. این خصلت‌ها را پاس بدارید و در به‌دست‌آوردنشان با یکدیگر رقابت کنید؛ و اگر به همه آن‌ها دست نمی‌یابید، بدانید به دست آوردن اندک بهتر از وانهادن همه است.","audio":null},{"id":"h290","kind":"hikmat","number":290,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَوْ لَمْ يَتَوَعَّدِ اللّهُ عَلى مَعْصِيَتِهِ، لَكانَ يَجِبُ اَنْ لا يُعْصى شُكْراً لِنِعَمِهِ.","persian":"اگر خداوند بر نافرمانی خود وعده عذاب هم نمی‌داد، سپاس نعمت‌هایش اقتضا می‌کرد که نافرمانی نشود.","audio":null},{"id":"h291","kind":"hikmat","number":291,"arabic":"وَ قالَ عَلَيْهِ السّلامُ، وَ قَدْ عَزَّى الاَْشْعَثَ بْنَ قَيْس عَنِ ابْن لَهُ: يا اَشْعَثُ، اِنْ تَحْزَنْ عَلَى ابْنِكَ فَقَدِ اسْتَحَقَّتْ مِنْكَ ذلِكَ الرَّحِمُ، وَ اِنْ تَصْبِرْ فَفِى اللّهِ مِنْ كُلِّ مُصيبَة خَلَفٌ. يا اَشْعَثُ، اِنْ صَبَرْتَ جَرى عَلَيْكَ الْقَدَرُ وَ اَنْتَ مأْجُورٌ، وَ اِنْ جَزِعْتَ جَرى عَلَيْكَ الْقَدَرُ وَ اَنْتَ مَأْزُورٌ. يا اَشْعَثُ، ابْنُكَ سَرَّكَ وَ هُوَ بَلاءٌ وَ فِتْنَةٌ، وَ حَزنَكَ وَ هُوَ ثَوابٌ وَ رَحْمَةٌ.","persian":"امام در سوگ فرزند اشعث بن قیس به او فرمود: «ای اشعث، اگر بر فرزندت اندوهگینی، پیوند خویشاوندی چنین حقی بر تو دارد؛ و اگر شکیبایی کنی، خداوند برای هر مصیبتی جایگزینی قرار داده است. ای اشعث، اگر صبر کنی تقدیر خدا جاری می‌شود و پاداش می‌بری؛ و اگر بی‌تابی کنی باز هم تقدیر جاری می‌شود اما گناهکار خواهی بود. ای اشعث، فرزندت تو را شاد کرد درحالی‌که آزمون و گرفتاری بود، و اندوهگینت کرد درحالی‌که برایت پاداش و رحمت است.»","audio":null},{"id":"h292","kind":"hikmat","number":292,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ عَلى قَبْرِ رَسُولِ اللّهِ صَلّى اللّهِ عَلَيْهِ وَ آلِهِ ساعَةَ دَفْنِهِ: اِنَّ الصَّبْرَ لَجَميلٌ اِلاّ عَنْكَ، وَ اِنَّ الْجَزَعَ لَقَبيحٌ اِلاّ عَلَيْكَ. وَ اِنَّ الْمُصابَ بِكَ لَجَليلٌ، وَ اِنَّهُ قَبْلَكَ وَ بَعْدَكَ لَجَلَلٌ.","persian":"امام هنگام دفن پیامبر خدا (ص) کنار قبر او فرمود: «شکیبایی زیباست مگر در مصیبت تو، و بی‌تابی ناپسند است مگر در سوگ تو. مصیبت از دست دادن تو بس بزرگ است و هر مصیبتی پیش از تو و پس از تو در برابر آن کوچک می‌نماید.»","audio":null},{"id":"h293","kind":"hikmat","number":293,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَصْحَبِ الْمائِقَ، فَاِنَّهُ يُزَيِّنُ لَكَ فِعْلَهُ، وَ يَوَدُّ اَنْ تَكُونَ مِثْلَهُ.","persian":"با نادان همنشین مشو؛ زیرا کار خود را در نظرت زیبا جلوه می‌دهد و دوست دارد تو نیز مانند او باشی.","audio":null},{"id":"h294","kind":"hikmat","number":294,"arabic":"وَ قَدْ سُئِلَ عَنْ مَسافَةِ ما بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، فَقالَ عَلَيْهِ السَّلامُ: مَسيرَةُ يَوْم لِلشَّمْسِ.","persian":"از امام پرسیدند فاصله مشرق تا مغرب چقدر است. فرمود: «به‌اندازه مسیر یک‌روزه خورشید.»","audio":null},{"id":"h295","kind":"hikmat","number":295,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَصْدِقاؤُكَ ثَلاثَةٌ، وَ اَعْداؤُكَ ثَلاثَةٌ: فَاَصْدِقاؤُكَ: صَديقُكَ، وَ صَديقُ صَديقِكَ، وَ عَدُوُّ عَدُوِّكَ. وَ اَعْداؤُكَ: عَدُوُّكَ، وَ عَدُوُّ صَديقِكَ، وَ صَديقُ عَدُوِّكَ.","persian":"دوستان تو سه گروه‌اند: دوست تو، دوستِ دوست تو و دشمنِ دشمن تو. دشمنانت نیز سه گروه‌اند: دشمن تو، دشمنِ دوست تو و دوستِ دشمن تو.","audio":null},{"id":"h296","kind":"hikmat","number":296,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِرَجُل رَآهُ يَسْعى عَلى عَدُوٍّ لَهُ بِما فيهِ اِضْرارٌ بِنَفْسِهِ: اِنَّما اَنْتَ كَالطّاعِنِ نَفْسَهُ لِيَقْتُلَ رِدْفَهُ.","persian":"به مردی که برای زیان رساندن به دشمن خود به کاری دست زده بود که خودش نیز از آن زیان می‌دید، فرمود: «تو مانند کسی هستی که برای کشتن فردِ نشسته پشت سرش، به خود نیزه بزند.»","audio":null},{"id":"h297","kind":"hikmat","number":297,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما اَكْثَرَ الْعِبَرَ وَ اَقَلَّ الاِْعْتِبارَ!","persian":"چه بسیارند مایه‌های عبرت و چه اندکند عبرت‌گیرندگان!","audio":null},{"id":"h298","kind":"hikmat","number":298,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ بالَغَ فى الْخُصُومَةِ اَثِمَ، وَ مَنْ قَصَّرَ فيها ظُلِمَ، وَلايَسْتَطيعُ اَنْ يَتَّقِىَ اللّهَ مَنْ خاصَمَ.","persian":"هرکس در دشمنی زیاده‌روی کند گناهکار می‌شود و هرکس کوتاهی کند مورد ستم قرار می‌گیرد؛ کسی که پیوسته به ستیزه‌جویی مشغول باشد نمی‌تواند تقوای الهی را رعایت کند.","audio":null},{"id":"h299","kind":"hikmat","number":299,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما اَهَمَّنى ذَنْبٌ اُمْهِلْتُ بَعْدَهُ حَتّى اُصَلِّىَ رَكْعَتَيْنِ؛ وَ اَسْأَلُ اللّهَ الْعافِيَةَ.","persian":"گناهی که پس از آن به من مهلت داده شود تا دو رکعت نماز بخوانم و از خدا عافیت بخواهم، مرا نگران نمی‌کند.","audio":null},{"id":"h300","kind":"hikmat","number":300,"arabic":"وَ سُئِلَ عَلَيْهِ السَّلامُ: كَيْفَ يُحاسِبُ اللّهُ الْخَلْقَ عَلى كَثْرَتِهِمْ؟ فَقالَ: كَما يَرْزُقُهُمْ عَلى كَثْرَتِهِمْ. فَقيلَ: كَيْفَ يُحاسِبُهُمْ وَ لايَرَوْنَهُ؟ فَقالَ: كَما يَرْزُقُهُمْ وَ لايَرَوْنَهُ.","persian":"از امام پرسیدند: «خدا چگونه به حساب این همه آفریده رسیدگی می‌کند؟» فرمود: «همان‌گونه که به همه آنان روزی می‌دهد.» گفتند: «چگونه حسابشان را می‌رسد، درحالی‌که او را نمی‌بینند؟» فرمود: «همان‌گونه که به آنان روزی می‌دهد و او را نمی‌بینند.»","audio":null},{"id":"h301","kind":"hikmat","number":301,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رَسُولُكَ تَرْجُمانُ عَقْلِكَ، وَ كِتابُكَ اَبْلَغُ ما يَنْطِقُ عَنْكَ.","persian":"فرستاده تو زبان گویای اندیشه توست، و نامه‌ات رساترین چیزی است که به جای تو سخن می‌گوید.","audio":null},{"id":"h302","kind":"hikmat","number":302,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَا الْمُبْتَلَى الَّذى قَدِ اشْتَدَّ بِهِ الْبَلاءُ بِاَحْوَجَ اِلَى الدُّعاءِ مِنَ الْمُعافَى الَّذى لايَأْمَنُ الْبَلاءَ.","persian":"کسی که گرفتاری سختی دارد، به دعا نیازمندتر از انسان سالمی نیست که از گرفتار شدن در امان نیست.","audio":null},{"id":"h303","kind":"hikmat","number":303,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: النّاسُ اَبْناءُ الدُّنْيا، وَلايُلامُ الرَّجُلُ عَلى حُبِّ اُمِّهِ.","persian":"مردم فرزندان دنیایند و هیچ‌کس را به سبب دوست داشتن مادرش سرزنش نمی‌کنند.","audio":null},{"id":"h304","kind":"hikmat","number":304,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ الْمِسْكينَ رَسُولُ اللّهِ، فَمَنْ مَنَعَهُ فَقَدْ مَنَعَ اللّهَ، وَ مَنْ اَعْطاهُ فَقَدْ اَعْطَى اللّهَ.","persian":"نیازمند فرستاده خداست؛ هرکس او را محروم کند، خدا را محروم کرده است و هرکس به او ببخشد، به خدا بخشیده است.","audio":null},{"id":"h305","kind":"hikmat","number":305,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما زَنى غَيُورٌ قَطُّ.","persian":"انسان غیرتمند هرگز زنا نمی‌کند.","audio":null},{"id":"h306","kind":"hikmat","number":306,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَفى بِالاَْجَلِ حارِساً.","persian":"برای نگهبانی از انسان، اجلِ تعیین‌شده بس است.","audio":null},{"id":"h307","kind":"hikmat","number":307,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَنامُ الرَّجُلُ عَلى الثُّكْلِ، وَ لايَنامُ عَلَى الْحَرَبِ.","persian":"آدمی می‌تواند با اندوهِ از دست دادن فرزند به خواب رود، اما با اندوهِ غارت شدن مالش خواب از چشمش می‌رود.","audio":null},{"id":"h308","kind":"hikmat","number":308,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَوَدَّةُ الاْباءِ قَرابَةٌ بَيْنَ الاَْبْناءِ، وَ الْقَرَابَةُ اِلَى الْمَوَدَّةِ اَحْوَجُ مِنْ الْمَوَدَّةِ اِلَى الْقَرابَةِ.","persian":"دوستی پدران، میان فرزندان پیوند خویشاوندی می‌آفریند؛ و خویشاوندی بیش از آنکه دوستی به آن نیاز داشته باشد، به دوستی نیازمند است.","audio":null},{"id":"h309","kind":"hikmat","number":309,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِتَّقُوا ظُنُونَ الْمُؤْمِنينَ، فَاِنَّ اللّهَ تَعالى جَعَلَ الْحَقَّ عَلى اَلْسِنَتِهِمْ.","persian":"از گمان مؤمنان پروا کنید؛ زیرا خداوند حق را بر زبان آنان جاری ساخته است.","audio":null},{"id":"h310","kind":"hikmat","number":310,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لا يَصْدُقُ ايمانُ عَبْد حَتّى يَكُونَ بِما فى يَدِ اللّهِ سُبْحانَهُ اَوْثَقَ مِنْهُ بِما فى يَدِهِ.","persian":"ایمان بنده راستین نمی‌شود تا آنکه اعتمادش به آنچه نزد خداست، از اعتمادش به آنچه در دست خود دارد بیشتر باشد.","audio":null},{"id":"h311","kind":"hikmat","number":311,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لاَِنَسِ بْنِ مالِك وَ قَدْ كانَ بَعَثَهُ اِلَى طَلْحَةَ وَالزُّبَيْرِ لَمّا جاءَ اِلَى الْبَصْرَةِ يُذَكِّرُهُما شَيْئاً قَدْ سَمِعَهُ مِنْ رَسُولِ اللّهِ صَلَّى اللّهُ عَلَيْهِ وَ آلِهِ فى مَعْناهُما. فَلَوى عَنْ ذلِكَ، فَرَجَعَ اِلَيْهِ فَقالَ: اِنِّى اُنْسيتُ ذلِكَ الاَْمْرَ: اِنْ كُنْتَ كاذِباً فَضَرَبَكَ اللّهُ بِها بَيْضاءَ لامِعَةً لاتُواريهَا الْعِمامَةُ.","persian":"هنگامی که امام برای یادآوری سخنی از پیامبر (ص) درباره طلحه و زبیر، انس بن مالک را نزد آن دو فرستاد، انس از انجام فرمان خودداری کرد و گفت: «آن سخن را فراموش کرده‌ام.» امام فرمود: «اگر دروغ می‌گویی، خداوند تو را به لکه‌ای سفید و نمایان گرفتار کند که عمامه آن را نپوشاند.»","audio":null},{"id":"h312","kind":"hikmat","number":312,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِلْقُلُوبِ اِقْبالاً وَ اِدْباراً، فَاِذا اَقْبَلَتْ فَاحْمِلُوها عَلَى النَّوافِلِ، وَ اِذا اَدْبَرَتْ فَاقْتَصِرُوا بِها عَلَى الْفَرائِضِ.","persian":"دل‌ها گاه نشاط دارند و گاه روی‌گردان می‌شوند؛ هنگام نشاط، آن‌ها را به کارهای مستحب وادارید و هنگام بی‌میلی، به واجبات بسنده کنید.","audio":null},{"id":"h313","kind":"hikmat","number":313,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: وَ فِى الْقُرْآنِ نَبَاُ ما قَبْلَكُمْ، وَ خَبَرُ ما بَعْدَكُمْ، وَ حُكْمُ ما بَيْنَكُمْ.","persian":"در قرآن، خبر گذشتگان، آگاهی از آیندگان و حکم آنچه در میان شماست وجود دارد.","audio":null},{"id":"h314","kind":"hikmat","number":314,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رُدُّوا الْحَجَرَ مِنْ حَيْثُ جاءَ، فَاِنَّ الشَّرَّ لايَدْفَعُهُ اِلاَّ الشَّرُّ.","persian":"سنگ را از همان سو که آمده بازگردانید؛ زیرا بدی را جز با بدی دفع نمی‌توان کرد.","audio":null},{"id":"h315","kind":"hikmat","number":315,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِكاتِبِهِ عُبَيْدِاللّهِ بْنِ اَبى رافِع: اَلِقْ دَواتَكَ، وَاَطِلْ جِلْفَةَ قَلَمِكَ، وَ فَرِّجْ بَيْنَ السُّطُورِ، وَ قَرْمِطْ بَيْنَ الْحُرُوفِ، فَاِنَّ ذلِكَ اَجْدَرُ بِصَباحَةِ الْخَطِّ.","persian":"امام به نویسنده خود، عبیدالله بن ابی‌رافع، فرمود: «در دواتت لیقه بگذار، نوک قلمت را بلند بتراش، فاصله میان سطرها را بیشتر و فاصله میان حروف را کمتر کن؛ این شیوه به زیبایی خط نزدیک‌تر است.»","audio":null},{"id":"h316","kind":"hikmat","number":316,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَنَا يَعْسُوبُ الْمُؤْمِنينَ، وَالْمالُ يَعْسُوبُ الْفُجّارِ.","persian":"من پیشوای مؤمنانم و مال، پیشوای بدکاران است.","audio":null},{"id":"h317","kind":"hikmat","number":317,"arabic":"وَ قالَ لَهُ بَعْضُ الْيَهُودِ: ما دَفَنْتُمْ نَبِيَّكُمْ حَتَّى اخْتَلَفْتُمْ فيهِ! فَقالَ عَلَيْهِ السَّلامُ لَهُ: اِنَّما اخْتَلَفْنا عَنْهُ لا فيهِ، وَلكِنَّكُمْ ما جَفَّتْ اَرْجُلُكُمْ مِنْ الْبَحْرِ حَتّى قُلْتُمْ لِنَبِيِّكُمْ: «اِجْعَلْ لَنا اِلهاً كَما لَهُمْ آلِهَةٌ، قالَ: اِنَّكُمْ قَوْمٌ تَجْهَلُونَ».","persian":"یکی از یهودیان به امام گفت: «هنوز پیامبرتان را به خاک نسپرده بودید که درباره او اختلاف کردید.» امام فرمود: «ما درباره آنچه از او به ما رسید اختلاف کردیم، نه درباره خود او؛ اما شما هنوز پاهایتان از آب دریا خشک نشده بود که به پیامبرتان گفتید برای ما نیز خدایی مانند خدایان آنان قرار بده؛ و او گفت: شما مردمی نادان هستید.»","audio":null},{"id":"h318","kind":"hikmat","number":318,"arabic":"وَ قيلَ لَهُ: بِاَىِّ شَىْء غَلَبْتَ الاَْقْرانَ؟ فَقالَ عَلَيْهِ السَّلامُ: ما لَقيتُ اَحَداً اِلاّ اَعانَنى عَلى نَفْسِهِ.","persian":"از امام پرسیدند: «چگونه بر هماوردان خود پیروز می‌شدی؟» فرمود: «با هیچ‌کس روبه‌رو نشدم مگر آنکه خود او مرا بر شکست دادنش یاری کرد.»","audio":null},{"id":"h319","kind":"hikmat","number":319,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لاِبْنِهِ مُحَمَّدِ بْنِ الْحَنَفِيَّةِ: يا بُنَىَّ اِنّى اَخافُ عَلَيْكَ الْفَقْرَ، فَاسْتَعِذْ بِاللّهِ مِنْهُ، فَاِنَّ الْفَقْرَ مَنْقَصَةٌ لِلدّينِ، مَدْهَشَةٌ لِلْعَقْلِ، داعِيَةٌ لِلْمَقْتِ.","persian":"امام به فرزندش محمد بن حنفیه فرمود: «پسرم، از تنگدستی برای تو بیمناکم؛ از آن به خدا پناه ببر، زیرا فقر به دین آسیب می‌زند، عقل را سرگردان می‌کند و کینه و دشمنی برمی‌انگیزد.»","audio":null},{"id":"h320","kind":"hikmat","number":320,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِسائِل سَاَلَهُ عَنْ مُعْضِلَة: سَلْ تَفَقُّهاً، وَ لاتَسْأَلْ تَعَنُّتاً، فَاِنَّ الْجاهِلَ الْمُتَعَلِّمَ شَبيهٌ بِالْعالِمِ، وَ اِنَّ الْعالِمَ الْمُتَعَسِّفَ شَبيهٌ بِالْجاهِلِ الْمُتَعَنِّتِ.","persian":"به کسی که مسئله‌ای دشوار پرسید فرمود: «برای فهمیدن بپرس، نه برای به زحمت افکندن دیگران؛ زیرا نادانی که می‌آموزد به دانا شباهت دارد و دانایی که بی‌انصافانه سؤال می‌کند به نادان لجوج شبیه است.»","audio":null},{"id":"h321","kind":"hikmat","number":321,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِعَبْدِ اللّهِ بْنِ الْعَبّاسِ وَ قَدْ اَشارَ عَلَيْهِ فى شَىْء لَمْ يُوافِقْ رَأْيَهُ: لَكَ اَنْ تُشيرَ عَلَىَّ وَ اَرى، فَاِنْ عَصَيْتُكَ فَاَطِعْنى.","persian":"امام به عبدالله بن عباس، که پیشنهادی برخلاف نظر امام داده بود، فرمود: «حق داری نظر خود را به من بگویی و من نیز آن را بررسی کنم؛ اما اگر نظرت را نپذیرفتم، باید از من پیروی کنی.»","audio":null},{"id":"h322","kind":"hikmat","number":322,"arabic":"وَ رُوِىَ اَنّهُ عَلَيْهِ السَّلامُ لَمّا وَرَدَ الْكُوفَةَ قادِماً مِنْ صِفّينَ مَرَّ بِالشَّباميّينَ، فَسَمِعَ بُكاءَ النِّساءِ عَلى قَتْلى صِفّينَ، وَ خَرَجَ اِلَيْهِ حَرْبُ بْنُ شُرَحْبيل الشَّبامِىُّ وَ كانَ مِنْ وُجُوهِ قَوْمِهِ، فَقالَ عَلَيْهِ السَّلامُ لَهُ: اَتَغْلِبُكُمْ نِساؤُكُمْ عَلى ما اَسْمَعُ؟! اَلاتَنْهَوْنَهُنَّ عَنْ هذَا الرَّنينِ؟! وَ اَقْبَلَ حَرْبٌ يَمْشى مَعَهُ وَ هُوَ عَلَيْهِ السَّلامُ راكِبٌ، فَقالَ لَهُ: اِرْجِعْ، فَاِنَّ مَشْىَ مِثْلِكَ مَعَ مِثْلى فِتْنَةٌ لِلْوالى، وَ مَذَلَّةٌ لِلْمُؤْمِنِ.","persian":"نقل شده است که امام هنگام بازگشت از صفین به کوفه، از کنار قبیلهٔ شبام گذشت و صدای گریهٔ زنان را بر کشته‌شدگان صفین شنید. حرب بن شرحبیل شبامی، از بزرگان آن قبیله، نزد او آمد. امام فرمود: «آیا زنانتان چنان بر شما چیره شده‌اند که این ناله‌ها را می‌شنوم؟ چرا آنان را از این شیون بازنمی‌دارید؟» حرب در حالی که امام سواره بود، پیاده همراهش حرکت کرد. امام فرمود: «بازگرد؛ زیرا پیاده رفتن کسی چون تو در کنار کسی چون من، برای فرمانروا مایهٔ فتنه و برای مؤمن مایهٔ خواری است.»","audio":null},{"id":"h323","kind":"hikmat","number":323,"arabic":"وَ قالَ عَلَيْه السَّلامُ وَ قَدْ مَرَّ بِقَتْلَى الْخَوارِج ِ يَوْمَ النَّهْرَوانِ: بُؤْساً لَكُمْ، لَقَدْ ضَرَّكُمْ مَنْ غَرَّكُمْ. فَقيلَ لَهُ: مَنْ غَرَّهُمْ يا اَميرَالْمُؤْمِنينَ؟ فَقالَ: الشَّيْطانُ الْمُضِلُّ، وَ الاَْنْفُسُ الاَْمّارَةُ بِالسُّوءِ غَرَّتْهُمْ بِالاَْمانِىِّ، وَ فَسَحَتْ لَهُمْ بِالْمَعاصى، وَ وَعَدَتْهُمُ الاِْظْهارَ، فَاقْتَحَمَتْ بِهِمُ النّارَ.","persian":"امام در روز نهروان از کنار کشته‌های خوارج گذشت و فرمود: «نگون‌بخت باشید! کسی که فریبتان داد، به شما زیان رساند.» پرسیدند: «ای امیر مؤمنان، چه کسی آنان را فریفت؟» فرمود: «شیطان گمراه‌کننده و نفس‌های فرمان‌دهنده به بدی؛ آنان را با آرزوهای پوچ فریفتند، راه گناه را برایشان گشودند، وعدهٔ پیروزی دادند و سرانجام در آتش افکندند.»","audio":null},{"id":"h324","kind":"hikmat","number":324,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِتَّقُوا مَعاصِىَ اللّهِ فِى الْخَلَواتِ، فَاِنَّ الشّاهِدَ هُوَ الْحاكِمُ.","persian":"در خلوت از نافرمانی خدا بپرهیزید؛ زیرا همان کسی که شاهد اعمال شماست، داور آن‌ها نیز هست.","audio":null},{"id":"h325","kind":"hikmat","number":325,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لَمّا بَلَغَهُ قَتْلُ مُحَمَّدِ بْنِ اَبى بَكْر رَضِىَ اللّهُ عَنْهُ: اِنَّ حُزْنَنا عَلَيْهِ عَلى قَدْرِ سُرُورِهِم بِهِ، اِلاّ اَنَّهُمْ نَقَصُوا بَغيضاً، وَ نَقَصْنا حَبيباً.","persian":"هنگامی که خبر کشته شدن محمد بن ابی‌بکر به امام رسید، فرمود: «اندوه ما برای او به اندازهٔ شادی دشمنانش است؛ جز اینکه آنان دشمنی را از دست دادند و ما دوستی را.»","audio":null},{"id":"h326","kind":"hikmat","number":326,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعُمْرُ الَّذى اَعْذَرَ اللّهُ فيهِ اِلَى ابْنِ آدَمَ سِتُّونَ سَنَةً.","persian":"شصت سال، عمری است که خداوند با گذشت آن، عذر و بهانه را از فرزند آدم می‌گیرد.","audio":null},{"id":"h327","kind":"hikmat","number":327,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما ظَفِرَ مَنْ ظَفِرَ الاِْثْمُ بِهِ، وَالْغالِبُ بِالشَّرِّ مَغْلُوبٌ.","persian":"کسی که گناه بر او چیره شده، پیروز نشده است؛ و کسی که با بدی غلبه می‌کند، در حقیقت شکست‌خورده است.","audio":null},{"id":"h328","kind":"hikmat","number":328,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اللّهَ سُبْحانَهُ فَرَضَ فى اَمْوالِ الاَْغْنِياءِ اَقْواتَ الْفُقَراءِ، فَما جاعَ فَقيرٌ اِلاّ بِما مَنَعَ غَنِىٌّ، وَاللّهُ تَعالى جَدُّهُ سائِلُهُمْ عَنْ ذلِكَ.","persian":"خداوند سبحان خوراک نیازمندان را در اموال ثروتمندان مقرر کرده است؛ هیچ فقیری گرسنه نمی‌ماند مگر به سبب آنچه توانگری از او دریغ می‌کند، و خداوند متعال ثروتمندان را از این بابت بازخواست خواهد کرد.","audio":null},{"id":"h329","kind":"hikmat","number":329,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الاِْسْتِغْناءُ عَنِ الْعُذْرِ اَعَزُّ مِنَ الصِّدْقِ بِهِ.","persian":"بی‌نیاز بودن از عذرخواهی، ارجمندتر از داشتن عذری راستین است.","audio":null},{"id":"h330","kind":"hikmat","number":330,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَقَلُّ ما يَلْزَمُكُمْ لِلّهِ سُبْحانَهُ اَنْ لاتَسْتَعينُوا بِنِعَمِهِ عَلى مَعاصيهِ.","persian":"کمترین حقی که خداوند بر شما دارد آن است که نعمت‌هایش را وسیلهٔ نافرمانی او نسازید.","audio":null},{"id":"h331","kind":"hikmat","number":331,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اللّهَ سُبْحانَهُ جَعَلَ الطّاعَةَ غَنيمَةَ الاَْكْياسِ عِنْدَ تَفْريطِ الْعَجَزَةِ.","persian":"خداوند اطاعت را هنگام کوتاهی ناتوانان، غنیمتی برای هوشمندان قرار داده است.","audio":null},{"id":"h332","kind":"hikmat","number":332,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: السُّلْطانُ وَزَعَةُ اللّهِ فى اَرْضِهِ.","persian":"فرمانروایان، بازدارندگان و نگهبانان نظم در زمین خدا هستند.","audio":null},{"id":"h333","kind":"hikmat","number":333,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى صِفَةِ الْمُؤْمِنِ: الْمُؤْمِنُ بِشْرُهُ فى وَجْهِهِ، و حُزْنُهُ فى قَلْبِهِ. اَوْسَعُ شَىْء صَدْراً، وَ اَذَلُّ شَىْء نَفْساً. يَكْرَهُ الرِّفْعَةَ، وَ يَشْنَأُ السُّمْعَةَ! طَويلٌ غَمُّهُ، بَعيدٌ هَمُّهُ، كَثيرٌ صَمْتُهُ، مَشْغُولٌ وَقْتُهُ، شَكُورٌ صَبُورٌ، مَغْمُورٌ بِفِكْرَتِهِ، ضَنينٌ بِخَلَّتِهِ، سَهْلُ الْخَليقَةِ، لَيِّنُ الْعَريكَةِ، نَفْسُهُ اَصْلَبُ مِنَ الصَّلْدِ، وَ هُوَ اَذَلُّ مِنَ الْعَبْدِ.","persian":"امام در وصف مؤمن فرمود: «شادمانی‌اش بر چهره و اندوهش در دل اوست. سینه‌ای گشاده و نفسی فروتن دارد. بلندی مقام را خوش نمی‌دارد و از شهرت‌طلبی بیزار است. اندوهش دیرپا و همتش بلند است؛ بسیار خاموش می‌ماند و وقتش را به کار می‌گیرد. سپاسگزار و شکیباست، در اندیشه فرو رفته و در بیان نیازهایش خویشتن‌دار است. خوش‌خو، نرم‌رفتار و سازگار است. در استواری از سنگ سخت‌تر و در فروتنی از بنده‌ای فرمان‌بردار فروتن‌تر است.»","audio":null},{"id":"h334","kind":"hikmat","number":334,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَوْ رَاَى الْعَبْدُ الاَْجَلَ وَ مَصيرَهُ لاََبْغَضَ الاَْمَلَ وَ غُرُورَهُ.","persian":"اگر انسان اجل و سرانجام خود را می‌دید، از آرزوهای دور و فریبندگی آن‌ها بیزار می‌شد.","audio":null},{"id":"h335","kind":"hikmat","number":335,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِكُلِّ امْرِئ فى مالِهِ شَريكانِ: الْوارِثُ وَالْحَوادِثُ.","persian":"هرکس در دارایی خود دو شریک دارد: وارث و حوادث.","audio":null},{"id":"h336","kind":"hikmat","number":336,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْمَسْؤُولُ حُرٌّ حَتّى يَعِدَ.","persian":"کسی که از او چیزی خواسته‌اند، تا وعده نداده است آزاد است.","audio":null},{"id":"h337","kind":"hikmat","number":337,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الدّاعى بِلا عَمَل كَالرّامى بِلاوَتَر.","persian":"دعاکننده‌ای که عمل نمی‌کند، مانند تیراندازی است که زهِ کمان ندارد.","audio":null},{"id":"h338","kind":"hikmat","number":338,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعِلْمُ عِلْمانِ: مَطْبُوعٌ وَ مَسْمُوعٌ، وَ لايَنْفَعُ الْمَسْمُوعُ اِذا لَمْ يَكُنِ الْمَطْبُوعُ.","persian":"دانش دو گونه است: دانشی که از درون می‌جوشد و دانشی که از دیگران شنیده می‌شود. اگر دانشِ درونی نباشد، آنچه از دیگران شنیده شده سودی نخواهد داشت.","audio":null},{"id":"h339","kind":"hikmat","number":339,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: صَوابُ الرَّأْىِ بِالدُّوَلِ، يُقْبِلُ بِاِقْبالِها، وَ يَذْهَبُ بِذَهابِها.","persian":"درستی رأی با گردش قدرت همراه است؛ با روی آوردن آن روی می‌آورد و با رفتنش از میان می‌رود.","audio":null},{"id":"h340","kind":"hikmat","number":340,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعَفافُ زينَةُ الْفَقْرِ، وَالشُّكْرُ زينَةُ الْغِنى.","persian":"پاکدامنی زیور تنگدستی و سپاسگزاری زیور توانگری است.","audio":null},{"id":"h341","kind":"hikmat","number":341,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَوْمُ الْعَدْلِ عَلَى الظّالِمِ اَشَدُّ مِنْ يَوْمِ الْجَوْرِ عَلَى الْمَظْلُومِ.","persian":"روز اجرای عدالت برای ستمگر، سخت‌تر از روز ستم برای ستمدیده است.","audio":null},{"id":"h342","kind":"hikmat","number":342,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْغِنَى الاَْكْبَرُ الْيَأْسُ عَمّا فى اَيْدِى النّاسِ.","persian":"بزرگ‌ترین بی‌نیازی، چشم نداشتن به آن چیزی است که در دست مردم است.","audio":null},{"id":"h343","kind":"hikmat","number":343,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الاَْقاويلُ مَحْفُوظَةٌ، وَالسَّرائِرُ مَبْلُوَّةٌ، وَ «كُلُّ نَفْس بِما كَسَبَتْ رَهينَةٌ». وَالنّاسُ مَنْقُوصُونَ مَدْخُولُونَ اِلاّ مَنْ عَصَمَ اللّهُ، سائِلُهُمْ مُتَعَنِّتٌ، وَ مُجيبُهُمْ مُتَكَلِّفٌ. يَكادُ اَفْضَلُهُمْ رَأْياً يَرُدُّهُ عَنْ فَضْلِ رَأْيِهِ الرِّضى وَالسُّخْطُ، وَ يَكادُ اَصْلَبُهُمْ عُوداً تَنْكَؤُهُ اللَّحْظَةُ، وَ تَسْتَحيلُهُ الْكَلِمَةُ الْواحِدَةُ.","persian":"گفته‌ها ثبت می‌شوند، رازهای نهان آزموده می‌شوند و «هرکس در گرو چیزی است که به دست آورده است». مردم جز آن‌که خدا نگاهش دارد، گرفتار کاستی و آفت‌اند؛ پرسشگرشان غالباً لجوج است و پاسخ‌گویشان خود را به زحمت می‌اندازد. چه‌بسا خشنودی یا خشم، خردمندترینشان را از رأی درست بازگرداند و حتی استوارترینشان با نگاهی رنجیده یا با یک سخن دگرگون شود.","audio":null},{"id":"h344","kind":"hikmat","number":344,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَعاشِرَ النّاسِ اتَّقُوا اللّهَ، فَكُمْ مِنْ مُؤَمِّل ما لايَبْلُغُهُ، وَ بان ما لايَسْكُنُهُ، وَ جامِع ما سَوْفَ يَتْرُكُهُ، وَ لَعَلَّهُ مِنْ باطِل جَمَعَهُ، وَ مِنْ حَقٍّ مَنَعَهُ، اَصابَهُ حَراماً، وَاحْتَمَلَ بِهِ آثاماً، فَباءَ بِوِزْرِهِ، وَ قَدِمَ عَلى رَبِّهِ آسِفاً لاهِفاً، قَدْ «خَسِرَ الدُّنْيا وَالاْخِرَةَ ذلِكَ هُوَ الْخُسْرانُ الْمُبينُ».","persian":"ای مردم، از خدا پروا کنید! چه بسیار آرزومندی که به آرزویش نمی‌رسد، خانه‌سازی که در خانه‌اش ساکن نمی‌شود و گردآورندهٔ مالی که به‌زودی آن را برجای می‌گذارد. چه‌بسا مالی که از راه باطل فراهم شده یا حقی که از صاحبش دریغ شده است؛ صاحبش آن را از حرام به دست آورده، بار گناهانش را بر دوش گرفته و با حسرت و اندوه نزد پروردگار حاضر شده است؛ هم دنیا را باخته و هم آخرت را، و این همان زیان آشکار است.","audio":null},{"id":"h345","kind":"hikmat","number":345,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مِنَ الْعِصْمَةِ تَعَذُّرُ الْمَعاصى.","persian":"دست‌نیافتنی بودن گناه، خود می‌تواند از عوامل مصون ماندن از آن باشد.","audio":null},{"id":"h346","kind":"hikmat","number":346,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ماءُ وَجْهِكَ جامِدٌ يُقْطِرُهُ السُّؤالُ، فَانْظُرْ عِنْدَ مَنْ تُقْطِرُهُ.","persian":"آبروی تو مانند آبی است که هنوز در جای خود مانده و درخواست کردن آن را قطره‌قطره می‌ریزد؛ پس بنگر آبرویت را نزد چه کسی می‌ریزی.","audio":null},{"id":"h347","kind":"hikmat","number":347,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الثَّناءُ بِاَكْثَرَ مِنَ الاِْسْتِحْقاقِ مَلَقٌ، وَالتَّقْصيرُ عَنِ الاِْسْتِحْقاقِ عِىٌّ اَوْ حَسَدٌ.","persian":"ستایش بیش از شایستگی، چاپلوسی است و ستایش کمتر از حق، نشانهٔ ناتوانی در بیان یا حسادت.","audio":null},{"id":"h348","kind":"hikmat","number":348,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَشَدُّ الذُّنُوبِ مَا اسْتَهانَ بِهِ صاحِبُهُ.","persian":"سخت‌ترین گناه، گناهی است که صاحبش آن را کوچک بشمارد.","audio":null},{"id":"h349","kind":"hikmat","number":349,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ نَظَرَ فى عَيْبِ نَفْسِهِ اشْتَغَلَ عَنْ عَيْبِ غَيْرِهِ. وَ مَنْ رَضِىَ بِرِزْقِ اللّهِ لَمْ يَحْزَنْ عَلى ما فاتَهُ. وَ مَنْ سَلَّ سَيْفَ الْبَغْىِ قُتِلَ بِهِ. وَ مَنْ كابَدَ الاُْمُورَ عَطِبَ. وَ مَنِ اقْتَحَمَ اللُّجَجَ غَرِقَ. وَ مَنْ دَخَلَ مَداخِلَ السُّوءِ اتُّهِمَ. وَ مَنْ كَثُرَ كَلامُهُ كَثُرَ خَطَأُهُ، وَ مَنْ كَثُرَ خَطَأُهُ قَلَّ حَياؤُهُ، وَ مَنْ قَلَّ حَياؤُهُ قَلَّ وَرَعُهُ، وَ مَنْ قَلَّ وَرَعُهُ ماتَ قَلْبُهُ، وَ مَنْ ماتَ قَلْبُهُ دَخَلَ النّارَ. وَ مَنْ نَظَرَ فى عُيُوبِ النّاسِ فَاَنْكَرَها ثُمَّ رَضِيَها لِنَفْسِهِ فَذاكَ الاَْحْمَقُ بِعَيْنِهِ. وَ الْقَناعَةُ مالٌ لايَنْفَدُ. وَ مَنْ اَكْثَرَ مِنْ ذِكْرِ الْمَوْتِ رَضِىَ مِنَ الدُّنْيا بِالْيَسيرِ. وَ مَنْ عَلِمَ اَنَّ كَلامَهُ مِنْ عَمَلِهِ قَلَّ كَلامُهُ اِلاّ فيما يَعْنيهِ.","persian":"هرکس به عیب خود بپردازد، از پرداختن به عیب دیگران بازمی‌ماند؛ و هرکس به روزیِ خدا خشنود باشد، بر آنچه از دست داده اندوه نمی‌خورد. هرکس شمشیر ستم برکشد، با همان شمشیر کشته می‌شود؛ و هرکس خود را بی‌پروا در سختی‌ها بیفکند، هلاک می‌شود. کسی که به ژرفای گرداب‌ها بزند غرق می‌شود و کسی که به جایگاه‌های بدگمانی وارد شود، متهم می‌گردد. هرکه بسیار سخن بگوید، خطایش بیشتر می‌شود؛ هرکه خطایش بیشتر شود، شرمش کمتر می‌گردد؛ هرکه شرمش کمتر شود، پرهیزگاری‌اش کاهش می‌یابد؛ و هرکه پرهیزگاری‌اش کم شود، دلش می‌میرد و سرانجام وارد آتش می‌شود. آن‌که عیب مردم را ناپسند بداند ولی همان را برای خود روا بشمارد، نادان حقیقی است. قناعت ثروتی پایان‌ناپذیر است. هرکس بسیار به یاد مرگ باشد، از دنیا به اندکی راضی می‌شود؛ و هرکس بداند سخنش از اعمال اوست، جز در آنچه به او مربوط است، کمتر سخن می‌گوید.","audio":null},{"id":"h350","kind":"hikmat","number":350,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِلظّالِمِ مِنَ الرِّجالِ ثَلاثُ عَلامات: يَظْلِمُ مَنْ فَوْقَهُ بِالْمَعْصِيَةِ، وَ مَنْ دُونَهُ بِالْغَلَبَةِ، وَ يُظاهِرُ الْقَوْمَ الظَّلَمَةَ.","persian":"ستمکار سه نشانه دارد: با نافرمانی به بالادست خود ستم می‌کند، با زورگویی به زیردستش و با پشتیبانی از ستمگران به دیگران.","audio":null},{"id":"h351","kind":"hikmat","number":351,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عِنْدَ تَناهِى الشِّدَّةِ تَكُونُ الْفُرْجَةُ، وَ عِنْدَ تَضايُقِ حَلَقِ الْبَلاءِ يَكُونُ الرَّخاءُ.","persian":"هنگامی که سختی به نهایت برسد، گشایش فرا می‌رسد؛ و آن‌گاه که حلقهٔ بلا تنگ‌تر شود، آسایش نزدیک است.","audio":null},{"id":"h352","kind":"hikmat","number":352,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِبَعْضِ اَصْحابِهِ: لاتَجْعَلَنَّ اَكْثَرَ شُغْلِكَ بِاَهْلِكَ وَ وَلَدِكَ، فَاِنْ يَكُنْ اَهْلُكَ وَ وَلَدُكَ اَوْلِياءَاللّهِ فَاِنَّ اللّهَ لايُضيعُ اَوْلِياءَهُ، وَ اِنْ يَكُونُوا اَعْداءَ اللّهِ فَما هَمُّكَ وَ شُغْلُكَ بِاَعْداءِ اللّهِ؟!","persian":"بیشترین وقت خود را صرف خانواده و فرزندانت نکن؛ اگر از دوستان خدایند، خدا دوستانش را تباه نمی‌گذارد، و اگر دشمنان خدایند، چرا باید اندوه و تلاش تو صرف دشمنان او شود؟","audio":null},{"id":"h353","kind":"hikmat","number":353,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَكْبَرُ الْعَيْبِ اَنْ تَعيبَ ما فيكَ مِثْلُهُ.","persian":"بزرگ‌ترین عیب آن است که دیگران را به چیزی سرزنش کنی که خود نیز به آن گرفتار هستی.","audio":null},{"id":"h354","kind":"hikmat","number":354,"arabic":"وَ هَنَّاَ بِحَضْرَتِهِ رَجُلٌ رَجُلاً بِغُلام وُلِدَ لَهُ، فَقالَ لَهُ: لِيَهْنِئْكَ الْفارِسُ. فَقالَ عَلَيْهِ السَّلامُ: لاتَقُلْ ذلِكَ، وَلكِنْ قُلْ: شَكَرْتَ الْواهِبَ، وَ بُورِكَ لَكَ فِى الْمَوْهُوبِ، وَ بَلَغَ اَشُدَّهُ، وَ رُزِقْتَ بِرَّهُ.","persian":"مردی در حضور امام به کسی که صاحب پسر شده بود گفت: «این سوارکار بر تو مبارک باد!» امام فرمود: «چنین مگو؛ بلکه بگو: بخشنده را سپاس گفته باشی، این هدیه بر تو مبارک باشد، به رشد و توانایی برسد و از نیکوکاری‌اش بهره‌مند شوی.»","audio":null},{"id":"h355","kind":"hikmat","number":355,"arabic":"وَ بَنى رَجُلٌ مِنْ عُمّالِهِ بِناءً فَخْماً؛ فَقالَ عَلَيْهِ السَّلامُ: اَطْلَعَتِ الْوَرِقُ رُؤُوسَها، اِنَّ الْبِناءَ يَصِفُ لَكَ الْغِنى.","persian":"یکی از کارگزاران امام ساختمانی باشکوه ساخت. امام فرمود: «سکه‌ها سر برآورده‌اند! این ساختمان از دارایی فراوان تو خبر می‌دهد.»","audio":null},{"id":"h356","kind":"hikmat","number":356,"arabic":"وَ قيلَ لَهُ عَلَيْهِ السَّلامُ: لَوْ سُدَّ عَلى رَجُل بابُ بَيْتِهِ وَ تُرِكَ فيهِ، مِنْ اَيْنَ كانَ يَأْتيهِ رِزْقُهُ؟ فَقالَ عَلَيْهِ السَّلامُ: مِنْ حَيْثُ يَأْتيهِ اَجَلُهُ.","persian":"پرسیدند: «اگر کسی را در خانه‌ای ببندند و در را بر او ببندند، روزی‌اش از کجا به او می‌رسد؟» فرمود: «از همان راهی که اجلش به او می‌رسد.»","audio":null},{"id":"h357","kind":"hikmat","number":357,"arabic":"وَ عَزّى قَوْماً عَنْ مَيِّت ماتَ لَهُمْ، فَقالَ عَلَيْهِ السَّلامُ: اِنَّ هذَا الاَْمْرَ لَيْسَ بِكُمْ بَدَاَ، وَ لا اِلَيْكُمُ انْتَهى. وَ قَدْ كانَ صاحِبُكُمْ هذا يُسافِرُ، فَعُدُّوهُ فى بَعْضِ اَسْفارِهِ، فَاِنْ قَدِمَ عَلَيْكُمْ، وَ اِلاّ قَدِمْتُمْ عَلَيْهِ.","persian":"امام گروهی را که عزیزی از دست داده بودند چنین تسلیت گفت: «این مرگ با شما آغاز نشده و به شما پایان نمی‌پذیرد. عزیزتان پیش‌تر به سفر می‌رفت؛ اکنون نیز او را در یکی از سفرهایش بدانید. اگر بازگشت که شما او را می‌بینید، و اگر نه، شما به سوی او خواهید رفت.»","audio":null},{"id":"h358","kind":"hikmat","number":358,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَيُّهَا النّاسُ، لِيَرَكُمُ اللّهُ مِنَ النِّعْمَةِ وَجِلينَ كَما يَراكُمْ مِنَ النِّقْمَةِ فَرِقينَ، اِنَّهُ مَنْ وُسِّعَ عَلَيْهِ فى ذاتِ يَدِهِ فَلَمْ يَرَ ذلِكَ اسْتِدْراجاً فَقَدْ اَمِنَ مَخُوفاً، وَ مَنْ ضُيِّقَ عَلَيْهِ فى ذاتِ يَدِهِ فَلَمْ يَرَ ذلِكَ اخْتِباراً فَقَدْ ضَيَّعَ مَأْمُولاً.","persian":"ای مردم، همان‌گونه که هنگام بلا از خدا بیم دارید، در هنگام نعمت نیز باید بیمناک باشید. کسی که از گشایش روزی برخوردار شود و احتمال ندهد که این نعمت وسیلهٔ آزمایش و نزدیک شدن تدریجی به کیفر باشد، از خطری که باید از آن بترسد غافل شده است؛ و هرکس تنگی روزی را آزمونی الهی نداند، پاداشی را که می‌توانست به آن امید ببندد از دست داده است.","audio":null},{"id":"h359","kind":"hikmat","number":359,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يا اَسْرَى الرَّغْبَةِ، اَقْصِرُوا، فَاِنَّ الْمُعَرِّجَ عَلَى الدُّنْيا لايَرُوعُهُ مِنْها اِلاّ صَريفُ اَنْيابِ الْحِدْثانِ. اَيُّهَا النّاسُ، تَوَلَّوْا مِنْ اَنْفُسِكُمْ تَأْديبَها، وَ اعْدِلُوا عَنْ ضَراوَةِ عاداتِها.","persian":"ای اسیران خواهش‌ها، از زیاده‌خواهی دست بکشید؛ زیرا دلبستگان دنیا را جز به‌هم‌خوردن دندان‌های حوادث از آن نمی‌ترساند. ای مردم، خود عهده‌دار تربیت خویش شوید و نفس خود را از سرسختی در عادت‌های زیان‌بار بازدارید.","audio":null},{"id":"h360","kind":"hikmat","number":360,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَظُنَّنَّ بِكَلِمَة خَرَجَتْ مِنْ اَحَد سُوءًا وَ اَنْتَ تَجِدُ لَها فِى الْخَيْرِ مُحْتَمَلاً.","persian":"تا زمانی که می‌توانی سخن کسی را بر معنایی نیک حمل کنی، دربارهٔ آن بدگمان مباش.","audio":null},{"id":"h361","kind":"hikmat","number":361,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا كانَتْ لَكَ اِلَى اللّهِ سُبْحانَهُ حاجَةٌ فَابْدَأْ بِمَسْاَلَةِ الصَّلاةِ عَلى رَسُولِهِ صَلّى اللّهُ عَلَيْهِ وَ آلِهِ، ثُمَّ سَلْ حاجَتَكَ، فَاِنَّ اللّهَ اَكْرَمُ مِنْ اَنْ يُسْاَلَ حاجَتَيْنِ فَيَقْضِىَ اِحْداهُما وَ يَمْنَعَ الاُْخْرى.","persian":"هرگاه حاجتی از خدا داری، دعایت را با درخواست درود بر پیامبر (ص) آغاز کن و سپس حاجتت را بخواه؛ زیرا خداوند کریم‌تر از آن است که از دو خواسته، یکی را بپذیرد و دیگری را رد کند.","audio":null},{"id":"h362","kind":"hikmat","number":362,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ ضَنَّ بِعِرْضِهِ فَلْيَدَع ِ الْمِراءَ.","persian":"هرکس آبروی خود را عزیز می‌دارد، باید ستیزه و جدال را رها کند.","audio":null},{"id":"h363","kind":"hikmat","number":363,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مِنَ الْخُرْقِ الْمُعاجَلَةُ قَبْلَ الاِْمْكانِ، وَ الاَْناةُ بَعْدَ الْفُرْصَةِ.","persian":"شتاب کردن پیش از فراهم شدن امکان و درنگ کردن پس از رسیدن فرصت، هر دو از بی‌تدبیری است.","audio":null},{"id":"h364","kind":"hikmat","number":364,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَسْاَلْ عَمّا لايَكُونُ، فَفِى الَّذى قَدْ كانَ لَكَ شُغْلٌ.","persian":"دربارهٔ آنچه هنوز رخ نداده بیهوده پرس‌وجو نکن؛ کارهایی که اکنون پیش روی توست برای مشغول شدنت کافی است.","audio":null},{"id":"h365","kind":"hikmat","number":365,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْفِكْرُ مِرْآةٌ صافِيَةٌ، وَالاِْعْتِبارُ مُنْذِرٌ ناصِحٌ. وَكَفى اَدَباً لِنَفْسِكَ تَجَنُّبُكَ ما كَرِهْتَهُ لِغَيْرِكَ.","persian":"اندیشه آینه‌ای روشن و عبرت، هشداردهنده‌ای خیرخواه است. برای تربیت خویش همین بس که از رفتاری که برای دیگران نمی‌پسندی دوری کنی.","audio":null},{"id":"h366","kind":"hikmat","number":366,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعِلْمُ مَقْرُونٌ بِالْعَمَلِ، فَمَنْ عَلِمَ عَمِلَ. وَالْعِلْمُ يَهْتِفُ بِالْعَمَلِ، فَاِنْ اَجابَهُ، وَ اِلاَّ ارْتَحَلَ عَنْهُ.","persian":"دانش با عمل پیوند دارد؛ هرکس به‌راستی بداند، عمل می‌کند. دانش، عمل را فرامی‌خواند؛ اگر عمل پاسخ دهد می‌ماند و اگر نه، دانش از میان می‌رود.","audio":null},{"id":"h367","kind":"hikmat","number":367,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يااَيُّهَا النّاسُ، مَتاعُ الدُّنْيا حُطامٌ مُوبِئٌ، فَتَجَنَّبُوا مَرْعاهُ، قُلْعَتُها اَحْظى مِنْ طُماْنينَتِها، وَ بُلْغَتُها اَزْكى مِنْ ثَرْوَتِها، حُكِمَ عَلى مُكْثِر مِنْها بِالْفاقَةِ، وَ اُعينَ مَنْ غَنِىَ عَنْها بِالرّاحَةِ. وَ مَنْ راقَهُ زِبْرِجُها اَعْقَبَتْ ناظِرَيْهِ كَمَهاً. وَ مَنِ اسْتَشْعَرَ الشَّغَفَ بِها مَلاََتْ ضَميرَهُ اَشْجاناً، لَهُنَّ رَقْصٌ عَلى سُوَيْداءِ قَلْبِهِ، هَمٌّ يَشْغَلُهُ وَ غَمٌّ يَحْزُنُهُ، كَذلِكَ حَتّى يُؤْخَذَ بِكَظَمِهِ فَيُلْقى بِالْفَضاءِ، مُنْقَطِعاً اَبْهَراهُ، هَيِّناً عَلَى اللّهِ فَناؤُهُ، وَ عَلَى الاِْخْوانِ اِلْقاؤُهُ. وَ اِنَّما يَنْظُرُ الْمُؤْمِنُ اِلَى الدُّنْيا بِعَيْنِ الاِْعْتِبارِ، وَ يَقْتاتُ مِنْها بِبَطْنِ الاِْضْطِرارِ، وَ يَسْمَعُ فيها بِاُذُنِ الْمَقْتِ وَالاِْبْغاضِ. اِنْ قيلَ اَثْرى قيلَ اَكْدى، وَ اِنْ فُرِحَ لَهُ بِالْبَقاءِ حُزِنَ لَهُ بِالْفَناءِ. هذا وَ لَمْ يَأْتِهِمْ يَوْمٌ فيهِ يُبْلِسُونَ!","persian":"ای مردم، کالای دنیا همچون گیاهی خشک و آفت‌زاست؛ از چراگاه آن دوری کنید. دل کندن از دنیا بهتر از دل بستن به آن است و بهره‌ای اندک از آن، پاکیزه‌تر از اندوختن بسیار است. آن‌که به گردآوری ثروت روی آورده، به فقر و ناآرامی محکوم می‌شود و آن‌که از دنیا بی‌نیاز شده، به آسایش رسیده است. کسی که زرق‌وبرق دنیا شگفت‌زده‌اش کند، دلش نابینا می‌شود؛ و هرکس دل به عشق دنیا بسپارد، گرفتار اندوه‌های پی‌درپی خواهد شد، تا آن‌گاه که مرگ گلویش را بفشارد و او را در گوشه‌ای بیندازد؛ در حالی که رشتهٔ زندگی‌اش گسسته است، جان دادن او بر خدا آسان و سپردنش به خاک بر دوستانش ساده می‌شود. مؤمن با چشم عبرت به دنیا می‌نگرد، به اندازهٔ نیاز از آن برمی‌گیرد و سخنان دنیاپرستان را با گوش بیزاری می‌شنود. اگر بگویند فلانی ثروتمند شد، اندکی بعد می‌گویند تهیدست شد؛ اگر به زندگی‌اش شاد شوند، از مرگش اندوهگین می‌شوند؛ و این‌ها در حالی است که روز حساب و جزا هنوز فرا نرسیده است.","audio":null},{"id":"h368","kind":"hikmat","number":368,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اللّهَ سُبْحانَهُ وَضَعَ الثَّوابَ عَلى طاعَتِهِ، وَ الْعِقابَ عَلى مَعْصِيَتِهِ، ذِيادَةً لِعِبادِهِ عَنْ نِقْمَتِهِ، وَ حِياشَةً لَهُمْ اِلى جَنَّتِهِ.","persian":"خداوند سبحان در برابر فرمان‌برداری پاداش و در برابر نافرمانی کیفر قرار داد، تا بندگانش را از عذاب بازدارد و به سوی بهشت سوق دهد.","audio":null},{"id":"h369","kind":"hikmat","number":369,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَأْتى عَلَى النّاسِ زَمانٌ لايَبْقى فيهِمْ مِنَ الْقُرْآنِ اِلاّ رَسْمُهُ، وَ مِنَ الاِْسْلامِ اِلاَّ اسْمُهُ. وَ مَساجِدُهُمْ يَوْمَئِذ عامِرَةٌ مِنَ الْبِناءِ، خَرابٌ مِنَ الْهُدى. سُكّانُها وَ عُمّارُها شَرُّ اَهْلِ الاَْرْضِ، مِنْهُمْ تَخْرُجُ الْفِتْنَةُ وَ اِلَيْهِمْ تَأْوِى الْخَطيئَةُ، يَرُدُّونَ مَنْ شَذَّ عَنْها فيها، وَ يَسُوقُونَ مَنْ تَاَخَّرَ عَنْها اِلَيْها، يَقُولُ اللّهُ سُبْحانَهُ: «فَبى حَلَفْتُ، لاََبْعَثَنَّ عَلى اُولئِكَ فِتْنَةً اَتْرُكُ الْحَليمَ فيها حَيْرانَ» وَ قَدْ فَعَلَ، وَ نَحْنُ نَسْتَقيلُ اللّهَ عَثْرَةَ الْغَفْلَةِ.","persian":"زمانی بر مردم می‌رسد که از قرآن جز نوشته‌اش و از اسلام جز نامش باقی نمی‌ماند. مسجدهایشان از نظر ساختمان آباد، اما از هدایت تهی است. ساکنان و آبادکنندگان آن مسجدها از بدترین مردم زمین خواهند بود؛ فتنه از آنان برمی‌خیزد و گناه به آنان پناه می‌برد. هرکس از فتنه کناره بگیرد، بازش می‌گردانند و هرکس عقب بماند، به سوی آن می‌رانند. خداوند سبحان می‌فرماید: «به خود سوگند خورده‌ام فتنه‌ای میانشان برانگیزم که بردباران در آن سرگردان شوند» و چنین خواهد کرد. ما از خدا می‌خواهیم از لغزش‌های ناشی از غفلت ما درگذرد.","audio":null},{"id":"h370","kind":"hikmat","number":370,"arabic":"وَ رُوِىَ اَنَّهُ عَلَيْهِ السَّلامُ قَلَّمَا اعْتَدَلَ بِهِ الْمِنْبَرُ اِلاّ قالَ اَمامَ الْخُطْبَةِ: اَيُّهَا النّاسُ اتَّقُوا اللّهَ، فَما خُلِقَ امْرُؤٌ عَبَثاً فَيَلْهُوَ، وَلا تُرِكَ سُدًى فَيَلْغُوَ، وَ ما دُنْياهُ الَّتى تَحَسَّنَتْ لَهُ بِخَلَف مِنَ الاْخِرَةِ الَّتى قَبَّحَها سُوءُ النَّظَرِ عِنْدَهُ. وَ مَا الْمَغْرُورُ الَّذى ظَفِرَ مِنَ الدُّنْيا بِاَعْلى هِمَّتِهِ كَالاْخَرِ الَّذى ظَفِرَ مِنَ الاْخِرَةِ بِاَدْنى سُهْمَتِهِ.","persian":"نقل شده است که امام به‌ندرت بر منبر قرار می‌گرفت مگر آنکه پیش از خطبه می‌فرمود: «ای مردم، از خدا پروا کنید. هیچ‌کس بیهوده آفریده نشده است تا عمر را به بازی بگذراند و به خود واگذاشته نشده است تا کار بیهوده کند. دنیایی که خود را در نظر او آراسته است، نباید جایگزین آخرتی شود که در چشم او کم‌رنگ شده است. آن فریب‌خورده‌ای که با تمام کوشش به بهره‌ای از دنیا دست یافته، هم‌پایهٔ کسی نیست که حتی سهمی اندک از آخرت یافته است.»","audio":null},{"id":"h371","kind":"hikmat","number":371,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاشَرَفَ اَعْلى مِنَ الاِْسْلامِ، وَلا عِزَّ اَعَزُّ مِنَ التَّقْوى، وَ لا مَعْقِلَ اَحْصَنُ مِنَ الْوَرَعِ، وَلا شَفيعَ اَنْجَحُ مِنَ التَّوْبَةِ. وَلا كَنْزَ اَغْنى مِنَ الْقَناعَةِ، وَ لا مالَ اَذْهَبُ لِلْفاقَةِ مِنَ الرِّضى بِالْقُوتِ. وَ مَنِ اقْتَصَرَ عَلى بُلْغَةِ الْكَفافِ فَقَدِ انْتَظَمَ الرَّاحَةَ، وَ تَبَوَّاَ خَفْضَ الدَّعَةِ. وَ الرَّغْبَةُ مِفْتاحُ النَّصَبِ، وَ مَطِيَّةُ التَّعَبِ. وَالْحِرْصُ وَالْكِبْرُ وَ الْحَسَدُ دَواع اِلَى التَّقَحُّمِ فِى الذُّنُوبِ، وَالشَّرُّ جامِعٌ لِمَساوِىَ الْعُيُوبِ.","persian":"هیچ شرافتی بالاتر از اسلام، هیچ عزتی ارجمندتر از تقوا، هیچ پناهگاهی استوارتر از پرهیز از حرام، هیچ شفاعتی رهایی‌بخش‌تر از توبه، هیچ گنجی بی‌نیازکننده‌تر از قناعت و هیچ دارایی‌ای برای زدودن فقر بهتر از خشنودی به روزی خدا نیست. هرکس به اندازهٔ کفایت بسنده کند به آسایش می‌رسد. دلبستگی به دنیا کلید رنج و مرکب سختی است. حرص و تکبر و حسد انسان را به گناهان فرومی‌برند و بدی، گردآورندهٔ همهٔ عیب‌هاست.","audio":null},{"id":"h372","kind":"hikmat","number":372,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِجابِرِ بْنِ عَبْدِاللّهِ الاَْنْصارِىِّ: يا جابِرُ، قِوامُ الدّينِ وَالدُّنْيا بِاَرْبَعَة: عالِم مُسْتَعْمِل عِلْمَهُ، وَ جاهِل لايَسْتَنْكِفُ اَنْ يَتَعَلَّمَ، وَ جَواد لايَبْخَلُ بِمَعْرُوفِهِ، وَ فَقير لايَبيعُ آخِرَتَهُ بِدُنْياهُ. فَاِذا ضَيَّعَ الْعالِمُ عِلْمَهُ اسْتَنْكَفَ الْجاهِلُ اَنْ يَتَعَلَّمَ، وَ اِذا بَخِلَ الْغَنِىُّ بِمَعْرُوفِهِ باعَ الْفَقيرُ آخِرَتَهُ بِدُنْياهُ. يا جابِرُ، مَنْ كَثُرَتْ نِعَمُ اللّهِ عَلَيْهِ كَثُرَتْ حَوائِجُ النّاسِ اِلَيْهِ، فَمَنْ قامَ لِلّهِ فيها بِما يَجِبُ عَرَّضَها لِلدَّوامِ وَ الْبَقاءِ، وَ مَنْ لَمْ يَقُمْ فيها بِما يَجِبُ عَرَّضَها لِلزَّوالِ وَالْفَناءِ.","persian":"امام به جابر بن عبدالله انصاری فرمود: «ای جابر، استواری دین و دنیا بر چهار چیز است: دانایی که دانشش را به کار بندد؛ نادانی که از آموختن سرباز نزند؛ بخشنده‌ای که نیکی خود را دریغ نکند؛ و فقیری که آخرتش را به دنیا نفروشد. اگر دانا علمش را تباه سازد، نادان نیز از آموختن بازمی‌ماند؛ و اگر توانگر نیکی نکند، نیازمند آخرتش را به دنیا می‌فروشد. ای جابر، هرکس نعمت خدا بر او بیشتر شود، نیاز مردم به او افزایش می‌یابد. کسی که حق این نعمت‌ها را ادا کند، آن‌ها را پایدار می‌سازد و کسی که حقشان را نپردازد، آن‌ها را در معرض نابودی قرار می‌دهد.»","audio":null},{"id":"h373","kind":"hikmat","number":373,"arabic":"وَ رَوَى ابْنُ جَرير الطَّبَرِىُّ فى تاريخِهِ عَنْ عَبْدِ الرَّحْمنِ بْنِ اَبى لَيْلَى الْفَقيهِ وَ كانَ مِمَّنْ خَرَجَ لِقِتالِ الْحَجّاج ِ مَعَ ابْنِ الاَْشْعَثِ اَنَّهُ قالَ فيما كانَ يَحُضُّ بِهِ النّاسَ عَلَى الْجِهادِ: اِنّى سَمِعْتُ عَلِيّاً رَفَعَ اللّهُ دَرَجَتَهُ فِى الصّالِحينَ، وَ اَثابَهُ ثَوابَ الشُّهَداءِ وَالصِّدّيقينَ يَقُولُ يَوْمَ لَقينا اَهْلَ الشّامِ: اَيُّهَا الْمُؤْمِنُونَ، اِنَّهُ مَنْ رَأى عُدْواناً يُعْمَلُ بِهِ، وَ مُنْكَراً يُدْعى اِلَيْهِ، فَاَنْكَرَهُ بِقَلْبِهِ فَقَدْ سَلِمَ وَ بَرِئَ، وَ مَنْ اَنْكَرَهُ بِلِسانِهِ فَقَدْ اُجِرَ وَ هُوَ اَفْضَلُ مِنْ صاحِبِهِ، وَ مَنْ اَنْكَرَهُ بِالسَّيْفِ لِتَكُونَ كَلِمَةُ اللّهِ هِىَ الْعُلْيا، وَ كَلِمَةُ الظّالِمينَ هِىَ السُّفْلى، فَذلِكَ الَّذى اَصابَ سَبيلَ الْهُدى، وَ قامَ عَلَى الطَّريقِ، وَ نَوَّرَ فى قَلْبِهِ الْيَقينُ.","persian":"ابن جریر طبری از عبدالرحمان بن ابی‌لیلی، فقیهی که برای جنگ با حجاج همراه ابن اشعث برخاست، نقل می‌کند که هنگام تشویق مردم به نبرد گفت: «از علی ـ که خداوند مقامش را میان نیکوکاران بالا برد و پاداش شهیدان و راست‌گویان به او عطا کند ـ در روز رویارویی با شامیان شنیدم که فرمود: ای مؤمنان، هرکس ستمی را که انجام می‌شود یا کار ناپسندی را که مردم به آن دعوت می‌شوند ببیند و در دل انکار کند، از گناه آن برکنار مانده است. هرکس با زبان انکار کند، پاداش می‌گیرد و برتر از گروه نخست است. و هرکس برای سربلندی کلام خدا و فرو افتادن سخن ستمکاران، با شمشیر به مبارزه برخیزد، راه هدایت و رستگاری را یافته، در راه درست ایستاده و نور یقین در دلش تابیده است.»","audio":null},{"id":"h374","kind":"hikmat","number":374,"arabic":"وَقالَ عَلَيْهِ السَّلامُ فى كَلام آخَرَلَهُ يَجْرى هذَا الْمَجْرى: فَمِنْهُمُ الْمُنْكِرُ لِلْمُنْكَرِ بِيَدِهِ وَ لِسانِهِ وَ قَلْبِهِ، فَذلِكَ الْمُسْتَكْمِلُ لِخِصالِ الْخَيْرِ. وَ مِنْهُمُ الْمُنْكِرُ بِلِسانِهِ وَ قَلْبِهِ وَالتّارِكُ بِيَدِهِ، فَذلِكَ مُتَمَسِّكٌ بِخَصْلَتَيْنِ مِنْ خِصالِ الْخَيْرِ، وَ مُضَيِّعٌ خَصْلَةً. وَ مِنْهُمُ الْمُنْكِرُ بِقَلْبِهِ وَالتّارِكُ بِيَدِهِ وَ لِسانِهِ، فَذلِكَ الَّذى ضَيَّعَ اَشْرَفَ الْخَصْلَتَيْنِ مِنَ الثَّلاثِ، وَ تَمَسَّكَ بِواحِدَة. وَ مِنْهُمْ تارِكٌ لاِِنْكارِ الْمُنْكَرِ بِلِسانِهِ وَ قَلْبِهِ وَ يَدِهِ، فَذلِكَ مَيِّتُ الاَْحْياءِ. وَ ما اَعْمالُ الْبِرِّ كُلُّها وَالْجِهادُ فى سَبيلِ اللّهِ عِنْدَ الاَْمْرِ بِالْمَعْرُوفِ وَالنَّهْىِ عَنِ الْمُنْكَرِ اِلاّ كَنَفْثَة فى بَحْر لُجِّىٍّ. وَ اِنَّ الاَْمْرَ بِالْمَعْرُوفِ وَالنَّهْىَ عَنِ الْمُنْكَرِ لايُقَرِّبانِ مِنْ اَجَل، وَ لايَنْقُصانِ مِنْ رِزْق. وَ اَفْضَلُ مِنْ ذلِكَ كُلِّهِ كَلِمَةُ عَدْل عِنْدَ اِمام جائِر.","persian":"در سخنی دیگر با همین مضمون فرمود: «برخی از مردم با دست و زبان و دل در برابر منکر می‌ایستند؛ چنین کسی همهٔ خصلت‌های نیک را کامل کرده است. برخی با زبان و دل مخالفت می‌کنند، اما با دست نه؛ دو خصلت نیک را گرفته‌اند و یکی را وانهاده‌اند. برخی تنها در دل منکر را ناپسند می‌دارند؛ دو خصلت برتر را از دست داده و به یکی بسنده کرده‌اند. و کسی که با دست و زبان و دل به انکار برنخیزد، مرده‌ای در میان زندگان است. همهٔ کارهای نیک و جهاد در راه خدا در برابر امر به معروف و نهی از منکر، چون دمی آب در دریایی ژرف‌اند. امر به معروف و نهی از منکر نه مرگ را نزدیک می‌کنند و نه روزی را می‌کاهند؛ و از همهٔ آن‌ها برتر، گفتن سخن عادلانه در برابر پیشوای ستمگر است.»","audio":null},{"id":"h375","kind":"hikmat","number":375,"arabic":"وَ عَنْ اَبى جُحَيْفَةَ قالَ: سَمِعْتُ اَميرَ الْمُؤْمِنينَ عَلَيْهِ السَّلامُ يَقُولُ: اَوَّلُ ما تُغْلَبُونَ عَلَيْهِ مِنَ الْجِهادِ الْجِهادُ بِاَيْديكُمْ، ثُمَّ بِاَلْسِنَتِكُمْ، ثُمَّ بِقُلُوبِكُمْ. فَمَنْ لَمْ يَعْرِفْ بِقَلْبِهِ مَعْرُوفاً، وَ لَمْ يُنْكِرْ مُنْكَراً قُلِبَ فَجُعِلَ اَعْلاهُ اَسْفَلَهُ، وَ اَسْفَلُهُ اَعْلاهُ.","persian":"ابوجحیفه نقل می‌کند که از امیر مؤمنان شنید: «نخستین بخش جهاد که از شما گرفته می‌شود، جهاد با دست است؛ سپس با زبان و پس از آن با دل. کسی که در دل نیکی را نیک نشمارد و زشتی را انکار نکند، سرشت او واژگون می‌شود، تا بالای وجودش پایین و پایین آن بالا قرار گیرد.»","audio":null},{"id":"h376","kind":"hikmat","number":376,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ الْحَقَّ ثَقيلٌ مَرىءٌ، وَ اِنَّ الْباطِلَ خَفيفٌ وَبىءٌ.","persian":"حق سنگین اما گواراست، و باطل سبک اما زیان‌بار.","audio":null},{"id":"h377","kind":"hikmat","number":377,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَأْمَنَنَّ عَلى خَيْرِ هذِهِ الاُْمَّةِ عَذابَ اللّهِ، لِقَوْلِهِ سُبْحانَهُ: «فَلايَأْمَنُ مَكْرَ اللّهِ اِلاَّ الْقَوْمُ الْخاسِرُونَ». وَ لاتَيْاَسَنَّ لِشَرِّ هذِهِ الاُْمَّةِ مِنْ رَوْح ِ اللّهِ، لِقَوْلِهِ سُبْحانَهُ: «اِنَّهُ لايَيْاَسُ مِنْ رَوْح ِ اللّهِ اِلاَّ الْقَوْمُ الْكافِرُونَ».","persian":"حتی دربارهٔ نیک‌ترین فرد این امت از کیفر خدا آسوده‌خاطر مباش؛ زیرا خداوند فرموده است: «از مکر خدا جز زیانکاران ایمن نیستند.» و دربارهٔ بدترین فرد امت نیز از رحمت خدا ناامید مباش؛ زیرا فرموده است: «از رحمت خدا جز کافران نومید نمی‌شوند.»","audio":null},{"id":"h378","kind":"hikmat","number":378,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْبُخْلُ جامِعٌ لِمَساوِىَ الْعُيُوبِ، وَ هُوَ زِمامٌ يُقادُ بِهِ اِلى كُلِّ سُوء.","persian":"بخل همهٔ عیب‌های ناپسند را در خود گرد می‌آورد و افساری است که انسان را به هر بدی می‌کشاند.","audio":null},{"id":"h379","kind":"hikmat","number":379,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الرِّزْقُ رِزْقانِ: رِزْقٌ تَطْلُبُهُ، وَ رِزْقٌ يَطْلُبُكَ، فَاِنْ لَمْ تَأْتِهِ اَتاكَ، فَلاتَحْمِلْ هَمَّ سَنَتِكَ عَلى هَمِّ يَوْمِكَ، كَفاكَ كُلُّ يَوْم ما فيهِ، فَاِنْ تَكُنِ السَّنَةُ مِنْ عُمُرِكَ فَاِنَّ اللّهَ تَعالى سَيُؤْتيكَ فى كُلِّ غَد جَديد ما قَسَمَ لَكَ، وَ اِنْ لَمْ تَكُنِ السَّنَةُ مِنْ عُمُرِكَ فَما تَصْنَعُ بِالْهَمِّ فيما لَيْسَ لَكَ؟! وَ لَنْ يَسْبِقَكَ اِلى رِزْقِكَ طالِبٌ، وَ لَنْ يَغْلِبَكَ عَلَيْهِ غالِبٌ، وَلَنْ يُبْطِئَ عَنْكَ ما قَدْ قُدِّرَ لَكَ.","persian":"روزی دو گونه است: روزی‌ای که در پی آن می‌روی و روزی‌ای که در پی تو می‌آید؛ اگر تو نزد آن نروی، آن نزد تو می‌آید. پس نگرانی یک سال را بر امروزت بار نکن؛ برای هر روز، روزی همان روز کافی است. اگر آن سال از عمر تو باشد، خداوند در هر روزش سهم تو را می‌رساند؛ و اگر از عمرت نباشد، چرا برای چیزی که از آنِ تو نخواهد بود اندوه بخوری؟ هیچ جوینده‌ای در روزی مقدر تو بر تو پیشی نمی‌گیرد، هیچ نیرومندی آن را از تو نمی‌رباید و آنچه برای تو تعیین شده، از رسیدن به تو بازنمی‌ماند.","audio":null},{"id":"h380","kind":"hikmat","number":380,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رُبَّ مُسْتَقْبِل يَوْماً لَيْسَ بِمُسْتَدْبِرِهِ، وَ مَغْبُوط فى اَوَّلِ لَيْلِهِ قامَتْ بَواكيهِ فى آخِرِهِ.","persian":"چه بسیار کسی که به پیشواز روزی می‌رود، اما به پایان آن نمی‌رسد؛ و چه بسیار کسی که در آغاز شب به او غبطه می‌خورند، اما تا پایان همان شب عزاداران بر او می‌گریند.","audio":null},{"id":"h381","kind":"hikmat","number":381,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْكَلامُ فى وَثاقِكَ مالَمْ تَتَكَلَّمْ بِهِ، فَاِذا تَكَلَّمْتَ بِهِ صِرْتَ فى وَثاقِهِ، فَاخْزُنْ لِسانَكَ كَما تَخْزُنُ ذَهَبَكَ وَ وَرِقَكَ، فَرُبَّ كَلِمَة سَلَبَتْ نِعْمَةً، وَجَلَبَتْ نِقْمَةً.","persian":"تا وقتی سخنت را نگفته‌ای، آن سخن در اختیار توست؛ اما همین که آن را گفتی، تو در بندش قرار می‌گیری. زبانت را همان‌گونه حفظ کن که طلا و نقره‌ات را حفظ می‌کنی؛ چه‌بسا سخنی که نعمتی را از میان ببرد و کیفری به بار آورد.","audio":null},{"id":"h382","kind":"hikmat","number":382,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَقُلْ مالاتَعْلَمُ، بَلْ لاتَقُلْ كُلَّ ما تَعْلَمُ، فَاِنَّ اللّهَ سُبْحانَهُ قَدْ فَرَضَ عَلى جَوارِحِكَ كُلِّها فَرائِضَ يَحْتَجُّ بِها عَلَيْكَ يَوْمَ الْقِيامَةِ.","persian":"آنچه را نمی‌دانی مگو؛ حتی هر آنچه را می‌دانی نیز بر زبان نیاور. خداوند بر اعضای بدنت حقوق و تکالیفی قرار داده است که روز قیامت با آن‌ها بر تو حجت خواهد آورد.","audio":null},{"id":"h383","kind":"hikmat","number":383,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِحْذَرْ اَنْ يَراكَ اللّهُ عِنْدَ مَعْصيَتِهِ، وَ يَفْقِدَكَ عِنْدَ طاعَتِهِ، فَتَكُونَ مِنَ الْخاسِرينَ. وَ اِذا قَويتَ فَاقْوَ عَلى طاعَةِ اللّهِ، وَ اِذا ضَعُفْتَ فَاضْعُفْ عَنْ مَعْصِيَةِ اللّهِ.","persian":"بپرهیز از اینکه خدا تو را هنگام نافرمانی حاضر و هنگام فرمان‌برداری غایب ببیند؛ در این صورت از زیانکارانی. هرگاه توانایی داری، آن را در اطاعت خدا به کار گیر و هرگاه ناتوان شدی، از گناه کردن ناتوان باش.","audio":null},{"id":"h384","kind":"hikmat","number":384,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الرُّكُونُ اِلَى الدُّنْيا مَعَ ما تُعايِنُ مِنْها جَهْلٌ. وَالتَّقْصيرُ فى حُسْنِ الْعَمَلِ اِذا وَثِقْتَ بِالثَّوابِ عَلَيْهِ غَبْنٌ. وَ الطُّمَأْنينَةُ اِلى كُلِّ اَحَد قَبْلَ الاِْخْتِبارِ لَهُ عَجْزٌ.","persian":"دلبستگی به دنیا با وجود دگرگونی‌های آشکار آن، نادانی است. کوتاهی در کار نیک، با اطمینان به پاداش آن، زیان‌دیدگی است؛ و اعتماد کردن به هرکس پیش از آزمودنش، ناتوانی در تدبیر است.","audio":null},{"id":"h385","kind":"hikmat","number":385,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مِنْ هَوانِ الدُّنْيا عَلَى اللّهِ اَنَّهُ لايُعْصى اِلاّ فيها، وَ لايُنالُ ما عِنْدَهُ اِلاّ بِتَرْكِها.","persian":"برای بی‌ارزشی دنیا نزد خدا همین بس که جز در دنیا نافرمانی نمی‌شود، و راه دست یافتن به آنچه نزد خداست، جز با دل کندن از دنیا گشوده نمی‌شود.","audio":null},{"id":"h386","kind":"hikmat","number":386,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ طَلَبَ شَيْئاً نالَهُ اَوْ بَعْضَهُ.","persian":"هرکس چیزی را با جدیت بخواهد، به همهٔ آن یا بخشی از آن دست می‌یابد.","audio":null},{"id":"h387","kind":"hikmat","number":387,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما خَيْرٌ بِخَيْر بَعْدَهُ النّارُ، وَ ما شَرٌّ بِشَرٍّ بَعْدَهُ الْجَنَّةُ. وَ كُلُّ نَعيم دُونَ الْجَنَّةِ مَحْقُورٌ، وَ كُلُّ بَلاء دُونَ النّارِ عافِيَةٌ.","persian":"خوبی‌ای که پایانش آتش است، خوبی نیست؛ و سختی‌ای که سرانجامش بهشت است، سختی به شمار نمی‌آید. هر نعمتی در مقایسه با بهشت ناچیز و هر بلایی در برابر دوزخ، آسایش است.","audio":null},{"id":"h388","kind":"hikmat","number":388,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَلا وَ اِنَّ مِنَ الْبَلاءِ الْفاقَةَ، وَ اَشَدُّ مِنَ الْفاقَةِ مَرَضُ الْبَدَنِ، وَ اَشَدُّ مِنْ مَرَضِ الْبَدَنِ مَرَضُ الْقَلْبِ. اَلا وَ اِنَّ مِنَ النِّعَمِ سَعَةَ الْمالِ، وَ اَفْضَلُ مِنْ سَعَةِ الْمالِ صِحَّةُ الْبَدَنِ، وَاَفْضَلُ مِنْ صِحَّةِ الْبَدَنِ تَقْوَى الْقَلْبِ.","persian":"آگاه باشید که تنگدستی از بلاهاست؛ بیماری بدن از آن سخت‌تر و بیماری دل از بیماری تن سخت‌تر است. بدانید که دارایی از نعمت‌هاست؛ تندرستی از آن بهتر و پرهیزگاری دل از تندرستی برتر است.","audio":null},{"id":"h389","kind":"hikmat","number":389,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَبْطَاَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ.","persian":"کسی را که عملش عقب انداخته باشد، نسبش پیش نمی‌برد.","audio":null},{"id":"h390","kind":"hikmat","number":390,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لِلْمُؤْمِنِ ثَلاثُ ساعات: فَساعَةٌ يُناجى فيها رَبَّهُ، وَ ساعَةٌ يَرُمُّ مَعاشَهُ، وَ ساعَةٌ يُخَلّى بَيْنَ نَفْسِهِ وَ بَيْنَ لَذَّتِها فيما يَحِلُّ وَ يَجْمُلُ. وَ لَيْسَ لِلْعاقِلِ اَنْ يَكُونَ شاخِصاً اِلاّ فى ثَلاث: مَرَمَّة لِمَعاش، اَوْ خُطْوَة فى مَعاد، اَوْ لَذَّة فى غَيْرِ مُحَرَّم.","persian":"مؤمن سه بخش از وقت خود را قرار می‌دهد: زمانی برای رازونیاز با پروردگار، زمانی برای سامان دادن معاش و زمانی برای بهره‌مندی از لذت‌های حلال و پسندیده. خردمند نیز جز برای سه هدف سفر نمی‌کند: بهبود زندگی، برداشتن گامی برای آخرت یا بهره بردن از لذتی که حرام نیست.","audio":null},{"id":"h391","kind":"hikmat","number":391,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِزْهَدْ فِى الدُّنْيا يُبَصِّرْكَ اللّهُ عَوْراتِها، وَلاتَغْفُلْ فَلَسْتَ بِمَغْفُول عَنْكَ.","persian":"از دنیا دل بکن تا خداوند تو را به عیب‌های آن بینا کند؛ و غافل مباش، زیرا از تو غافل نیستند.","audio":null},{"id":"h392","kind":"hikmat","number":392,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: تَكَلَّمُوا تُعْرَفُوا، فَاِنَّ الْمَرْءَ مَخْبُوءٌ تَحْتَ لِسانِهِ.","persian":"سخن بگویید تا شناخته شوید؛ زیرا شخصیت انسان زیر زبانش پنهان است.","audio":null},{"id":"h393","kind":"hikmat","number":393,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: خُذْ مِنَ الدُّنْيا ما اَتاكَ، وَ تَوَلَّ عَمّا تَوَلّى عَنْكَ، فَاِنْ اَنْتَ لَمْ تَفْعَلْ فَاَجْمِلْ فِى الطَّلَبِ.","persian":"آنچه از دنیا به سراغت آمد بپذیر و از آنچه از تو روی گرداند، روی بگردان؛ و اگر چنین نمی‌کنی، دست‌کم در جست‌وجوی آن میانه‌رو باش.","audio":null},{"id":"h394","kind":"hikmat","number":394,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رُبَّ قَوْل اَنْفَذُ مِنْ صَوْل.","persian":"چه‌بسا سخنی که اثرش از یورش و حمله نافذتر باشد.","audio":null},{"id":"h395","kind":"hikmat","number":395,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كُلُّ مُقْتَصَر عَلَيْهِ كاف.","persian":"هر مقدار که نیاز را برآورد، کافی است.","audio":null},{"id":"h396","kind":"hikmat","number":396,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْمَنِيَّةُ وَلاَ الدَّنِيَّةُ، وَالتَّقَلُّلُ وَلاَ التَّوَسُّلُ. وَ مَنْ لَمْ يُعْطَ قاعِداً لَمْ يُعْطَ قائِماً. وَالدَّهْرُ يَوْمانِ: يَوْمٌ لَكَ، وَ يَوْمٌ عَلَيْكَ. فَاِذا كانَ لَكَ فَلاتَبْطَرْ، وَ اِذا كانَ عَلَيْكَ فَاصْبِرْ.","persian":"مرگ را بپذیر، نه خواری را؛ و به اندک بسنده کن، نه اینکه دست نیاز پیش دیگران دراز کنی. کسی که در حالت نشسته چیزی به او داده نمی‌شود، در حالت ایستاده نیز به او داده نخواهد شد. روزگار دو روز است: روزی به سود تو و روزی به زیان تو. چون به سود تو بود، سرمستی و گردنکشی مکن، و چون به زیان تو بود، شکیبا باش.","audio":null},{"id":"h397","kind":"hikmat","number":397,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: نِعْمَ الطّيبُ الْمِسْكُ، خَفيفٌ مَحْمِلُهُ، عَطِرٌ ريحُهُ.","persian":"مشک چه عطر نیکویی است! حمل آن سبک و بویش خوش است.","audio":null},{"id":"h398","kind":"hikmat","number":398,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ضَعْ فَخْرَكَ، وَاحْطُطْ كِبْرَكَ، وَ اذْكُرْ قَبْرَكَ.","persian":"فخرفروشی را کنار بگذار، تکبر را فرو بنشان و قبر خود را به یاد آور.","audio":null},{"id":"h399","kind":"hikmat","number":399,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِلْوَلَدِ عَلَى الْوالِدِ حَقّاً، وَ اِنَّ لِلْوالِدِ عَلَى الْوَلَدِ حَقّاً. فَحَقُّ الْوالِدِ عَلَى الْوَلَدِ اَنْ يُطيعَهُ فى كُلِّ شَىْء اِلاّ فى مَعْصِيَةِ اللّهِ سُبْحانَهُ، وَ حَقُّ الْوَلَدِ عَلَى الْوالِدِ اَنْ يُحَسِّنَ اسْمَهُ، وَ يُحَسِّنَ اَدَبَهُ، وَ يُعَلِّمَهُ الْقُرْآنَ.","persian":"فرزند بر پدر حقی دارد و پدر نیز بر فرزند حقی. حق پدر بر فرزند آن است که در همه‌چیز، جز نافرمانی خدا، از او اطاعت کند. حق فرزند بر پدر آن است که نامی نیکو برایش برگزیند، خوب تربیتش کند و قرآن به او بیاموزد.","audio":null},{"id":"h400","kind":"hikmat","number":400,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعَيْنُ حَقٌّ، وَالرُّقى حَقٌّ، وَالسِّحْرُ حَقٌّ، وَالْفَأْلُ حَقٌّ، وَالطِّيَرَةُ لَيْسَتْ بِحَقٍّ، وَالْعَدْوى لَيْسَتْ بِحَقٍّ. وَالطّيبُ نُشْرَةٌ، وَالْعَسَلُ نُشْرَةٌ، وَالرُّكُوبُ نُشْرَةٌ، وَالنَّظَرُ اِلَى الْخُضْرَةِ نُشْرَةٌ.","persian":"در این سخن، چشم‌زخم، دعاها و افسون‌های درمانی، سحر و فال نیک اموری واقعی شمرده شده‌اند؛ اما فال بد و «عدوى» نفی شده‌اند. بوی خوش، عسل، سواری و نگاه کردن به سبزه نیز از مایه‌های نشاط و رفع اندوه دانسته شده‌اند.","audio":null},{"id":"h401","kind":"hikmat","number":401,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مُقارَبَةُ النّاسِ فى اَخْلاقِهِمْ اَمْنٌ مِنْ غَوائِلِهِمْ.","persian":"نزدیک شدن به مردم و سازگاری با اخلاقشان، انسان را از آسیب‌ها و دشمنی‌های آنان ایمن می‌سازد.","audio":null},{"id":"h402","kind":"hikmat","number":402,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِبَعْضِ مُخاطِبيهِ وَ قَدْ تَكَلَّمَ بِكَلِمَة يُسْتَصْغَرُ مِثْلُهُ عَنْ قَوْلِ مِثْلِها: لَقَدْ طِرْتَ شَكيراً، وَ هَدَرْتَ سَقْباً.","persian":"امام به کسی که در حضورش سخنی بالاتر از اندازهٔ خود گفت، فرمود: «پیش از آنکه پر درآوری، پرواز کردی و هنوز کم‌سالی، بانگ برداشتی.»","audio":null},{"id":"h403","kind":"hikmat","number":403,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَوْمَاَ اِلى مُتَفاوِت خَذَلَتْهُ الْحِيَلُ.","persian":"کسی که به هدفی ناسازگار یا دور از دسترس رو کند، چاره‌ها او را تنها می‌گذارند.","audio":null},{"id":"h404","kind":"hikmat","number":404,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ، وَ قَدْ سُئِلَ عَنْ مَعْنى قَوْلِهِمْ: «لاحَوْلَ وَلاقُوَّةَ اِلاّ بِاللّهِ»: اِنّا لانَمْلِكُ مَعَ اللّهِ شَيْئاً، وَلانَمْلِكُ اِلاّ ما مَلَّكَنا، فَمَتى مَلَّكَنا ما هُوَ اَمْلَكُ بِهِ مِنّا كَلَّفَنا، وَ مَتى اَخَذَهُ مِنّا وَضَعَ تَكْليفَهُ عَنّا.","persian":"از امام دربارهٔ معنای «لا حول و لا قوّة إلّا بالله» پرسیدند. فرمود: «ما در کنار خدا صاحب چیزی نیستیم و جز آنچه او در اختیارمان قرار دهد، مالک چیزی نمی‌شویم. پس هرگاه چیزی را به ما سپارد ـ درحالی‌که خود از ما به آن سزاوارتر است ـ تکلیفی بر عهده‌مان می‌گذارد و چون آن را بازستاند، تکلیفش را نیز از ما برمی‌دارد.»","audio":null},{"id":"h405","kind":"hikmat","number":405,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِعَمّارِ بْنِ ياسِر رَحِمَهُ اللّهُ، وَ قَدْ سَمِعَهُ يُراجِعُ الْمُغيرَةَ ابْنَ شُعْبَةَ كَلاماً: دَعْهُ يا عَمّارُ، فَاِنَّهُ لَمْ يَأْخُذْ مِنَ الدّينِ اِلاّ ما قارَبَهُ مِنَ الدُّنْيا، وَ عَلى عَمْد لَبَّسَ عَلى نَفْسِهِ لِيَجْعَلَ الشُّبُهاتِ عاذِراً لِسَقَطاتِهِ.","persian":"امام سخن عمار یاسر را با مغیرة بن شعبه شنید و به عمار فرمود: «او را واگذار؛ زیرا از دین جز آنچه او را به دنیا نزدیک می‌کرد برنگرفته است. خود را عمداً در شبهه‌ها فرو برده تا آن‌ها را بهانه‌ای برای توجیه لغزش‌هایش قرار دهد.»","audio":null},{"id":"h406","kind":"hikmat","number":406,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما اَحَسَنَ تَواضُعَ الاَْغْنِياءِ لِلْفُقَراءِ طَلَباً لِما عِنْدَاللّهِ! وَ اَحْسَنُ مِنْهُ تيهُ الْفُقَراءِ عَلَى الاَْغْنِياءِ اتِّكالاً عَلَى اللّهِ.","persian":"چه نیکوست فروتنی ثروتمندان در برابر نیازمندان، به امید رحمت خدا؛ و نیکوتر از آن، بزرگ‌منشی نیازمندان در برابر ثروتمندان، از سر اعتماد به خداست.","audio":null},{"id":"h407","kind":"hikmat","number":407,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَا اسْتَوْدَعَ اللّهُ امْرَءاً عَقْلاً اِلاّ اسْتَنْقَذَهُ بِهِ يَوْماًما.","persian":"خداوند عقل را در کسی به ودیعه نمی‌گذارد مگر آنکه روزی به یاری همان عقل او را نجات دهد.","audio":null},{"id":"h408","kind":"hikmat","number":408,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ صارَعَ الْحَقَّ صَرَعَهُ.","persian":"هرکس با حق درافتد، حق او را بر زمین می‌زند.","audio":null},{"id":"h409","kind":"hikmat","number":409,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْقَلْبُ مُصْحَفُ الْبَصَرِ.","persian":"دل، دفترِ دریافت‌های چشم است.","audio":null},{"id":"h410","kind":"hikmat","number":410,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: التُّقى رَئيسُ الاَْخْلاقِ.","persian":"پرهیزگاری سرآمد خصلت‌های اخلاقی است.","audio":null},{"id":"h411","kind":"hikmat","number":411,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاتَجْعَلَنَّ ذَرَبَ لِسانِكَ عَلى مَنْ اَنْطَقَكَ، وَ بَلاغَةَ قَوْلِكَ عَلى مَنْ سَدَّدَكَ.","persian":"تیزی زبانت را بر کسی که سخن گفتن به تو آموخت به کار مگیر و قدرت بیانت را علیه کسی که سخنت را درست کرد به کار نبر.","audio":null},{"id":"h412","kind":"hikmat","number":412,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَفاكَ اَدَباً لِنَفْسِكَ اجْتِنابُ ما تَكْرَهُهُ مِنْ غَيْرِكَ.","persian":"برای تربیت خویش همین بس که از آنچه در دیگران ناخوش می‌داری دوری کنی.","audio":null},{"id":"h413","kind":"hikmat","number":413,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ صَبَرَ صَبْرَ الاَْحْرارِ، وَ اِلاّ سَلا سُلُوَّ الاَْغْمارِ.","persian":"آدمی یا باید چون آزادگان صبر کند یا همچون افراد ناآگاه، با گذشت زمان آرام گیرد.","audio":null},{"id":"h414","kind":"hikmat","number":414,"arabic":"وَ فى خَبَر آخَرَ اَنَّهُ عَلَيْهِ السَّلامُ قالَ لِلاَْشْعَثِ بْنِ قَيْس مُعَزِّياً عَنِ ابْن لَهُ: اِنْ صَبَرْتَ صَبْرَ الاَْكارِمِ، وَ اِلاّ سَلَوْتَ سُلُوَّ الْبَهائِمِ.","persian":"در نقل دیگری آمده است که امام هنگام تسلیت به اشعث بن قیس فرمود: «اگر شکیبایی کنی، همچون بزرگواران صبر کرده‌ای و اگر نه، مانند چهارپایان با فراموشی آرام می‌گیری.»","audio":null},{"id":"h415","kind":"hikmat","number":415,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى صِفَةِ الدُّنْيا: الدُّنْيا تَغُرُّ وَ تَضُّرُّ وَ تَمُرُّ. اِنَّ اللّهَ تَعالى لَمْ يَرْضَها ثَواباً لاَِوْلِيائِهِ، وَلا عِقاباً لاَِعْدائِهِ. وَ اِنَّ اَهْلَ الدُّنْيا كَرَكْب بَيْنا هُمْ حَلُّوا اِذْ صاحَ بِهِمْ سائِقُهُمْ فَارْتَحَلُوا.","persian":"دنیا فریب می‌دهد، زیان می‌رساند و می‌گذرد. خداوند دنیا را نه پاداشی برای دوستان خویش قرار داده و نه کیفری برای دشمنانش. دنیاپرستان چون کاروانی هستند که هنوز فرود نیامده‌اند که کاروان‌سالار آنان بانگ کوچ سر می‌دهد.","audio":null},{"id":"h416","kind":"hikmat","number":416,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لاِبْنِهِ الْحَسَنِ عَلَيْهِ السَّلامُ: يا بُنَىَّ، لاتُخَلِّفَنَّ وَراءَكَ شَيْئاً مِنَ الدُّنْيا، فَاِنَّكَ تُخَلِّفُهُ لاَِحَدِ رَجُلَيْنِ: اِمّا رَجُلٌ عَمِلَ فيهِ بِطاعَةِ اللّهِ فَسَعِدَ بِما شَقيتَ بِهِ. وَ اِمّا رَجُلٌ عَمِلَ فيهِ بِمَعْصِيَةِ اللّهِ، فَشَقِىَ بِما جَمَعْتَ لَهُ، فَكُنْتَ عَوْناً لَهُ عَلى مَعْصِيَتِهِ. وَ لَيْسَ اَحَدُ هذَيْنِ حَقيقاً اَنْ تُؤْثِرَهُ عَلى نَفْسِكَ.","persian":"امام به فرزندش حسن (ع) فرمود: «پسرم، چیزی از دنیا برای پس از خود بر جای مگذار؛ زیرا آن را برای یکی از دو نفر باقی می‌گذاری: یا کسی که در راه اطاعت خدا خرجش می‌کند و با مالی که تو برایش رنج کشیده‌ای به سعادت می‌رسد؛ یا کسی که آن را در نافرمانی خدا مصرف می‌کند، پس با آنچه تو برایش گرد آورده‌ای بدبخت می‌شود و تو او را بر گناه یاری کرده‌ای. هیچ‌یک سزاوار نیست که او را بر خود ترجیح دهی.»","audio":null},{"id":"h417","kind":"hikmat","number":417,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِقائِل قالَ بِحَضْرَتِهِ: «اَسْتَغْفِرُ اللّهَ»: ثَكِلَتْكَ اُمُّكَ! اَتَدْرى مَا الاِْسْتِغْفارُ؟ اِنَّ الاْستِغْفارَ دَرَجَةُ الْعِلّيّينَ، وَ هُوَ اسْمٌ واقِعٌ عَلى سِتَّةِ مَعان: اَوَّلُهَا النَّدَمُ عَلى ما مَضى. وَالثَّانِى الْعَزْمُ عَلى تَرْك الْعَوْدِ اِلَيْهِ اَبَداً. وَالثّالِثُ اَنْ تُوَدِّىَ اِلَى الْمَخْلُوقينَ حُقُوقَهُمْ حَتّى تَلْقَى اللّهَ اَمْلَسَ لَيْسَ عَلَيْكَ تَبِعَةٌ. وَالرّابِعُ اَنْ تَعْمِدَ اِلى كُلِّ فَريضَة عَلَيْكَ ضَيَّعْتَها فَتُؤَدِّىَ حَقَّها. وَالْخامِسُ اَنْ تَعْمِدَ اِلَى اللَّحْمِ الَّذى نَبَتَ عَلَى السُّحْتِ فَتُذيبَهُ بِالاَْحْزانِ حَتّى تُلْصِقَ الْجِلْدَ بِالْعَظْمِ وَ يَنْشَاَ بَيْنَهُما لَحْمٌ جَديدٌ. وَالسّادِسُ اَنْ تُذيقَ الْجِسْمَ اَلَمَ الطّاعَةِ كَما اَذَقْتَهُ حَلاوَةَ الْمَعْصِيَةِ. فَعِنْدَ ذلِكَ تَقُولُ: اَسْتَغْفِرُ اللّهَ.","persian":"مردی در حضور امام گفت: «از خدا آمرزش می‌خواهم.» امام فرمود: «مادرت به سوگت بنشیند! آیا می‌دانی آمرزش‌خواهی چیست؟ استغفار جایگاه بلندمرتبگان است و شش معنا دارد: نخست، پشیمانی از گذشته؛ دوم، تصمیم بر بازنگشتن به گناه؛ سوم، بازگرداندن حقوق مردم تا هنگامی که خدا را دیدار می‌کنی، حقی بر گردنت نباشد؛ چهارم، به‌جا آوردن هر واجبی که تباهش کرده‌ای؛ پنجم، آن‌قدر با اندوهِ گناه گذشته بر تن خود سخت بگیری که گوشت روییده از حرام آب شود و گوشت تازه جای آن را بگیرد؛ و ششم، رنج عبادت را به تن بچشانی، چنان‌که شیرینی نافرمانی را به آن چشانده‌ای. پس از آن بگو: «از خدا آمرزش می‌خواهم.»»","audio":null},{"id":"h418","kind":"hikmat","number":418,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْحِلْمُ عَشيرَةٌ.","persian":"بردباری، برای انسان همچون تبار و خویشاوندی است.","audio":null},{"id":"h419","kind":"hikmat","number":419,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مِسْكينٌ ابْنُ آدَمَ، مَكْتُومُ الاَْجَلِ، مَكْنُونُ الْعِلَلِ، مَحْفُوظُ الْعَمَلِ، تُؤْلِمُهُ الْبَقَّةُ، وَ تَقْتُلُهُ الشَّرْقَةُ، وَ تُنْتِنُهُ الْعَرْقَةُ.","persian":"بیچاره فرزند آدم! زمان مرگش پنهان، بیماری‌هایش نهفته و اعمالش ثبت‌شده است. پشه‌ای آزارش می‌دهد، جرعه‌ای گلوگیر او را می‌کشد و عرق تنش بوی ناخوش می‌گیرد.","audio":null},{"id":"h420","kind":"hikmat","number":420,"arabic":"وَ رُوِىَ اَنَّهُ عَلَيْهِ السَّلامُ كانَ جالِساً فى اَصْحابِهِ فَمَرَّتْ بِهِمُ امْرَاَةٌ جَميلَةٌ، فَرَمَقَهَا الْقَوْمُ بِاَبْصارِهِمْ. فَقالَ عَلَيْهِ السَّلامُ: اِنَّ اَبْصارَ هذِهِ الْفُحُولِ طَوامِحُ، وَ اِنَّ ذلِكَ سَبَبُ هِبابِها، فَاِذا نَظَرَ اَحَدُكُمْ اِلَى امْرَاَة تُعْجِبُهُ فَلْيُلامِسْ اَهْلَهُ، فَاِنَّما هِىَ امْرَاَةُ كَامْرَاَة فَقالَ رَجُلٌ مِنَ الْخَوارِج ِ: قاتَلَهُ اللّهُ كافِراً ما اَفْقَهَهُ! فَوَثَبَ الْقَوْمُ لِيَقْتُلُوهُ، فَقالَ عَلَيْهِ السَّلامُ: رُوَيْداً، اِنَّما هُوَ سَبٌّ بِسَبٍّ، اَوْ عَفْوٌ عَنْ ذَنْب.","persian":"نقل شده است که امام در میان یاران نشسته بود که زنی زیبا از کنارشان گذشت و نگاه‌ها به او خیره شد. امام فرمود: «چشم‌های این مردان به شهوت نگریست و همین نگاه مایهٔ تحریک است. هرگاه کسی از شما زنی را دید و از او خوشش آمد، نزد همسر خویش رود؛ زیرا آن زن نیز همانند همسر اوست.» مردی از خوارج گفت: «خدا این کافر را بکشد، چه داناست!» حاضران خواستند او را بکشند، اما امام فرمود: «رهایش کنید؛ پاسخ دشنام، دشنامی همانند آن است یا گذشت از گناه.»","audio":null},{"id":"h421","kind":"hikmat","number":421,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: كَفاكَ مِنْ عَقْلِكَ ما اَوْضَحَ لَكَ سُبُلَ غَيِّكَ مِنْ رُشْدِكَ.","persian":"از عقل تو همین اندازه بس است که راه‌های گمراهی را از راه‌های رستگاری برایت آشکار کند.","audio":null},{"id":"h422","kind":"hikmat","number":422,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِفْعَلُوا الْخَيْرَ وَلاتَحْقِرُوا مِنْهُ شَيْئاً، فَاِنَّ صَغيرَهُ كَبيرٌ، وَ قَليلَهُ كَثيرٌ، وَلايَقُولَنَّ اَحَدُكُمْ: اِنَّ اَحَداً اَوْلى بِفِعْلِ الْخَيْرِ مِنّى؛ فَيَكُونَ وَاللّهِ كَذلِكَ. اِنَّ لِلْخَيْرِ وَالشَّرِّ اَهْلاً، فَمَهْما تَرَكْتُمُوهُ مِنْهُما كَفاكُمُوهُ اَهْلُهُ.","persian":"کار نیک انجام دهید و هیچ نیکی‌ای را کوچک نشمارید؛ زیرا اندکش بزرگ و کمش بسیار است. هیچ‌یک از شما نگوید دیگری برای نیکوکاری از من سزاوارتر است؛ به خدا سوگند، چنین خواهد شد. نیکی و بدی هرکدام مردمانی دارند؛ اگر شما کاری را رها کنید، اهل آن به جای شما انجامش می‌دهند.","audio":null},{"id":"h423","kind":"hikmat","number":423,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ اَصْلَحَ سَريرَتَهُ اَصْلَحَ اللّهُ عَلانِيَتَهُ. وَ مَنْ عَمِلَ لِدينِهِ اَحْسَنَ اللّهُ اَمْرَ دُنْياهُ. وَ مَنْ اَحْسَنَ فيما بَيْنَهُ وَ بَيْنَ اللّهِ اَحْسَنَ اللّهُ ما بَيْنَهُ وَ بَيْنَ النّاسِ.","persian":"هرکس باطنش را اصلاح کند، خداوند ظاهرش را اصلاح می‌کند؛ هرکس برای دینش کار کند، خداوند کار دنیایش را کفایت می‌کند؛ و هرکس رابطهٔ خود با خدا را نیکو سازد، خداوند رابطهٔ او با مردم را سامان می‌دهد.","audio":null},{"id":"h424","kind":"hikmat","number":424,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْحِلْمُ غِطاءٌ ساتِرٌ، وَالْعَقْلُ حُسامٌ قاطِعٌ، فَاسْتُرْ خَلَلَ خُلُقِكَ بِحِلْمِكَ، وَ قاتِلْ هَواكَ بِعَقْلِكَ.","persian":"بردباری پوششی است که عیب‌ها را می‌پوشاند، و عقل شمشیری برنده است؛ پس کاستی‌های اخلاقت را با بردباری بپوشان و با عقل خود به جنگ خواسته‌های نفست برو.","audio":null},{"id":"h425","kind":"hikmat","number":425,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِلّهِ عِباداً يَخْتَصُّهُمُ اللّهُ بِالنِّعَمِ لِمَنافِع ِ الْعِبادِ، فَيُقِرُّها فى اَيْديهِمْ ما بَذَلُوها، فَاِذا مَنَعُوها نَزَعَها مِنْهُمْ ثُمَّ حَوَّلَها اِلى غَيْرِهِمْ.","persian":"خداوند بندگانی دارد که نعمت‌هایی را برای سود رساندن به دیگر بندگان به آنان می‌سپارد. تا وقتی می‌بخشند، آن نعمت‌ها را در دستشان نگه می‌دارد؛ و چون از بخشش دست بکشند، نعمت‌ها را از آنان می‌گیرد و به دیگران می‌سپارد.","audio":null},{"id":"h426","kind":"hikmat","number":426,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لايَنْبَغى لِلْعَبْدِ اَنْ يَثِقَ بِخَصْلَتَيْنِ: الْعافِيَةِ وَ الْغِنى، بَيْنا تَراهُ مُعافًى اِذْ سَقِمَ، وَ بَيْنا تَراهُ غَنِيّاً اِذِ افْتَقَرَ.","persian":"هیچ بنده‌ای نباید بر دو چیز تکیه کند: تندرستی و توانگری؛ زیرا ممکن است کسی را سالم ببینی و ناگهان بیمار شود، یا توانگر ببینی و ناگهان فقیر گردد.","audio":null},{"id":"h427","kind":"hikmat","number":427,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ شَكَا الْحاجَةَ اِلى مُؤْمِن فَكَاَنَّهُ شَكاها اِلَى اللّهِ، وَ مَنْ شَكاها اِلى كافِر فَكاَنَّما شَكَا اللّهَ.","persian":"هرکس نیازش را نزد مؤمنی در میان بگذارد، گویی آن را نزد خدا گفته است؛ و هرکس از نیاز خود نزد کافری شکایت کند، گویی از خدا شکایت کرده است.","audio":null},{"id":"h428","kind":"hikmat","number":428,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى بَعْضِ الاَْعْيادِ: اِنَّما هُوَ عيدٌ لِمَنْ قَبِلَ اللّهُ صِيامَهُ وَ شَكَرَ قِيامَهُ، وَ كُلُّ يَوْم لايُعْصَى اللّهُ فيهِ فَهُوَ يَوْمُ عيد.","persian":"امام در یکی از روزهای عید فرمود: «عید، روز کسی است که خدا روزه‌اش را پذیرفته و عبادتش را سپاس گفته است؛ و هر روزی که در آن نافرمانی خدا نشود، عید است.»","audio":null},{"id":"h429","kind":"hikmat","number":429,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اَعْظَمَ الْحَسَراتِ يَوْمَ الْقِيامَةِ حَسْرَةُ رَجُل كَسَبَ مالاً فى غَيْرِ طاعَةِ اللّهِ، فَوَرِثَهُ رَجُلٌ فَاَنْفَقَهُ فى طاعَةِ اللّهِ سُبْحانَهُ، فَدَخَلَ بِهِ الْجَنَّةَ، وَ دَخَلَ الاَْوَّلُ بِهِ النّارَ.","persian":"از بزرگ‌ترین حسرت‌های روز قیامت، حسرت کسی است که مالی را از راه نافرمانی خدا گرد آورده و به دیگری ارث رسانده است؛ وارث آن را در راه فرمان‌برداری خدا خرج می‌کند و به سبب آن به بهشت می‌رود، اما گردآورندهٔ نخستین به‌سبب همان مال وارد آتش می‌شود.","audio":null},{"id":"h430","kind":"hikmat","number":430,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اَخْسَرَ النّاسِ صَفْقَةً، وَ اَخْيَبَهُمْ سَعْياً رَجُلٌ اَخْلَقَ بَدَنَهُ فى طَلَبِ آمالِهِ، وَ لَمْ تُساعِدْهُ الْمَقاديرُ عَلى اِرادَتِهِ، فَخَرَجَ مِنَ الدُّنْيا بِحَسْرَتِهِ، وَ قَدِمَ عَلَى الاْخِرَةِ بِتَبِعَتِهِ.","persian":"زیان‌دیده‌ترین مردم در معامله و نومیدترینشان در کوشش، کسی است که تنش را در پی آرزوهای خود فرسوده، اما تقدیر با خواسته‌اش همراه نشده باشد؛ در نتیجه با حسرت از دنیا می‌رود و با بار مسئولیت و گناه به آخرت وارد می‌شود.","audio":null},{"id":"h431","kind":"hikmat","number":431,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الرِّزْقُ رِزْقانِ: طالِبٌ وَ مَطْلُوبٌ، فَمَنْ طَلَبَ الدُّنْيا طَلَبَهُ الْمَوْتُ حَتّى يُخْرِجَهُ عَنْها، وَ مَنْ طَلَبَ الاْخِرَةَ طَلَبَتْهُ الدُّنْيا حَتّى يَسْتَوْفِىَ رِزْقَهُ مِنْها.","persian":"روزی دو گونه است: روزی‌ای که در جست‌وجوی توست و روزی‌ای که تو در جست‌وجوی آنی. هرکس دنیا را بجوید، مرگ به دنبالش می‌آید تا او را از آن بیرون ببرد؛ و هرکس آخرت را بخواهد، دنیا به دنبالش می‌آید تا روزی‌اش را به‌تمامی دریافت کند.","audio":null},{"id":"h432","kind":"hikmat","number":432,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ اَوْلِياءَ اللّهِ هُمُ الَّذينَ نَظَرُوا اِلى باطِنِ الدُّنْيا اِذا نَظَرَ النّاسُ اِلى ظاهِرِها، وَ اشْتَغَلُوا بِآجِلِها اِذَا اشْتَغَلَ النّاسُ بِعاجِلِها، فَاَماتُوا مِنْها ما خَشُوا اَنْ يُميتَهُمْ، وَ تَرَكُوا مِنْها ما عَلِمُوا اَنَّهُ سَيَتْرُكُهُمْ، وَ رَاَوُا اسْتِكْثارَ غَيْرِهِمْ مِنْهَا اسْتِقْلالاً، وَ دَرَكَهُمْ لَها فَوْتاً. اَعْداءُ ما سالَمَ النّاسُ، وَ سِلْمُ ما عادَى النّاسُ. بِهِمْ عُلِمَ الْكِتابُ وَ بِهِ عَلِمُوا، وَ بِهِمْ قامَ الْكِتابُ وَ بِهِ قامُوا. لايَرَوْنَ مَرْجُوّاً فَوْقَ ما يَرْجُونَ، وَلا مَخُوفاً فَوْقَ ما يَخافُونَ.","persian":"دوستان خدا کسانی‌اند که به باطن دنیا نگاه می‌کنند، درحالی‌که دیگران به ظاهر آن می‌نگرند؛ و به سرانجام دنیا می‌اندیشند، درحالی‌که دیگران درگیر اکنون آن‌اند. آنچه را می‌ترسند روزی آنان را نابود کند، در دل خود می‌میرانند؛ و آنچه را می‌دانند روزی رهایشان خواهد کرد، خود رها می‌کنند. گردآوری مال به دست دیگران را ناچیز می‌شمرند و دست یافتن به دنیا را گونه‌ای از دست دادن می‌دانند. با آنچه مردم دوستش دارند دشمن‌اند و با آنچه مردم دشمن می‌دارند، آشتی‌اند. کتاب خدا به وسیلهٔ آنان شناخته می‌شود و خود آنان نیز با آن شناخته می‌شوند؛ کتاب به آنان برپاست و آنان به کتاب. امیدی بالاتر از آنچه امید می‌بندند و بیمی بزرگ‌تر از آنچه از آن می‌ترسند نمی‌بینند.","audio":null},{"id":"h433","kind":"hikmat","number":433,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اُذْكُرُوا انْقِطاعَ اللَّذّاتِ وَ بَقاءَ التَّبِعاتِ.","persian":"پایان یافتن لذت‌ها و باقی ماندن پیامدهای گناهان را به یاد آورید.","audio":null},{"id":"h434","kind":"hikmat","number":434,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اُخْبُرْ تَقْلِهِ.","persian":"بیازمای تا حقیقت او را بشناسی و چه‌بسا از او بیزار شوی.","audio":null},{"id":"h435","kind":"hikmat","number":435,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما كانَ اللّهُ لِيَفْتَحَ عَلى عَبْد بابَ الشُّكْرِ وَ يُغْلِقَ عَنْهُ بابَ الزِّيادَةِ، وَلا لِيَفْتَحَ عَلى عَبْد بابَ الدُّعاءِ وَ يُغْلِقَ عَنْهُ بابَ الاِْجابَةِ، وَلا لِيَفْتَحَ عَلى عَبْد بابَ التَّوْبَةِ وَ يُغْلِقَ عَنْهُ بابَ الْمَغْفِرَةِ.","persian":"چنین نیست که خدا درِ سپاسگزاری را به روی بنده‌ای بگشاید و درِ افزایش نعمت را ببندد؛ یا درِ دعا را باز کند و درِ اجابت را ببندد؛ یا درِ توبه را باز کند و درِ آمرزش را بسته نگه دارد.","audio":null},{"id":"h436","kind":"hikmat","number":436,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَوْلَى النّاسِ بِالْكَرَمِ مَنْ عَرَّقَتْ فيهِ الْكِرامُ.","persian":"سزاوارترین مردم به بزرگواری، کسی است که بزرگ‌منشی در خاندانش ریشه‌دار باشد.","audio":null},{"id":"h437","kind":"hikmat","number":437,"arabic":"وَ سُئِلَ عَلَيْهِ السَّلامُ: اَيُّما اَفْضَلُ، الْعَدْلُ اَوِ الْجُودُ؟ فَقالَ عَلَيْهِ السَّلامُ: الْعَدْلُ يَضَعُ الاُْمُورَ مَواضِعَها، وَالْجُودُ يُخْرِجُها مِنْ جِهَتِها. وَالْعَدْلُ سائِسٌ عامٌّ، وَالْجُودُ عارِضٌ خاصٌّ. فَالْعَدْلُ اَشْرَفُهُما وَ اَفْضَلُهُما.","persian":"از امام پرسیدند: «عدالت برتر است یا بخشندگی؟» فرمود: «عدالت، هر چیز را در جای خود می‌نهد؛ اما بخشندگی، آن را از جای خود بیرون می‌برد. عدالت تدبیرگر و سودمند برای همگان است و بخشندگی سودی ویژه به گروهی می‌رساند. پس عدالت ارجمندتر و برتر است.»","audio":null},{"id":"h438","kind":"hikmat","number":438,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: النّاسُ اَعْداءُ ما جَهِلُوا.","persian":"مردم دشمن چیزی هستند که آن را نمی‌شناسند.","audio":null},{"id":"h439","kind":"hikmat","number":439,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الزُّهْدُ كُلُّهُ بَيْنَ كَلِمَتَيْنِ مِنَ الْقُرْآنِ: قالَ اللّهُ سُبْحانَهُ: «لِكَيْلا تَأْسَوْا عَلى ما فاتَكُمْ، وَلاتَفْرَحُوا بِما آتاكُمْ». وَ مَنْ لَمْ يَأْسَ عَلَى الْماضى، وَ لَمْ يَفْرَحْ بِالاْتى فَقَدْ اَخَذَ الزُّهْدَ بِطَرَفَيْهِ.","persian":"تمام زهد در دو عبارت قرآن جمع شده است. خداوند سبحان فرموده است: «تا بر آنچه از دستتان رفته اندوه نخورید و به آنچه به شما داده است شادمان و مغرور نشوید.» پس کسی که بر گذشته افسوس نخورد و به آنچه نصیبش شده دلبسته و سرمست نشود، هر دو سوی زهد را دریافته است.","audio":null},{"id":"h440","kind":"hikmat","number":440,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما اَنْقَضَ النَّوْمَ لِعَزائِمِ الْيَوْمِ!","persian":"چه بسیار خواب که تصمیم‌های روز را درهم می‌شکند!","audio":null},{"id":"h441","kind":"hikmat","number":441,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْوِلاياتُ مَضاميرُ الرِّجالِ.","persian":"منصب‌ها میدان آزمون مردمان‌اند.","audio":null},{"id":"h442","kind":"hikmat","number":442,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لَيْسَ بَلَدٌ بِاَحَقَّ بِكَ مِنْ بَلَد، خَيْرُ الْبِلادِ ما حَمَلَكَ.","persian":"هیچ شهری ذاتاً برای تو شایسته‌تر از شهر دیگر نیست؛ بهترین شهر برای تو آن است که تو را بپذیرد و در آن آسوده باشی.","audio":null},{"id":"h443","kind":"hikmat","number":443,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ، وَ قَدْ جاءَهُ نَعْىُ الاَْشْتَرِ رَحِمَهُ اللّهُ: مالِكٌ وَ ما مالِكٌ! وَاللّهِ لَوْ كانَ جَبَلاً لَكانَ فِنْداً، وَ لَوْ كانَ حَجَراً لَكانَ صَلْداً، لايَرْتَقيهِ الْحافِرُ، وَلايُوفى عَلَيْهِ الطّائِرُ.","persian":"چون خبر درگذشت مالک اشتر به امام رسید، فرمود: «مالک! و چه کسی بود مالک! به خدا سوگند اگر کوه بود، کوهی بلند و یگانه بود؛ و اگر سنگ بود، سنگی سخت و استوار. هیچ سواری به بلندی او نمی‌رسید و هیچ پرنده‌ای بر فرازش پرواز نمی‌کرد.»","audio":null},{"id":"h444","kind":"hikmat","number":444,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: قَليلٌ مَدُومٌ عَلَيْهِ خَيْرٌ مِنْ كَثير مَمْلُول مِنْهُ.","persian":"کار اندکی که بر آن مداومت شود، بهتر از کار فراوانی است که انسان از آن خسته گردد.","audio":null},{"id":"h445","kind":"hikmat","number":445,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذا كانَ فى رَجُل خَلَّةٌ رائِقَةٌ فَانْتَظِرُوا اَخَواتِها.","persian":"هرگاه در کسی خصلتی پسندیده دیدید، چشم‌به‌راه خصلت‌های پسندیدهٔ دیگر او نیز باشید.","audio":null},{"id":"h446","kind":"hikmat","number":446,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِغالِبِ بْنِ صَعْصَعَةَ اَبِى الْفَرَزْدَقِ فى كَلام دارَ بَيْنَهُما: ما فَعَلَتْ اِبِلُكَ الْكَثيرَةُ؟ قالَ: ذَعْذَعَتْهَا الْحُقُوقُ يا اَميرَ الْمُؤْمِنينَ. فَقالَ عَلَيْهِ السَّلامُ: ذلِكَ اَحْمَدُ سُبُلِها.","persian":"امام به غالب بن صعصعه، پدر فرزدق، دربارهٔ شتران فراوانش پرسید. او گفت: «پرداخت حقوق خدا آن‌ها را پراکنده کرد، ای امیر مؤمنان.» امام فرمود: «این بهترین و ستوده‌ترین گونهٔ پراکنده شدن مال است.»","audio":null},{"id":"h447","kind":"hikmat","number":447,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنِ اتَّجَرَ بِغَيْرِ فِقْه فَقَدِارْتَطَمَ فِى الرِّبا.","persian":"هرکس بی‌آنکه احکام تجارت را بداند دادوستد کند، در ربا فرو می‌رود.","audio":null},{"id":"h448","kind":"hikmat","number":448,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ عَظَّمَ صِغارَ الْمَصائِبِ ابْتَلاهُ اللّهُ بِكِبارِها.","persian":"هرکس مصیبت‌های کوچک را بزرگ بشمارد، خداوند او را به مصیبت‌های بزرگ گرفتار می‌سازد.","audio":null},{"id":"h449","kind":"hikmat","number":449,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْ كَرُمَتْ عَلَيْهِ نَفْسُهُ هانَتْ عَلَيْهِ شَهَواتُهُ.","persian":"هرکس کرامت خویش را ارزشمند بداند، خواهش‌های نفسانی در نظرش خوار می‌شود.","audio":null},{"id":"h450","kind":"hikmat","number":450,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما مَزَحَ امْرُؤٌ مَزْحَةً اِلاّ مَجَّ مِنْ عَقْلِهِ مَجَّةً.","persian":"هیچ‌کس شوخی نمی‌کند مگر آنکه پاره‌ای از عقل خویش را از دست می‌دهد.","audio":null},{"id":"h451","kind":"hikmat","number":451,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: زُهْدُكَ فى راغِب فيكَ نُقْصانُ حَظٍّ، وَ رَغْبَتُكَ فى زاهِد فيكَ ذُلُّ نَفْس.","persian":"بی‌رغبتی تو به کسی که به تو راغب است، کاستیِ بهره است؛ و رغبت تو به کسی که به تو بی‌اعتناست، خواری نفس است.","audio":null},{"id":"h452","kind":"hikmat","number":452,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْغِنى وَالْفَقْرُ بَعْدَ الْعَرْضِ عَلَى اللّهِ.","persian":"توانگری و تهیدستی واقعی پس از عرضه شدن اعمال بر خدا آشکار می‌شود.","audio":null},{"id":"h453","kind":"hikmat","number":453,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما زالَ الزُّبَيْرُ رَجُلاً مِنّا اَهْلَ الْبَيْتِ حَتّى نَشَاَ ابْنُهُ الْمَشْؤُومُ عَبْدُاللّهِ.","persian":"زبیر همچنان از ما اهل‌بیت بود تا آنکه فرزند ناخجسته‌اش عبدالله بزرگ شد.","audio":null},{"id":"h454","kind":"hikmat","number":454,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما لاِبْنِ آدَمَ وَالْفَخْرَ؟! اَوَّلُهُ نُطْفَةٌ، وَ آخِرُهُ جيفَةٌ، لايَرْزُقُ نَفْسَهُ، وَلايَدْفَعُ حَتْفَهُ!","persian":"فرزند آدم را با فخرفروشی چه کار؟ آغازش نطفه و پایانش مردار است؛ نه می‌تواند روزی خود را فراهم آورد و نه مرگ را از خود بازدارد.","audio":null},{"id":"h455","kind":"hikmat","number":455,"arabic":"وَ سُئِلَ عَنْ اَشْعَرِ الشُّعَراءِ، فَقالَ عَلَيْهِ السَّلامُ: اِنَّ الْقَوْمَ لَمْ يَجْرُوا فى حَلْبَة تُعْرَفُ الْغايَةُ عِنْدَ قَصَبَتِها، فَاِنْ كانَ وَلابُدَّ فَالْمَلِكُ الضِّلّيلُ.","persian":"از امام پرسیدند: «شاعرترین شاعران کیست؟» فرمود: «آنان در میدان مسابقه‌ای یکسان نتاخته‌اند که خط پایانش معلوم باشد و بتوان پیشتاز را شناخت؛ اما اگر ناچار به پاسخ باشیم، آن پادشاه گمراه است.» مقصود، امرؤالقَیس است.","audio":null},{"id":"h456","kind":"hikmat","number":456,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَلا حُرٌّ يَدَعُ هذِهِ اللُّماظَةَ لاَِهْلِها؟! اِنَّهُ لَيْسَ لاَِنْفُسِكُمْ ثَمَنٌ اِلاَّ الْجَنَّةَ، فَلاتَبيعُوها اِلاّ بِها.","persian":"آیا آزاده‌ای نیست که این ته‌ماندهٔ دنیا را به اهلش واگذارد؟ آگاه باشید که بهای جان‌های شما چیزی جز بهشت نیست؛ پس آن‌ها را جز در برابر بهشت نفروشید.","audio":null},{"id":"h457","kind":"hikmat","number":457,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَنْهُومانِ لايَشْبَعانِ: طالِبُ عِلْم وَ طالِبُ دُنْيا.","persian":"دو حریص هرگز سیر نمی‌شوند: جویندهٔ دانش و جویندهٔ دنیا.","audio":null},{"id":"h458","kind":"hikmat","number":458,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: عَلامَةُ الاْيمانِ اَنْ تُؤْثِرَ الصِّدْقَ حَيْثُ يَضُرُّكَ عَلَى الْكَذِبِ حَيْثُ يَنْفَعُكَ، وَ اَنْ لايَكُونَ فى حَديثِكَ فَضْلٌ عَنْ عَمَلِكَ، وَ اَنْ تَتَّقِىَ اللّهَ فى حَديثِ غَيْرِكَ.","persian":"نشانهٔ ایمان آن است که راستی را، هرچند به زیانت باشد، بر دروغی که به سودت است ترجیح دهی؛ سخنت از کردارت بیشتر نباشد و هنگام سخن گفتن دربارهٔ دیگری از خدا پروا کنی.","audio":null},{"id":"h459","kind":"hikmat","number":459,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَغْلِبُ الْمِقْدارُ عَلَى التَّقْديرِ حَتّى تَكُونَ الاْفَةُ فِى التَّدْبيرِ.","persian":"تقدیر بر تدبیر چیره می‌شود، تا آنجا که گاه نابودی انسان در همان تدبیر اوست.","audio":null},{"id":"h460","kind":"hikmat","number":460,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْحِلْمُ وَ الاَْناةُ تَوْاَمانِ، يُنْتِجُهُما عُلُوُّ الْهِمَّةِ.","persian":"بردباری و آرامش در تصمیم‌گیری دو همزادند که از بلندهمتی پدید می‌آیند.","audio":null},{"id":"h461","kind":"hikmat","number":461,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْغيبَةُ جُهْدُ الْعاجِزِ.","persian":"غیبت کردن، نهایت کوشش ناتوان است.","audio":null},{"id":"h462","kind":"hikmat","number":462,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: رُبَّ مَفْتُون بِحُسْنِ الْقَوْلِ فيهِ.","persian":"چه‌بسا کسی که به‌سبب ستایشی که از او می‌شود، گرفتار فریب و آزمون گردد.","audio":null},{"id":"h463","kind":"hikmat","number":463,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الدُّنْيا خُلِقَتْ لِغَيْرِها وَ لَمْ تُخْلَقْ لِنَفْسِها.","persian":"دنیا برای چیزی جز خود آفریده شده است، نه برای آنکه خود هدف نهایی باشد.","audio":null},{"id":"h464","kind":"hikmat","number":464,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِنَّ لِبَنى اُمَيَّةَ مُرْوَداً يَجْرُونَ فيهِ، وَلَوْ قَدِ اخْتَلَفُوا فيما بَيْنَهُمْ ثُمَّ كادَتْهُمُ الضِّباعُ لَغَلَبَتْهُمْ.","persian":"بنی‌امیه مدتی مهلت دارند تا در میدان آن بتازند؛ اما اگر میانشان اختلاف افتد، حتی کفتارها هم اگر به آنان حمله کنند بر آن‌ها پیروز می‌شوند.","audio":null},{"id":"h465","kind":"hikmat","number":465,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى مَدْح ِ الاَْنْصارِ: هُمْ وَاللّهِ رَبَّوُا الاِْسْلامَ كَما يُرَبَّى الْفِلْوُ مَعَ غَنائِهِمْ، بِاَيْديهِمُ السِّباطِ، وَاَلْسِنَتِهِمُ السِّلاطِ.","persian":"امام در ستایش انصار فرمود: «به خدا سوگند، اسلام را همچون کره‌اسبی که پرورش می‌دهند به توانایی و استقلال رساندند؛ با دست‌های گشاده و زبان‌های برندهٔ خود.»","audio":null},{"id":"h466","kind":"hikmat","number":466,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْعَيْنُ وِكاءُ السَّهِ.","persian":"چشم، بندِ نگهدارندهٔ مخرج است.","audio":null},{"id":"h467","kind":"hikmat","number":467,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى كَلام لَهُ: وَ وَلِيَهُمْ وَال فَاَقامَ وَاسْتَقامَ حَتّى ضَرَبَ الدّينُ بِجِرانِهِ.","persian":"فرمانروایی بر آنان حکومت کرد، حق را برپا داشت و پایداری ورزید تا دین استوار شد.","audio":null},{"id":"h468","kind":"hikmat","number":468,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَأْتى عَلَى النّاسِ زَمانٌ عَضُوضٌ، يَعَضُّ الْمُوسِرُ فيهِ عَلى ما فى يَدَيْهِ وَ لَمْ يُؤْمَرْ بِذلِكَ، قالَ اللّهُ سُبْحانَهُ: «وَلاتَنْسَوُا الْفَضْلَ بَيْنَكُمْ». تَنْهَدُ فيهِ الاَْشْرارُ، وَ تُسْتَذَلُّ فيهِ الاَْخْيارُ، وَ يُبايِعُ الْمُضْطَرُّونَ وَ قَدْ نَهى رَسُولُ اللّهِ صَلَّى اللّهُ عَلَيْهِ وَ آلِهِ عَنْ بِيَع ِ الْمُضْطَرّينَ.","persian":"روزگاری سخت بر مردم خواهد آمد که توانگران اموال خود را سخت در چنگ می‌گیرند، درحالی‌که به چنین کاری فرمان نیافته‌اند. خداوند سبحان فرموده است: «نیکی و بخشش را در میان خود فراموش نکنید.» در آن روزگار بدکاران بالا می‌روند و نیکان خوار می‌شوند؛ نیازمندان از سر ناچاری دارایی خویش را می‌فروشند، با آنکه پیامبر خدا (ص) از معامله با کسانی که به اضطرار افتاده‌اند نهی کرده است.","audio":null},{"id":"h469","kind":"hikmat","number":469,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: يَهْلِكُ فِىَّ رَجُلانِ: مُحِبٌّ مُفْرِطٌ، وَ باهِتٌ مُفْتَر.","persian":"دو گروه دربارهٔ من به هلاکت می‌افتند: دوستی که در محبت زیاده‌روی کند و دشمنی که بهتان ببندد و افترا بزند.","audio":null},{"id":"h470","kind":"hikmat","number":470,"arabic":"وَ سُئِلَ عَلَيْهِ السَّلامُ عَنِ التَّوْحيدِ وَالْعَدْلِ، فَقالَ: التَّوْحيدُ اَنْ لاتَتَوَهَّمَهُ، وَالْعَدْلُ اَنْ لاتَتَّهِمَهُ.","persian":"از امام دربارهٔ توحید و عدالت پرسیدند. فرمود: «توحید آن است که خدا را در قالب خیال و وهم نگنجانی؛ و عدالت آن است که او را متهم نسازی.»","audio":null},{"id":"h471","kind":"hikmat","number":471,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: لاخَيْرَ فِى الصَّمْتِ عَنِ الْحُكْمِ، كَما اَنَّهُ لاخَيْرَ فِى الْقَوْلِ بِالْجَهْلِ.","persian":"سکوت در جایی که سخن حکیمانه لازم است سودی ندارد؛ چنان‌که سخن گفتن از روی نادانی نیز خیری ندارد.","audio":null},{"id":"h472","kind":"hikmat","number":472,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ فى دُعاء اسْتَسْقى بِهِ: اللّهُمَّ اسْقِنا ذُلُلَ السَّحابِ دُونَ صِعابِها.","persian":"امام در دعای باران فرمود: «خدایا، ما را با ابرهای رام و آرام سیراب کن، نه با ابرهای سرکش.»","audio":null},{"id":"h473","kind":"hikmat","number":473,"arabic":"وَ قيلَ لَهُ عَلَيْهِ السَّلامُ: لَوْ غَيَّرْتَ شَيْبَكَ يا اَميرَ الْمُؤْمِنينَ؟ فَقالَ: الْخِضابُ زينَةٌ وَ نَحْنُ قَوْمٌ فى مُصيبَة.","persian":"به امام گفتند: «ای امیر مؤمنان، چرا موی سپیدت را خضاب نمی‌کنی؟» فرمود: «خضاب زینت است و ما در سوگ به سر می‌بریم.»","audio":null},{"id":"h474","kind":"hikmat","number":474,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: مَا الْمُجاهِدُ الشَّهيدُ فى سَبيلِ اللّهِ بِاَعْظَمَ اَجْراً مِمَّنْ قَدَرَ فَعَفَّ. لَكادَ الْعَفيفُ اَنْ يَكُونَ مَلَكاً مِنَ الْمَلائِكَةِ.","persian":"پاداش مجاهدی که در راه خدا شهید شده، از پاداش کسی که توان انجام گناه دارد اما پاکدامنی پیش می‌گیرد بیشتر نیست؛ نزدیک است چنین پاکدامنی یکی از فرشتگان باشد.","audio":null},{"id":"h475","kind":"hikmat","number":475,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: الْقَناعَةُ مالٌ لايَنْفَدُ.","persian":"قناعت، ثروتی است که پایان نمی‌پذیرد.","audio":null},{"id":"h476","kind":"hikmat","number":476,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ لِزِيادِ بْنِ اَبيهِ، وَ قَدِ اسْتَخْلَفَهُ لِعَبْدِاللّهِ بْنِ الْعَبّاسِ عَلى فارِسَ وَ اَعْمالِها، فى كَلام طَويل كانَ بَيْنَهُما، نَهاهُ فيهِ عَنْ تَقَدُّمِ الْخَراج ِ: اسْتَعْمِلِ الْعَدْلَ، وَ احْذَرِ الْعَسْفَ وَالْحَيْفَ، فَاِنَّ الْعَسْفَ يَعُودُ بِالْجَلاءِ، وَالْحَيْفَ يَدْعُو اِلَى السَّيْفِ.","persian":"امام به زیاد بن ابیه، آن‌گاه که جانشین عبدالله بن عباس در فارس و نواحی آن بود و امام او را از گرفتن خراج پیش از موعد بازمی‌داشت، فرمود: «عدالت پیشه کن و از زورگویی و ستم بپرهیز؛ زیرا زورگویی مردم را به کوچ و آوارگی می‌کشاند و ستم، کار را به شمشیر و درگیری می‌رساند.»","audio":null},{"id":"h477","kind":"hikmat","number":477,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اَشَدُّ الذُّنُوبِ مَا اسْتَخَفَّ بِهِ صاحِبُهُ.","persian":"سنگین‌ترین گناه، گناهی است که صاحبش آن را ناچیز بشمارد.","audio":null},{"id":"h478","kind":"hikmat","number":478,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: ما اَخَذَ اللّهُ عَلى اَهْلِ الْجَهْلِ اَنْ يَتَعَلَّمُوا حَتّى اَخَذَ عَلى اَهْلِ الْعِلْمِ اَنْ يُعَلِّمُوا.","persian":"خداوند از نادانان پیمان آموختن نگرفت، مگر آنکه پیش از آن از دانایان پیمان آموزش دادن گرفته بود.","audio":null},{"id":"h479","kind":"hikmat","number":479,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: شَرُّ الاِْخْوانِ مَنْ تُكُلِّفَ لَهُ.","persian":"بدترین دوستان و برادران کسی است که آدمی برای معاشرت با او ناچار به تکلف و زحمت شود.","audio":null},{"id":"h480","kind":"hikmat","number":480,"arabic":"وَ قالَ عَلَيْهِ السَّلامُ: اِذَا احْتَشَمَ الْمُؤْمِنُ اَخاهُ فَقَدْ فارَقَهُ.","persian":"هرگاه مؤمنی برادر دینی خود را به خشم یا شرمندگی بیندازد، زمینهٔ جدایی از او را فراهم کرده است.","audio":null}];
